-- Canonical translations, consolidated with the existing winning values.
local _, addonTable = ...

local chat_rows = {
    [1000572642] = { ["english"] = { [1] = "Then, all you need to do is have a seat near the fire and soak it all in. After a few minutes of resting, you'll gain various boons that will help you in your travels." }, ["npcs"] = { [1] = "Raan Wildwind" }, ["priority"] = 3, ["text"] = "Тоді тобі лишається сісти біля вогню й насолодитися відпочинком. За кілька хвилин ти отримаєш різні благословення, які допоможуть у мандрах." },
    [1003578350] = { ["english"] = { [1] = "Let the executions begin!" }, ["npcs"] = { [1] = "Sandfury Executioner" }, ["priority"] = 1, ["text"] = "Нехай почнеться страта!" },
    [100592624] = { ["english"] = { [1] = "That is wonderous, Rimblat! Even this foul, sundered earth is not beyond healing." }, ["npcs"] = { [1] = "Rayne" }, ["priority"] = 1, ["text"] = "Це дивовижно, Рімблате! Навіть для такої нечистої й понівеченої землі ще є надія на зцілення." },
    [1007517259] = { ["english"] = { [1] = "If you fished as well as you talked the ocean wouldn't have any fish left." }, ["npcs"] = { [1] = "Adam" }, ["priority"] = 1, ["text"] = "Якби ти рибалив так само добре, як ти базікаєш, в океані не залишилося б риби." },
    [1016984614] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Move to the stairs and defend!" }, ["npcs"] = { [1] = "Crimson Gallant" }, ["priority"] = 1, ["text"] = "Рухайтеся до сходів і обороняйтеся!" }, [2] = { ["english"] = { [1] = "Move to the stairs and defend!" }, ["npcs"] = { [1] = "Crimson Guardsman" }, ["priority"] = 1, ["text"] = "Рухайтеся до сходів і обороняйтеся!" } }, ["english"] = { [1] = "Move to the stairs and defend!" }, ["npcs"] = { [1] = "Crimson Conjuror" }, ["priority"] = 1, ["text"] = "Рухайтеся до сходів і обороняйтеся!" },
    [1030129301] = { ["english"] = { [1] = "Who dares to challenge me in my domain?!" }, ["npcs"] = { [1] = "Araj the Summoner" }, ["priority"] = 1, ["text"] = "Хто посміє кинути мені виклик у моїх володіннях?!" },
    [103433419] = { ["english"] = { [1] = "The People of Westfall salute Roland, a brave and valiant defender of freedom." }, ["npcs"] = { [1] = "Gryan Stoutmantle" }, ["priority"] = 3, ["text"] = "Народ Західного краю вітає Роланда, хороброго й доблесного захисника свободи." },
    [1035160661] = { ["english"] = { [1] = "%s explodes and releases several Bile Slimes!" }, ["npcs"] = { [1] = "Bile Spewer" }, ["priority"] = 1, ["text"] = "%s вибухає і вивільняє жовчний слиз!" },
    [1036325904] = { ["english"] = { [1] = "And one time, at camp, I caught a fish that was bigger than I am!!" }, ["npcs"] = { [1] = "Billy" }, ["priority"] = 1, ["text"] = "А одного разу в таборі я зловив рибу, яка була більшою за мене самого!" },
    [1039135411] = { ["english"] = { [1] = "Attack!  For the Horde!" }, ["npcs"] = { [1] = "Krug Skullsplit" }, ["priority"] = 1, ["text"] = "В атаку! За Орду!" },
    [1040703516] = { ["english"] = { [1] = "There! Job's done." }, ["npcs"] = { [1] = "Chemist Cuely" }, ["priority"] = 1, ["text"] = "Ось так! Все готово." },
    [1043121982] = { ["english"] = { [1] = "Klaven doesn't pay me enough to deal with zombies, drones, or whatever he calls 'em." }, ["npcs"] = { [1] = "Defias Tower Patroller" }, ["priority"] = 1, ["text"] = "Клейвен не платить мені стільки, щоб я водилася з зомбі, чи мерцями, чи як він їх там називає." },
    [1046852679] = { ["english"] = { [1] = "Toil not in matters of the past, <name>!" }, ["npcs"] = { [1] = "Forlorn Spirit" }, ["priority"] = 3, ["text"] = "Не переймайся справами минулого, <name>!" },
    [1049450909] = { ["english"] = { [1] = "Hm...after dropping this off, I think I'll head to that cheese shop for a snack." }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Хм... після того, як віднесу це, певно, схожу до сирного за смаколиком." },
    [1050836932] = { ["english"] = { [1] = "Wow! We did it... not sure why we thought we needed the likes of you. Nevertheless, speak with Smeed Scrablescrew; he will give you your earnings!" }, ["npcs"] = { [1] = "Rigger Gizelton" }, ["priority"] = 1, ["text"] = "Вау! Ми впорались... Не знаю, нащо нам була твоя допомога... Та все ж поговори зі Смідом Гвинтодряпом — він віддасть тобі твій заробіток!" },
    [105112261] = { ["english"] = { [1] = "Scourge activity in the Plaguelands has increased ten-fold. We are receiving reports of Scourge attacks from as far away as Kalimdor! Now how do you suppose this has happened? How have the wretched undead done that which was previously thought impossible? Is nowhere safe?" }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Активність Скари в Зачумлених землях зросла в десятки разів. Ми отримуємо повідомлення про їх напади аж із Калімдору! Як же, на вашу думку, це сталося? Як ці кляті невмерлі зробили те, що раніше ми вважали неможливим? Невже ніде не залишилося безпечних місць?" },
    [1052886018] = { ["english"] = { [1] = "Your reign of terror ends now!  Face your doom mortals!" }, ["npcs"] = { [1] = "Ambassador Flamelash" }, ["priority"] = 1, ["text"] = "Вашій тиранії кінець! Прийміть свою загибель, смертні!" },
    [1054177436] = { ["english"] = { [1] = "%s becomes enraged!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s лютує!" },
    [1054392535] = { ["english"] = { [1] = "Crybaby! Crybaby!" }, ["npcs"] = { [1] = "William" }, ["priority"] = 1, ["text"] = "Плакса! Плакса!" },
    [1055970849] = { ["english"] = { [1] = "Run while you still can!" }, ["npcs"] = { [1] = "Grand Widow Faerlina" }, ["priority"] = 1, ["text"] = "Біжіть, поки ще можете!" },
    [1056241744] = { ["english"] = { [1] = "The Scourge beckons you, foolish <race>." }, ["npcs"] = { [1] = "Cauldron Lord Razarch" }, ["priority"] = 1, ["text"] = "Скара кличе тебе, {стать:дурний:дурна} {раса:к}.#foolish <race>." },
    [1057780043] = { ["english"] = { [1] = "Crush!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Трощити!" },
    [1065318059] = { ["english"] = { [1] = "<name>! I'm watching you!" }, ["npcs"] = { [1] = "Bloodlord Mandokir" }, ["priority"] = 1, ["text"] = "{Ім'я}! Я стежу за тобою!#<name>! I'm" },
    [1068079626] = { ["english"] = { [1] = "%s performs one last service for Ragnaros..." }, ["npcs"] = { [1] = "Baron Geddon" }, ["priority"] = 1, ["text"] = "%s виконує останнє доручення Раґнароса..." },
    [1070781923] = { ["english"] = { [1] = "%s shakes his head in disappointment." }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "%s похитує головою від розчарування." },
    [1070998807] = { ["english"] = { [1] = "Too little, too late. The dam has broken. We are a bump in the road at best." }, ["npcs"] = { [1] = "Scarlet Commander Marjhan" }, ["priority"] = 1, ["text"] = "Занадто мало, та й запізно. Скару вже не зупинити. В кращому випадку ми їх лише затримаємо." },
    [1071394456] = { ["english"] = { [1] = "The meddling of your order will hasten our doom!" }, ["npcs"] = { [1] = "Windshaper Novice Seer" }, ["priority"] = 3, ["text"] = "Втручання твого ордену лише наблизить нашу загибель!" },
    [1075712578] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Broke both me legs that night. How could I forget?" }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Зламав обидві ноги тієї ночі. Як я міг таке забути?" } }, ["english"] = { [1] = "Broke both me legs that night. How could I forget?" }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Зламав обидві ноги тієї ночі. Як я міг таке забути?" },
    [1082533495] = { ["english"] = { [1] = "Impudent whelps! You've rushed headlong to your own deaths! See now, the master stirs!" }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Нахабні виродки! Ви кинулися стрімголов назустріч власній смерті! Готуйтесь, бо володар прокинувся!" },
    [1083908283] = { ["english"] = { [1] = "Ha! I'm more afraid that those old holes and gashes would burst that thing and I would be showered by the shrapnel!" }, ["npcs"] = { [1] = "Pilot Bellowfiz" }, ["priority"] = 3, ["text"] = "Ха! Я більше боюся, що ті старі дірки й пробоїни розірвуть цю штукенцію, а мене засипле уламками!" },
    [1085853588] = { ["english"] = { [1] = "*sigh* It's about time to check on the cemetery again-- I'll be back in a few minutes." }, ["npcs"] = { [1] = "Deathguard Bartholomew" }, ["priority"] = 1, ["text"] = "*зітхає* Пора знову оглянути кладовище... Я повернуся за кілька хвилин." },
    [1090112340] = { ["english"] = { [1] = "Read this tome I have placed before you, and speak the words aloud." }, ["npcs"] = { [1] = "Celebras the Redeemed" }, ["priority"] = 1, ["text"] = "Прочитай фоліант, що я поклав біля каменю, і промовляй слова вголос." },
    [1092151934] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What?  Such a small, frail thing beckons me?  I shall add your bones to my throne, <race>!!" }, ["npcs"] = { [1] = "Lord Skwol" }, ["priority"] = 1, ["text"] = "Що? Мене кличе така маленька, квола істота? Я прикрашу свій трон твоїми кістками, {раса:к}!!#throne, <race>!" }, [2] = { ["english"] = { [1] = "What?  Such a small, frail thing beckons me?  I shall add your bones to my throne, <race>!!" }, ["npcs"] = { [1] = "Prince Skaldrenox" }, ["priority"] = 1, ["text"] = "Що? Мене кличе така маленька, квола істота? Я прикрашу свій трон твоїми кістками, {раса:к}!!#throne, <race>!" } }, ["english"] = { [1] = "What?  Such a small, frail thing beckons me?  I shall add your bones to my throne, <race>!!" }, ["npcs"] = { [1] = "Baron Kazum" }, ["priority"] = 1, ["text"] = "Що? Мене кличе така маленька, квола істота? Я прикрашу свій трон твоїми кістками, {раса:к}!!#throne, <race>!" },
    [1092570404] = { ["english"] = { [1] = "I am unworthy, master!" }, ["npcs"] = { [1] = "Deathknight Understudy" }, ["priority"] = 1, ["text"] = "Я нічого не вартий, вчителю!" },
    [1096086202] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Remember when Danath gathered all the mercenaries of Stormwind together and we marched to fight at Nethergarde?" }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Пам'ятаєш, як Данат зібрав усіх найманців Штормовію і ми вирушили на битву до Підсвітньої Варти?" } }, ["english"] = { [1] = "Remember when Danath gathered all the mercenaries of Stormwind together and we marched to fight at Nethergarde?" }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Пам'ятаєш, як Данат зібрав усіх найманців Штормовію і ми вирушили на битву до Підсвітньої Варти?" },
    [1098267361] = { ["english"] = { [1] = "This <class> intrudes on our work! Die fool!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "{Раса:н} заважає нашій роботі! Здохни, нікчемо!#This <class> intrudes" },
    [1100997069] = { ["english"] = { [1] = "Well, whatever it is, it works quite well!" }, ["npcs"] = { [1] = "Donova Snowden" }, ["priority"] = 1, ["text"] = "Ну, що б це не було, працює воно досить добре!" },
    [1105735521] = { ["english"] = { [1] = "I'll crush you!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Я тебе розчавлю!" },
    [1106092425] = { ["english"] = { [1] = "I sentence you to death!" }, ["npcs"] = { [1] = "Battleguard Sartura" }, ["priority"] = 1, ["text"] = "Я засуджую вас до смерті!" },
    [1108746048] = { ["english"] = { [1] = "Stormpike soldiers, aid and protect us! The Forest Lord has granted us his protection. The gateway must now be opened!" }, ["npcs"] = { [1] = "Arch Druid Renferal" }, ["priority"] = 1, ["text"] = "Солдати Бурешпиля, допоможіть і захистіть нас! Повелитель лісу надасть нам свій захист. Тепер ми маємо відкрити браму!" },
    [1110621179] = { ["english"] = { [1] = "You threw last one, idiot. It's my turn." }, ["npcs"] = { [1] = "Blackhand Thug" }, ["priority"] = 1, ["text"] = "Ти кидав минулого разу, недоумок. Тепер моя черга." },
    [1113734037] = { ["english"] = { [1] = "No!  It can't be..." }, ["npcs"] = { [1] = "Bethor Iceshard" }, ["priority"] = 1, ["text"] = "Ні! Цього не може бути..." },
    [1115544638] = { ["english"] = { [1] = "Brave <class>, thank you for rescuing me! I am sure Marshal Marris will reward your kind deed, <name>." }, ["npcs"] = { [1] = "Corporal Keeshan" }, ["priority"] = 1, ["text"] = "Дякую за порятунок, {стать:хоробрий:хоробра} {клас:к}! Я впевнений, що маршал Марріс винагородить тебе за цей добрий вчинок.#Brave <class>, thank#deed, <name>." },
    [1117447247] = { ["english"] = { [1] = "I will not be lured from this place." }, ["npcs"] = { [1] = "Alzzin the Wildshaper" }, ["priority"] = 1, ["text"] = "Ви не виманите мене звідси." },
    [1120569929] = { ["english"] = { [1] = "We're almost there!" }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "Ми майже на місці!" },
    [1121391341] = { ["english"] = { [1] = "I... am... undone." }, ["npcs"] = { [1] = "Gothik the Harvester" }, ["priority"] = 1, ["text"] = "Я... знищений." },
    [1124539967] = { ["english"] = { [1] = "And STAY dead!" }, ["npcs"] = { [1] = "Mekgineer Thermaplugg" }, ["priority"] = 1, ["text"] = "І НЕ ВСТАВАЙ!" },
    [1134133542] = { ["english"] = { [1] = "Good luck, Brenda!" }, ["npcs"] = { [1] = "Yorus Barleybrew" }, ["priority"] = 3, ["text"] = "Щасти, Brenda!" },
    [1136680317] = { ["english"] = { [1] = "Who dares to approach this cauldron?  Taste my dark blade!" }, ["npcs"] = { [1] = "Cauldron Lord Malvinious" }, ["priority"] = 1, ["text"] = "Хто сміє наближатися до цього котла? Відчуй мій темний клинок!" },
    [1137814893] = { ["english"] = { [1] = "\"Khadgar's Mystical Journal, Volume 8.\" I think this is the one I wanted." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "\"Містичний записник Кадґара, том 8\". Думаю, це саме те, що я хотіла." },
    [1142311961] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Welcome to the Stockade!" }, ["npcs"] = { [1] = "Bruegal Ironknuckle" }, ["priority"] = 1, ["text"] = "Ласкаво просимо до в'язниці!" } }, ["english"] = { [1] = "Welcome to the Stockade!" }, ["npcs"] = { [1] = "Bazil Thredd" }, ["priority"] = 1, ["text"] = "Ласкаво просимо до в'язниці!" },
    [114378656] = { ["english"] = { [1] = "Only flesh and bone. Mortals are such easy prey..." }, ["npcs"] = { [1] = "Emperor Vek'lor" }, ["priority"] = 1, ["text"] = "Сама лише плоть і кістки. Смертні — такі легка здобич..." },
    [1146351847] = { ["english"] = { [1] = "Good... good, A-Me. A-Me good. Home. Find home." }, ["npcs"] = { [1] = "A-Me 01" }, ["priority"] = 1, ["text"] = "Хороша... хороша Е-Мі. Е-Мі хороша. Дім. Знайти дім." },
    [1149361862] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Your treachery only speeds your doom.  This world will fall to darkness!" }, ["npcs"] = { [1] = "Lord Skwol" }, ["priority"] = 1, ["text"] = "Твоє віроломство лише прискорить твою загибель. Цей світ порине у пітьму!" }, [2] = { ["english"] = { [1] = "Your treachery only speeds your doom.  This world will fall to darkness!" }, ["npcs"] = { [1] = "Prince Skaldrenox" }, ["priority"] = 1, ["text"] = "Твоє віроломство лише прискорить твою загибель. Цей світ порине у пітьму!" } }, ["english"] = { [1] = "Your treachery only speeds your doom.  This world will fall to darkness!" }, ["npcs"] = { [1] = "Baron Kazum" }, ["priority"] = 1, ["text"] = "Твоє віроломство лише прискорить твою загибель. Цей світ порине у пітьму!" },
    [1151222245] = { ["english"] = { [1] = "The Scourge have broken into the Bastion!  Redouble your efforts!  We must not fail!" }, ["npcs"] = { [1] = "Crimson Gallant" }, ["priority"] = 1, ["text"] = "Скара прорвалася до Бастіону! Посильте оборону! Ми не маємо права програти!" },
    [1153774846] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Tell the Warden this prison is ours now!" }, ["npcs"] = { [1] = "Bruegal Ironknuckle" }, ["priority"] = 1, ["text"] = "Скажіть наглядачу, що ця в'язниця тепер наша!" } }, ["english"] = { [1] = "Tell the Warden this prison is ours now!" }, ["npcs"] = { [1] = "Bazil Thredd" }, ["priority"] = 1, ["text"] = "Скажіть наглядачу, що ця в'язниця тепер наша!" },
    [1154610684] = { ["english"] = { [1] = "Come young one, sit with me." }, ["npcs"] = { [1] = "Rathiril Sunlance" }, ["priority"] = 3, ["text"] = "Підійди, юначе, сядь зі мною." },
    [1156867771] = { ["english"] = { [1] = "I need to pee." }, ["npcs"] = { [1] = "Gil" }, ["priority"] = 1, ["text"] = "Хочу пісяти." },
    [1159192658] = { ["english"] = { [1] = "Make yourself useful and help me out here!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Зроби хоч щось корисне і допоможи мені!" },
    [1161031934] = { ["english"] = { [1] = "Hold! I sense an evil presence... Undead!" }, ["npcs"] = { [1] = "Feero Ironhand" }, ["priority"] = 1, ["text"] = "Стій! Я відчуваю присутність зла... Невмерлі!" },
    [1164662096] = { ["english"] = { [1] = "Bloodscalp, Sandfury, Skullsplitter, Vilebranch and Witherbark. They all pledge their allegiance to Jin - their souls to Hakkar. You have lost." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Кровоскальпі, Піщанолюті, Черепотрощителі, Миршаве Гілля і Зів'яла Кора. Усі вони присягли на вірність Джину — їхні душі належать Гаккару. Ви програли." },
    [1165139213] = { ["english"] = { [1] = "I'm saved! Thank you, doctor!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Я врятований! Дякую, лікарю!" },
    [1166909719] = { ["english"] = { [1] = "Ancient ones guide my hand... Wake from your slumber! WAKE AND SEAL THIS CURSED PLACE!" }, ["npcs"] = { [1] = "Fandral Staghelm" }, ["priority"] = 1, ["text"] = "Древні, направте мої руки... Прокиньтесь від свого сну! ПРОКИНЬТЕСЬ І ЗАПЕЧАТАЙТЕ ЦЕ ПРОКЛЯТЕ МІСЦЕ!" },
    [1169390528] = { ["english"] = { [1] = "Where are your Gods now? WHERE, SERVITOR?" }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Де тепер твої Боги? ДЕ, СЛУГО?" },
    [1175933178] = { ["english"] = { [1] = "%s takes in a deep breath..." }, ["npcs"] = { [1] = "Onyxia" }, ["priority"] = 1, ["text"] = "%s робить глибокий вдих..." },
    [1178790997] = { ["english"] = { [1] = "Aonda is a good woman, and true servant of Zephras Isle. It is my hope that you can quickly earn her trust and help her to keep Shen'dar Village safe. May the winds guide you, <name>." }, ["npcs"] = { [1] = "Aetheen of the Gales" }, ["priority"] = 3, ["text"] = "Аонда — добра жінка й вірна служниця острова Зефрас. Сподіваюся, ти швидко заслужиш її довіру й допоможеш їй берегти селище Шен'дар. Нехай вітри ведуть тебе, {ім'я:к}." },
    [1180688703] = { ["english"] = { [1] = "%s flee as the controlling power of the orb is drained." }, ["npcs"] = { [1] = "Nefarian's Troops" }, ["priority"] = 1, ["text"] = "%s втікають, коли сила сфери домінування вичерпується." },
    [1181122061] = { ["english"] = { [1] = "Trogg incursion! Defend me while I blast the hole closed!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Це троги! Прикрийте мене, поки я закладаю вибухівку!" },
    [1184620804] = { ["english"] = { [1] = "Hey Reese, give me an' Christoph another round." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Гей, Різз! Нам з Крістофом ще по одній." },
    [1186015685] = { ["english"] = { [1] = "%s loosens her grasp on the journal she had been clutching." }, ["npcs"] = { [1] = "Jandice Barov" }, ["priority"] = 1, ["text"] = "%s випускає щоденник, який вона стискала в руці." },
    [119077835] = { ["english"] = { [1] = "Come, little ones. Face me!" }, ["npcs"] = { [1] = "Azuregos" }, ["priority"] = 1, ["text"] = "Підходьте, малята. Відчуйте мій гнів!" },
    [119466824] = { ["english"] = { [1] = "Thank you! Thank you, <priest/priestess>. Now I can take on those corrupt timberlings with Elune's power behind me!" }, ["npcs"] = { [1] = "Sentinel Shaya" }, ["priority"] = 1, ["text"] = "Дякую! Щиро дякую, {стать:жерцю:жрице}. Завдяки тобі я знову зможу зайнятись цими оскверненими деревниками!" },
    [1195980826] = { ["english"] = { [1] = "Yes, yes. Hmm, it seems to cross reference another tome. Guess I have to find that one too." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Так, так. Хм, здається, це посилання на інший том. Певно, доведеться знайти і його." },
    [1199051485] = { ["english"] = { [1] = "Give of your hearts and your purses! Give to the children of Stormwind who have lost their parents." }, ["npcs"] = { [1] = "John Turner" }, ["priority"] = 1, ["text"] = "Не шкодуйте ні сердець, ні гаманців! Допоможіть дітям Штормовію, які втратили батьків." },
    [1199778238] = { ["english"] = { [1] = "Today you have unmade what took me years to create! For this you shall all die by my hand!" }, ["npcs"] = { [1] = "Grand Crusader Dathrohan" }, ["priority"] = 1, ["text"] = "Ви знищили те, що я створював роками! За це ви всі загинете від моєї руки!" },
    [1200914664] = { ["english"] = { [1] = "My forces cannot overcome the Qiraji defenses. We will not be able to get close enough to place your precious barrier, dragon." }, ["npcs"] = { [1] = "Fandral Staghelm" }, ["priority"] = 1, ["text"] = "Мої сили не можуть подолати оборону кіражів. Ми не зможемо підібратись достатньо близько, щоб встановити твій бар'єр, драконе." },
    [120490661] = { ["english"] = { [1] = "Gah... Youths!" }, ["npcs"] = { [1] = "Rorian the Dayseeker" }, ["priority"] = 3, ["text"] = "Гах... Молодь!" },
    [1208492961] = { ["english"] = { [1] = "Prepare to die, <class> scum!" }, ["npcs"] = { [1] = "Dark Strand Assassin" }, ["priority"] = 1, ["text"] = "Готуйся здохнути, {стать:мерзенний:мерзенна} {клас:н}!#die, <class> scum" },
    [121018574] = { ["english"] = { [1] = "Thank you for these badges, <name>.  I will send news to the families of the deceased." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "Дякую за ці значки, {ім'я:к}. Я сповіщу родини загиблих.#badges, <name>." },
    [1212288730] = { ["english"] = { [1] = "Finally they show mercy!  They've given us something to drink!" }, ["npcs"] = { [1] = "Captured Farmer" }, ["priority"] = 1, ["text"] = "Нарешті вони проявили милосердя! Вони дали нам щось випити!" },
    [1216630075] = { ["english"] = { [1] = "Our new allies will avenge us!" }, ["npcs"] = { [1] = "Charlga Razorflank" }, ["priority"] = 1, ["text"] = "Наші нові союзники помстяться за нас!" },
    [1218157097] = { ["english"] = { [1] = "Don't hurt Betsy, you meanie!" }, ["npcs"] = { [1] = "Donna" }, ["priority"] = 1, ["text"] = "Не кривдь Бетсі, негідник!" },
    [1219469663] = { ["english"] = { [1] = "Incoming blast in 5 seconds. Clear the tunnel! Stay back!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Вибух через 5 секунд. Покиньте тунель! Назад!" },
    [1223070823] = { ["english"] = { [1] = "And if you do not, then I am truly lost." }, ["npcs"] = { [1] = "Annalise Lerent" }, ["priority"] = 1, ["text"] = "А якщо ні, то я дійсно втрачена навіки." },
    [1226784262] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "%s blood sprays into the air!" }, ["npcs"] = { [1] = "Irradiated Pillager" }, ["priority"] = 1, ["text"] = "%s забризкує все навколо кров'ю!" } }, ["english"] = { [1] = "%s blood sprays into the air!" }, ["npcs"] = { [1] = "Irradiated Invader" }, ["priority"] = 1, ["text"] = "%s забризкує все навколо кров'ю!" },
    [1228387305] = { ["english"] = { [1] = "I serve to the last!" }, ["npcs"] = { [1] = "Battleguard Sartura" }, ["priority"] = 1, ["text"] = "Я служу до кінця!" },
    [1232537635] = { ["english"] = { [1] = "I now return to whence I came, only to find myself here once more to relive the same epic tragedy." }, ["npcs"] = { [1] = "Eris Havenfire" }, ["priority"] = 1, ["text"] = "Тепер я повертаюсь туди, звідки прийшла, щоб знову опинитися тут і пережити цю жахливу трагедію." },
    [1238356432] = { ["english"] = { [1] = "Who dares to provoke the messenger of Edwin Van Cleef?  Die <race>!" }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "Хто насмілюється перешкоджати гінцю Едвіна Ван-Кліфа? Помри, {раса:к}!" },
    [1243705373] = { ["english"] = { [1] = "Free! Free from my bonds at last!" }, ["npcs"] = { [1] = "Zaetar's Spirit" }, ["priority"] = 1, ["text"] = "Свобода! Нарешті я вільний від цих пут!" },
    [1249399023] = { ["english"] = { [1] = "I've finally reached Lakeshire-- come one, come all, and take advantage of Antonio Perelli's wonderful deals." }, ["npcs"] = { [1] = "Antonio Perelli" }, ["priority"] = 1, ["text"] = "Нарешті я в Приозер'ї... Підходьте, скористайтеся чудовими пропозиціями від Антоніо Переллі." },
    [1250274903] = { ["english"] = { [1] = "Incredible!  I know he who wrought these enchantments..." }, ["npcs"] = { [1] = "Bethor Iceshard" }, ["priority"] = 1, ["text"] = "Неймовірно! Я знаю того, хто створив ці чари..." },
    [125159650] = { ["english"] = { [1] = "Be healed!" }, ["npcs"] = { [1] = "Eris Havenfire" }, ["priority"] = 1, ["text"] = "Зцілися!" },
    [1252767036] = { ["english"] = { [1] = "Too easy." }, ["npcs"] = { [1] = "Amnennar the Coldbringer" }, ["priority"] = 1, ["text"] = "Занадто легко." },
    [1254857525] = { ["english"] = { [1] = "%s goes into a rage!" }, ["npcs"] = { [1] = "Raging Agam'ar" }, ["priority"] = 1, ["text"] = "%s впадає в лють!" },
    [1258163037] = { ["english"] = { [1] = "I see you misplaced that chapter you worked so hard to put together, <name>. Well, you left it right here!" }, ["npcs"] = { [1] = "Barnil Stonepot" }, ["priority"] = 1, ["text"] = "Здається, тут розділи зібрані в неправильному порядку, {ім'я:к}. Ну нічого, залишай їх так, я розберусь!#put together, <name>." },
    [1260258193] = { ["english"] = { [1] = "Troublesome whelps. I'll teach you to interfere!" }, ["npcs"] = { [1] = "Charlga Razorflank" }, ["priority"] = 1, ["text"] = "Набридливі вилупки. Я покажу, що стається з тими, хто заважає нам!" },
    [1263462081] = { ["english"] = { [1] = "Thank you, <name>.  You have tempered the cold rage in my heart." }, ["npcs"] = { [1] = "Coleman Farthing" }, ["priority"] = 1, ["text"] = "Дякую тобі, {ім'я:к}. Ти {стать:вгамував:вгамувала} мою жагу помсти.#you, <name>." },
    [1263870715] = { ["english"] = { [1] = "Best drinks in Stormwind!" }, ["npcs"] = { [1] = "Erich Lohan" }, ["priority"] = 1, ["text"] = "Найкраща випивка у Штормовії!" },
    [1263936040] = { ["english"] = { [1] = "Who hath summoned forth Aman?" }, ["npcs"] = { [1] = "Aman" }, ["priority"] = 1, ["text"] = "Хто прикликав Амана?" },
    [1269776197] = { ["english"] = { [1] = "The light condemns all who harbor evil.  Now you will die!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Світло засуджує всіх, хто носить у собі зло. Тепер ти помреш!" },
    [1270987804] = { ["english"] = { [1] = "You there! Be careful! Your sacred shen'dorei gifts are not to be used for amusement!" }, ["npcs"] = { [1] = "Rorian the Dayseeker" }, ["priority"] = 3, ["text"] = "Гей, ти! Обережніше! Священні дари шен'дорай не для забави!" },
    [1273503923] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I still have the scars from that night." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "У мене досі залишилися шрами з тієї ночі." } }, ["english"] = { [1] = "I still have the scars from that night." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "У мене досі залишилися шрами з того дня." },
    [1279584609] = { ["english"] = { [1] = "I should have a few extra coins from this sale.  Maybe I'll buy myself some lunch..." }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Я отримаю за цю партію чимало грошей. Може, варто купити чогось смачного..." },
    [128165256] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The solution is ready in my cauldron.  It's just the matter of treating both the unfinished key and the scarab." }, ["npcs"] = { [1] = "Apothecary Dithers" }, ["priority"] = 1, ["text"] = "Розчин вже кипить у котлі. Залишилось лише обробити ним незавершений ключ і скарабея." } }, ["english"] = { [1] = "The solution is ready in my cauldron.  It's just the matter of treating both the unfinished key and the scarab." }, ["npcs"] = { [1] = "Alchemist Arbington" }, ["priority"] = 1, ["text"] = "Розчин вже кипить у котлі. Залишилось лише обробити ним незавершений ключ і скарабея." },
    [128204118] = { ["english"] = { [1] = "%s lowers the sound of his voice to a whisper." }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "%s переходить на шепіт." },
    [1284323713] = { ["english"] = { [1] = "Your deaths feed my strength!" }, ["npcs"] = { [1] = "Bloodlord Mandokir" }, ["priority"] = 1, ["text"] = "Ваші смерті наповнюють мене силою!" },
    [1285687110] = { ["english"] = { [1] = "The Stonewrought Dam will be destroyed!  Long live Ragnaros!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Ми знищимо Каменярську дамбу! Слава Раґнаросу!" },
    [1287473079] = { ["english"] = { [1] = "This is Rigger Gizelton asking for assistance escorting my caravan past Mannoroc Coven. I'm on the road east of Shadowprey village." }, ["npcs"] = { [1] = "Rigger Gizelton" }, ["priority"] = 1, ["text"] = "Агов! Я Монтер Ґізельтон, і мені потрібна допомога з супроводом мого каравану повз руїни Маннорок. Я стою на дорозі на схід від селища Тінездобич." },
    [1290937955] = { ["english"] = { [1] = "Our defenses are failing!  By the light we must prevail!" }, ["npcs"] = { [1] = "Crimson Gallant" }, ["priority"] = 1, ["text"] = "Наша оборона слабшає! Ми повинні перемогти, заради світла!" },
    [1291741744] = { ["english"] = { [1] = "Aye sure, just as long as we get to hit the arena right after!" }, ["npcs"] = { [1] = "Pilot Stonegear" }, ["priority"] = 3, ["text"] = "Аякже, тільки якщо одразу після цього підемо на арену!" },
    [1299224654] = { ["english"] = { [1] = "SQUAWK!!!" }, ["npcs"] = { [1] = "Polly" }, ["priority"] = 1, ["text"] = "КРРРАА!!!" },
    [1299706956] = { ["english"] = { [1] = "What have we here?  <name> the <class>?  Attack!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Що це тут в нас? {Ім'я:н}-{клас:н}? В атаку!#here?  <name> the#the <class>?  Attack" },
    [13046448] = { ["english"] = { [1] = "The children of Sul will protect their master. Rise once more Sul'lithuz!" }, ["npcs"] = { [1] = "Antu'sul" }, ["priority"] = 1, ["text"] = "Діти Сула захищатимуть свого господаря. Повстань, Сул'літуз!" },
    [1304928578] = { ["english"] = { [1] = "What was that?! Trey? TREY!?" }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Що це було?! Трей? ТРЕЙ?!" },
    [1305398727] = { ["english"] = { [1] = "Payment for those plans comes in bones - YOUR BONES!" }, ["npcs"] = { [1] = "Black Guard Swordsmith" }, ["priority"] = 1, ["text"] = "Ви заплатите за ці креслення СВОЇМИ КІСТКАМИ!" },
    [1310253280] = { ["english"] = { [1] = "Doomed... we are... doomed..." }, ["npcs"] = { [1] = "Windshaper Novice Seer" }, ["priority"] = 3, ["text"] = "Ми приречені... приречені..." },
    [1312180711] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Outsiders! Kill em all!" }, ["npcs"] = { [1] = "Bruegal Ironknuckle" }, ["priority"] = 1, ["text"] = "Чужинці! Вбийте їх всіх!" } }, ["english"] = { [1] = "Outsiders! Kill em all!" }, ["npcs"] = { [1] = "Bazil Thredd" }, ["priority"] = 1, ["text"] = "Чужинці! Вбийте їх всіх!" },
    [1313602369] = { ["english"] = { [1] = "Farewell, my friend." }, ["npcs"] = { [1] = "Bethor Iceshard" }, ["priority"] = 1, ["text"] = "До зустрічі, мій друже." },
    [1314457718] = { ["english"] = { [1] = "I have waited long enough. Now you face the harvester of souls." }, ["npcs"] = { [1] = "Gothik the Harvester" }, ["priority"] = 1, ["text"] = "Я довго цього чекав. Тепер ви зустрінетесь з женцем душ." },
    [1316916878] = { ["english"] = { [1] = "Now for that snack..." }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "А тепер за смаколиком..." },
    [1317393778] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Die, <race>!  These lands belong to the Stonesplinter Tribe!" }, ["npcs"] = { [1] = "Grawmug" }, ["priority"] = 1, ["text"] = "Помри, {раса:н}! Ці землі належать племені Каменедробів!#Die, <race>!" }, [2] = { ["english"] = { [1] = "Die, <race>!  These lands belong to the Stonesplinter Tribe!" }, ["npcs"] = { [1] = "Magosh" }, ["priority"] = 1, ["text"] = "Помри, {раса:н}! Ці землі належать племені Каменедробів!#Die, <race>!" } }, ["english"] = { [1] = "Die, <race>!  These lands belong to the Stonesplinter Tribe!" }, ["npcs"] = { [1] = "Boss Galgosh" }, ["priority"] = 1, ["text"] = "Помри, {раса:н}! Ці землі належать племені Каменедробів!#Die, <race>!" },
    [1318220478] = { ["english"] = { [1] = "Incoming blast in 10 seconds!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Вибух через 10 секунд!" },
    [132035702] = { ["english"] = { [1] = "This is unforseen.  The being who enchanted this is known to me..." }, ["npcs"] = { [1] = "Bethor Iceshard" }, ["priority"] = 1, ["text"] = "Цього я не очікував. Я знаю того, хто зачарував це..." },
    [1321832724] = { ["english"] = { [1] = "I don't know how it started, but it hardly matters now. We need to extinguish it!" }, ["npcs"] = { [1] = "Relathor Moonsong" }, ["priority"] = 1, ["text"] = "Я не знаю, як це почалося, але це й не має значення. Нам потрібно погасити це!" },
    [132504735] = { ["english"] = { [1] = "More troggs! Ward them off as I prepare the explosives!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Ще троги! Стримуйте їх, поки я готую вибухівку!" },
    [1330712792] = { ["english"] = { [1] = "I am not worthy, sir." }, ["npcs"] = { [1] = "Thomas Miller" }, ["priority"] = 1, ["text"] = "Я не гідний, пане." },
    [133210999] = { ["english"] = { [1] = "Almost done..." }, ["npcs"] = { [1] = "Apothecary Faustin" }, ["priority"] = 1, ["text"] = "Майже готово..." },
    [1336896242] = { ["english"] = { [1] = "Freshly baked bread for sale!" }, ["npcs"] = { [1] = "Thomas Miller" }, ["priority"] = 1, ["text"] = "Свіжоспечений хліб!" },
    [1350342203] = { ["english"] = { [1] = "And they're off!" }, ["npcs"] = { [1] = "Fobeed" }, ["priority"] = 1, ["text"] = "І вони рушили!" },
    [1350457698] = { ["english"] = { [1] = "It looks like we're in trouble. Look lively, here they come!" }, ["npcs"] = { [1] = "Feero Ironhand" }, ["priority"] = 1, ["text"] = "Здається, у нас неприємності. Будьте насторожі, вони вже тут!" },
    [1371594139] = { ["english"] = { [1] = "Begone, uncouth scum!  The Alliance shall prevail in Alterac Valley!" }, ["npcs"] = { [1] = "Captain Balinda Stonehearth" }, ["priority"] = 1, ["text"] = "Геть, неотесані виродки! Альянс здобуде перемогу в Альтерацькій долині!" },
    [1372962101] = { ["english"] = { [1] = "The living are here!" }, ["npcs"] = { [1] = "Eye of Naxxramas" }, ["priority"] = 1, ["text"] = "Тут живі!" },
    [1375653815] = { ["english"] = { [1] = "She'll have our heads if we're caught!" }, ["npcs"] = { [1] = "Theramore Sentry" }, ["priority"] = 1, ["text"] = "Вона нам голови знесе, якщо нас упіймають!" },
    [1379568606] = { ["english"] = { [1] = "Come, spirits - attend your master!" }, ["npcs"] = { [1] = "Amnennar the Coldbringer" }, ["priority"] = 1, ["text"] = "Прийдіть, духи — служіть своєму володарю!" },
    [1380063910] = { ["english"] = { [1] = "Keever is most pleased." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "Ківер дуже задоволений." },
    [1382444029] = { ["english"] = { [1] = "5 seconds until detonation!!!!!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "5 секунд до детонації!!!!!" },
    [1382835866] = { ["english"] = { [1] = "No rest... for the angry dead!" }, ["npcs"] = { [1] = "Bloodmage Thalnos" }, ["priority"] = 1, ["text"] = "Немає спокою... для розгніваних мерців!" },
    [1394470132] = { ["english"] = { [1] = "What am I paying you for? The kodos are nearly dead!" }, ["npcs"] = { [1] = "Rigger Gizelton" }, ["priority"] = 1, ["text"] = "За що я тобі плачу? Кодо ледь живі!" },
    [1395316306] = { ["english"] = { [1] = "Beware!  Beware!  A threat lurks in the wild!  Night Watchers, be on the alert!" }, ["npcs"] = { [1] = "Watcher Cutford" }, ["priority"] = 3, ["text"] = "Обережно! Обережно! У хащах причаїлася загроза! Нічна варто, будьте напоготові!" },
    [1398542489] = { ["english"] = { [1] = "%s's soft voice trails away into the mists, \"Know that I love you always...\"" }, ["npcs"] = { [1] = "Anaya" }, ["priority"] = 1, ["text"] = "%s розчиняється в імлі, лишаючи за собою лиш відлуння останніх слів: «Знай, що я завжди кохатиму тебе...»" },
    [1399803625] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "%s jumps out of the shadows!" }, ["npcs"] = { [1] = "Defias Blackguard" }, ["priority"] = 1, ["text"] = "%s вискакує з тіней!" } }, ["english"] = { [1] = "%s jumps out of the shadows!" }, ["npcs"] = { [1] = "Cat" }, ["priority"] = 1, ["text"] = "%s вискакує з тіней!" },
    [1401222207] = { ["english"] = { [1] = "Grom zugas maza kazum kazum ka dogg, <name>!" }, ["npcs"] = { [1] = "Dragonmaw Scout" }, ["priority"] = 3, ["text"] = "Grom zugas maza kazum kazum ka dogg, {ім'я:к}!" },
    [1401600312] = { ["english"] = { [1] = "Look at what <name> brought us!  Let's drink up!" }, ["npcs"] = { [1] = "Gnome Pit Boss" }, ["priority"] = 1, ["text"] = "Подивіться, що нам {стать:приніс:принесла} {ім'я:н}! Давайте вип'ємо!" },
    [1405592021] = { ["english"] = { [1] = "Nothing you can say will ever get me in the arena against that monstrosity of a machine you call a steam tank!" }, ["npcs"] = { [1] = "Pilot Bellowfiz" }, ["priority"] = 3, ["text"] = "Що б ти не казав, я нізащо не вийду на арену проти того чудовиська, яке ти називаєш паровим танком!" },
    [1406701728] = { ["english"] = { [1] = "Bob!  I'm finished!" }, ["npcs"] = { [1] = "Tormus Deepforge" }, ["priority"] = 3, ["text"] = "Бобе!  Я закінчив!" },
    [140899419] = { ["english"] = { [1] = "Long live the Dragonmaw! Die you worthless <race>!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Слава Драконовій Пащі! Помри, нікчемо!" },
    [1414866619] = { ["english"] = { [1] = "%s sets eyes on <name>!" }, ["npcs"] = { [1] = "Buru the Gorger" }, ["priority"] = 1, ["text"] = "%s спрямовує погляд на {ім'я:з}!#eyes on <name>!" },
    [1418160633] = { ["english"] = { [1] = "Who's next?" }, ["npcs"] = { [1] = "Charlga Razorflank" }, ["priority"] = 1, ["text"] = "Хто наступний?" },
    [1421583693] = { ["english"] = { [1] = "Ok, you had the fish platter, Commander. Enjoy!" }, ["npcs"] = { [1] = "Jessica Chambers" }, ["priority"] = 1, ["text"] = "Гаразд, ось ваша риба, командире. Смачного!" },
    [1423218468] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "A living <race>... soon to be a dead like me." }, ["npcs"] = { [1] = "Cursed Marine" }, ["priority"] = 1, ["text"] = "{стать:Живий:Жива} {раса:н}. Скоро будеш {стать:мертвий:мертва}, як і я.#living <race>..." }, [2] = { ["english"] = { [1] = "A living <race>... soon to be a dead like me." }, ["npcs"] = { [1] = "Cursed Sailor" }, ["priority"] = 1, ["text"] = "{стать:Живий:Жива} {раса:н}. Скоро будеш {стать:мертвий:мертва}, як і я.#living <race>..." } }, ["english"] = { [1] = "A living <race>... soon to be a dead like me." }, ["npcs"] = { [1] = "Captain Halyndor" }, ["priority"] = 1, ["text"] = "{стать:Живий:Жива} {раса:н}. Скоро будеш {стать:мертвий:мертва}, як і я.#living <race>..." },
    [1431918718] = { ["english"] = { [1] = "Well done Edward and Tyler. You are progressing along in your training quite nicely. We shall test your mettle again soon." }, ["npcs"] = { [1] = "Brother Malach" }, ["priority"] = 1, ["text"] = "Молодці, Едвард і Тайлер. Ви чудово просунулися у своєму навчанні. Скоро ми знову перевіримо ваші сили." },
    [1433094550] = { ["english"] = { [1] = "We are under siege!  To arms!  Kill this <target>!" }, ["npcs"] = { [1] = "Corporal Keeshan" }, ["priority"] = 1, ["text"] = "Нас атакують! До зброї!" },
    [1439989805] = { ["english"] = { [1] = "<name>, I have the information you seek..." }, ["npcs"] = { [1] = "Bethor Iceshard" }, ["priority"] = 1, ["text"] = "{ім'я:к}, у мене є інформація, що тебе зацікавить...#<name>, I have" },
    [1440953412] = { ["english"] = { [1] = "Let not even a drop of their blood remain upon the arena floor, my children. Feast on their souls!" }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Нехай жодної краплі їхньої крові не залишиться на арені, діти мої. Пожеріть їхні душі!" },
    [1442139528] = { ["english"] = { [1] = "The Scourge have broken through in all wings!  May the light defeat these foul creatures!  We shall fight to the last!" }, ["npcs"] = { [1] = "Crimson Gallant" }, ["priority"] = 1, ["text"] = "Скара прорвалася в усі зали! Нехай світло переможе цих мерзенних створінь! Ми будемо боротися до останнього!" },
    [1442861620] = { ["english"] = { [1] = "Martens, Reblock, Adinay, Nikeson..." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "Мартенс, Реблок, Адіней, Ніксон..." },
    [1453227378] = { ["english"] = { [1] = "Ha! Now your death is ensured!" }, ["npcs"] = { [1] = "Blood Elf Defender" }, ["priority"] = 1, ["text"] = "Ха! Тобі кінець!" },
    [1453369247] = { ["english"] = { [1] = "There's nothing like some scalding mornbrew on a chilly Dun Morogh day to get things started right!" }, ["npcs"] = { [1] = "Durnan Furcutter" }, ["priority"] = 1, ["text"] = "Немає нічого кращого за гарячий ранковий напій у прохолодний день у Дун-Морозі, щоб добре почати день!" },
    [1454967392] = { ["english"] = { [1] = "We must focus our thoughts upon the Circle of Calling if the Forest Lord is to come! We must hurry! Concentrate your energies!" }, ["npcs"] = { [1] = "Arch Druid Renferal" }, ["priority"] = 1, ["text"] = "Ми маємо зосередитись на колі, щоб викликати Повелителя лісу! Хутчіше! Зосередьте свої сили!" },
    [1458512438] = { ["english"] = { [1] = "Now you're gonna get it good, <name>!" }, ["npcs"] = { [1] = "Dashel Stonefist" }, ["priority"] = 1, ["text"] = "Зараз я тобі покажу, {ім'я:к}!#it good, <name>!" },
    [1460143634] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "C'mon, let's try somewhere else." }, ["npcs"] = { [1] = "Billy" }, ["priority"] = 1, ["text"] = "Пішли, спробуємо ще десь." } }, ["english"] = { [1] = "C'mon, let's try somewhere else." }, ["npcs"] = { [1] = "Adam" }, ["priority"] = 1, ["text"] = "Пішли, спробуємо ще десь." },
    [1472036349] = { ["english"] = { [1] = "Kill the guards, take the Warden alive!" }, ["npcs"] = { [1] = "Defias Rioter" }, ["priority"] = 1, ["text"] = "Убийте вартових, схопіть наглядача!" },
    [147298155] = { ["english"] = { [1] = "I should have taken the translucent pill." }, ["npcs"] = { [1] = "Caretaker Alen" }, ["priority"] = 1, ["text"] = "Треба було обрати іншу таблетку." },
    [1477822526] = { ["english"] = { [1] = "One of the Ash'ari Crystals has been destroyed!  Slay the intruders!" }, ["npcs"] = { [1] = "Thuzadin Acolyte" }, ["priority"] = 1, ["text"] = "Один з кристалів Аш'арі знищено! Вбийте чужинців!" },
    [1484695459] = { ["english"] = { [1] = "Your actions shame us all, <class>. I hurt inside as I beat you senseless." }, ["npcs"] = { [1] = "Cenarion Hold Infantry" }, ["priority"] = 1, ["text"] = "Ти ганьбиш нас всіх, {клас:к}. Серце кров'ю обливається, але я мушу тебе провчити." },
    [1487846011] = { ["english"] = { [1] = "I'm sure I can find a use for this mixture..." }, ["npcs"] = { [1] = "Crank Fizzlebub" }, ["priority"] = 1, ["text"] = "Думаю, я знайду де використати цю суміш..." },
    [1489973655] = { ["english"] = { [1] = "No farm woman can stand against the Defias!" }, ["npcs"] = { [1] = "Defias Raider" }, ["priority"] = 1, ["text"] = "Жодна фермерка не зупинить Непокірних!" },
    [1490982862] = { ["english"] = { [1] = "Argh, the pain. Will it ever leave me?" }, ["npcs"] = { [1] = "Deathguard Kel" }, ["priority"] = 1, ["text"] = "Аргх, цей біль. Коли вже він мене полишить?" },
    [1497093567] = { ["english"] = { [1] = "Let your death serve as an example!" }, ["npcs"] = { [1] = "The Prophet Skeram" }, ["priority"] = 1, ["text"] = "Твоя смерть стане прикладом для інших!" },
    [1497963302] = { ["english"] = { [1] = "For the Dragonmaw!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "За Драконову Пащу!" },
    [1499227062] = { ["english"] = { [1] = "Just sit right back and you'll hear a ta... *hic* a tai... *hic* a taiiii *hic* Damnit!" }, ["npcs"] = { [1] = "Caretaker Alen" }, ["priority"] = 1, ["text"] = "Нехай проблеми та незгоди не роб... *гик* не роооб... *гик* роб...*гик* Трясця!" },
    [1500841817] = { ["english"] = { [1] = "%s calls more of his allies out of the shadows." }, ["npcs"] = { [1] = "Edwin VanCleef" }, ["priority"] = 1, ["text"] = "%s викликає більше союзників з тіней." },
    [1501603116] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Imposter!  It is a dishonor without equal to be summoned by a whelp such as you!  DIE!" }, ["npcs"] = { [1] = "The Duke of Fathoms" }, ["priority"] = 1, ["text"] = "{стать:Самозванець:Самозванка}! Бути викликаним такою нікчемою, як ти — яка ганьба! ЗДОХНИ!" }, [2] = { ["english"] = { [1] = "Imposter!  It is a dishonor without equal to be summoned by a whelp such as you!  DIE!" }, ["npcs"] = { [1] = "The Duke of Shards" }, ["priority"] = 1, ["text"] = "{стать:Самозванець:Самозванка}! Бути викликаним такою нікчемою, як ти — яка ганьба! ЗДОХНИ!" }, [3] = { ["english"] = { [1] = "Imposter!  It is a dishonor without equal to be summoned by a whelp such as you!  DIE!" }, ["npcs"] = { [1] = "The Duke of Zephyrs" }, ["priority"] = 1, ["text"] = "{стать:Самозванець:Самозванка}! Бути викликаним такою нікчемою, як ти — яка ганьба! ЗДОХНИ!" } }, ["english"] = { [1] = "Imposter!  It is a dishonor without equal to be summoned by a whelp such as you!  DIE!" }, ["npcs"] = { [1] = "The Duke of Cynders" }, ["priority"] = 1, ["text"] = "{стать:Самозванець:Самозванка}! Бути викликаним такою нікчемою, як ти — яка ганьба! ЗДОХНИ!" },
    [1508820764] = { ["english"] = { [1] = "Thanks a lot, <name>!" }, ["npcs"] = { [1] = "Stormpike Quartermaster" }, ["priority"] = 1, ["text"] = "Красно дякую, {ім'я:к}!#lot, <name>!" },
    [1511051154] = { ["english"] = { [1] = "Dat <race> look gud to eat!" }, ["npcs"] = { [1] = "Chok'sul" }, ["priority"] = 1, ["text"] = "Ми їсти {раса:н}!#Dat <race> look" },
    [1512045678] = { ["english"] = { [1] = "Pull up a stool and have a drink!" }, ["npcs"] = { [1] = "Barkeep Daniels" }, ["priority"] = 1, ["text"] = "Сідайте на стілець та візьміть щось випити!" },
    [1517833689] = { ["english"] = { [1] = "Aye, lads!  Things are about to get quite ugly." }, ["npcs"] = { [1] = "Captain Blackanvil" }, ["priority"] = 1, ["text"] = "Гаразд, народ! Зараз почнеться місиво." },
    [1524356560] = { ["english"] = { [1] = "The good doctor saves the day! HOORAY!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Гарний лікар рятує ситуацію! УРА!" },
    [1525595495] = { ["english"] = { [1] = "Eww... that's not a fish!" }, ["npcs"] = { [1] = "Roman" }, ["priority"] = 1, ["text"] = "Фуу... це не риба!" },
    [1531762875] = { ["english"] = { [1] = "After the savagery that my people have witnessed and felt, you expect me to accept another burden, dragon? Surely you are mad." }, ["npcs"] = { [1] = "Fandral Staghelm" }, ["priority"] = 1, ["text"] = "Після всього зла, яке довелося пережити моєму народу, ти очікуєш, що я прийму ще один тягар, драконе? Ти, певно, несповна розуму." },
    [1532928] = { ["english"] = { [1] = "OK Fengus, where you at?!  You come call me a gnoll lover while I give you da hammer upside da head!" }, ["npcs"] = { [1] = "Captain Kromcrush" }, ["priority"] = 1, ["text"] = "Ну, Фенґ, ти де?! Давай, скажи мені хто тут гнололюб, поки я тобі молотом по макітрі не гепнув!" },
    [1533684956] = { ["english"] = { [1] = "Andre!  I'm finished!" }, ["npcs"] = { [1] = "Tormus Deepforge" }, ["priority"] = 3, ["text"] = "Андре!  Я закінчив!" },
    [153429995] = { ["english"] = { [1] = "Behold Ragnaros - the Firelord! He who was ancient when this world was young! Bow before him, mortals! Bow before your ending!" }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Готуйтесь зустрітися з Раґнаросом — Володарем Вогню! Тим, хто був древнім ще в часи юності цього світу! Схиліться перед ним, смертні! Схиліться перед своєю загибеллю!" },
    [1535942007] = { ["english"] = { [1] = "The People of Westfall salute <name>, a brave and valiant defender of freedom." }, ["npcs"] = { [1] = "Gryan Stoutmantle" }, ["priority"] = 3, ["text"] = "Народ Західного краю вітає {ім'я:з}, хороброго й звитяжного захисника свободи." },
    [1536573688] = { ["english"] = { [1] = "Come, puny mortals. Come and face your end. The secrets of Ahn'Qiraj will die with Roman'khan!" }, ["npcs"] = { [1] = "Emissary Roman'khan" }, ["priority"] = 1, ["text"] = "Йдіть, недолугі смертні. Йдіть і зустріньте свою загибель. Таємниці Ан'Кіража помруть разом з Роман'ханом!" },
    [15376703] = { ["english"] = { [1] = "Assassins! Guards! Guards!" }, ["npcs"] = { [1] = "Crimson Courier" }, ["priority"] = 1, ["text"] = "Вбивці! Охорона! Охорона!" },
    [1539535848] = { ["english"] = { [1] = "How interesting... the Stone possesses great magical potential, but in a purely raw form..." }, ["npcs"] = { [1] = "Archmage Ansirem Runeweaver" }, ["priority"] = 1, ["text"] = "Як цікаво... Камінь має надзвичайний магічний потенціал, але в абсолютно чистій формі..." },
    [1540598206] = { ["english"] = { [1] = "Beware!  I am under attack!" }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "Обережно! На мене напали!" },
    [1548758209] = { ["english"] = { [1] = "The toxin is ready, <name>." }, ["npcs"] = { [1] = "Apothecary Zamah" }, ["priority"] = 1, ["text"] = "Токсин готовий, {ім'я:к}.#ready, <name>." },
    [154921396] = { ["english"] = { [1] = "Straight from the lush forests of Elwynn, get your fresh fruit right here." }, ["npcs"] = { [1] = "Bimble Longberry" }, ["priority"] = 1, ["text"] = "Найсвіжіші фрукти, щойно з пишних лісів Ельвинну." },
    [1550101773] = { ["english"] = { [1] = "My compliments to the chef!" }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Мої компліменти шефу!" },
    [1550382713] = { ["english"] = { [1] = "%s spits on the corpse of the fallen zealot." }, ["npcs"] = { [1] = "Zandalar Enforcer" }, ["priority"] = 1, ["text"] = "%s плює на труп ревнителя." },
    [1556466823] = { ["english"] = { [1] = "Sorry, Huldar... But it seems I've misled you." }, ["npcs"] = { [1] = "Saean" }, ["priority"] = 1, ["text"] = "Пробач, Хульдаре... Але, схоже, я ввів тебе в оману." },
    [1559457464] = { ["english"] = { [1] = "The final charge is set. Stand back!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Останній заряд встановлено. Відійдіть!" },
    [1560389029] = { ["english"] = { [1] = "I could crush you with but a single motion. Do not anger me." }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "Я можу знищити тебе одним помахом руки. Не гнівай мене." },
    [1576798731] = { ["english"] = { [1] = "You wish to learn of the stone? Follow me." }, ["npcs"] = { [1] = "Celebras the Redeemed" }, ["priority"] = 1, ["text"] = "Хочеш побачити камінь? Ходи за мною." },
    [157926944] = { ["english"] = { [1] = "You won't ruin my lands, you scum!" }, ["npcs"] = { [1] = "Daphne Stilwell" }, ["priority"] = 1, ["text"] = "Ви не плюндруватимете мою землю, покидьки!" },
    [1579335637] = { ["english"] = { [1] = "Leave this accursed place at once!" }, ["npcs"] = { [1] = "Baron Silverlaine" }, ["priority"] = 1, ["text"] = "Покиньте це прокляте місце негайно!" },
    [1579605495] = { ["english"] = { [1] = "Oh yeah, I heard about that." }, ["npcs"] = { [1] = "Brandon" }, ["priority"] = 1, ["text"] = "А, так, я чув про це." },
    [1579792297] = { ["english"] = { [1] = "<target> attacking! Help!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "{Ціль} атакує! Допоможіть!#<target> attacking!" },
    [1579816303] = { ["english"] = { [1] = "The Light must prevail!" }, ["npcs"] = { [1] = "Darrowshire Poltergeist" }, ["priority"] = 1, ["text"] = "Світло має перемогти!" },
    [1580199154] = { ["english"] = { [1] = "So you see fit to toy with the Lich King's creations? Ramstein, be sure to give the intruders a proper greeting." }, ["npcs"] = { [1] = "Baron Rivendare" }, ["priority"] = 1, ["text"] = "То ви вирішили побавитися з творіннями Короля-ліча? Рамштайн, подбай про наших непроханих гостей." },
    [158331303] = { ["english"] = { [1] = "%s shoots from the hip at the bottles..." }, ["npcs"] = { [1] = "Rifleman Middlecamp" }, ["priority"] = 1, ["text"] = "%s стріляє від стегна по пляшках..." },
    [1583875010] = { ["english"] = { [1] = "Come to the aid of the Throne!" }, ["npcs"] = { [1] = "Emperor Dagran Thaurissan" }, ["priority"] = 1, ["text"] = "Допоможіть Престолу!" },
    [1584195484] = { ["english"] = { [1] = "Go with grace, and may the Lady's magic protect you." }, ["npcs"] = { [1] = "Archmage Tervosh" }, ["priority"] = 1, ["text"] = "Йди з миром, і нехай магія Леді захистить тебе." },
    [1584947857] = { ["english"] = { [1] = "Think there are any fish in here?" }, ["npcs"] = { [1] = "Billy" }, ["priority"] = 1, ["text"] = "Думаєш, тут є риба?" },
    [1588376325] = { ["english"] = { [1] = "Finally, my soul may rest... Oh, dearest Cerellean..." }, ["npcs"] = { [1] = "Anaya Dawnrunner" }, ["priority"] = 1, ["text"] = "Нарешті, моя душа може спочити... О, любий Цереліане..." },
    [1589445318] = { ["english"] = { [1] = "This is grim news, and I fear it is linked to the dealings Shadow had with the Embalmer." }, ["npcs"] = { [1] = "Lord Ello Ebonlocke" }, ["priority"] = 3, ["text"] = "Це лихі новини, і я боюся, що вони пов’язані зі справами, які Шедоу мав із Бальзамувальником." },
    [1592013139] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "%s will be armed in 10 seconds!" }, ["npcs"] = { [1] = "Goblin Land Mine" }, ["priority"] = 1, ["text"] = "%s активується через 10 секунд!" } }, ["english"] = { [1] = "%s will be armed in 10 seconds!" }, ["npcs"] = { [1] = "Dark Iron Land Mine" }, ["priority"] = 1, ["text"] = "%s активується через 10 секунд!" },
    [1596041019] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "It all worked out in the end." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Зрештою, у нас тоді все вийшло." } }, ["english"] = { [1] = "It all worked out in the end." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Зрештою, у нас тоді все вийшло." },
    [1596323577] = { ["english"] = { [1] = "And the cart is still salvageable. It will need repairs, but the damage could have been much worse." }, ["npcs"] = { [1] = "Cyriden Farseeker" }, ["priority"] = 1, ["text"] = "І віз ще можна врятувати. Його потрібно буде відремонтувати, але все могло бути значно гірше." },
    [1597265505] = { ["english"] = { [1] = "They might have run all the other farmers off, but the Saldean's will never leave Westfall." }, ["npcs"] = { [1] = "Farmer Saldean" }, ["priority"] = 1, ["text"] = "Вони, можливо, й вигнали інших фермерів, але Салдени ніколи не покинуть Західний край." },
    [1597360264] = { ["english"] = { [1] = "Ah, I see you toil with relics of the past." }, ["npcs"] = { [1] = "Aman" }, ["priority"] = 1, ["text"] = "Бачу, ви бавитесь з реліквіями минулого." },
    [15987728] = { ["english"] = { [1] = "Thank you, <name>.  And luck to you." }, ["npcs"] = { [1] = "Barithras Moonshade" }, ["priority"] = 1, ["text"] = "Дякую, {ім'я:к}. І нехай тобі щастить.#Thank you, <name>." },
    [160174595] = { ["english"] = { [1] = "Hey, Raven..." }, ["npcs"] = { [1] = "Defias Tower Patroller" }, ["priority"] = 1, ["text"] = "Гей, Вороно..." },
    [1602551003] = { ["english"] = { [1] = "For once I agree with you... scum." }, ["npcs"] = { [1] = "Sorcerer Ashcrombe" }, ["priority"] = 1, ["text"] = "Вперше я з тобою згоден... виродок." },
    [1607615761] = { ["english"] = { [1] = "Welcome to flavor country!" }, ["npcs"] = { [1] = "Ezra Grimm" }, ["priority"] = 1, ["text"] = "Вітаємо у світі ароматів!" },
    [161384637] = { ["english"] = { [1] = "Let's get to the others, and keep an eye open for those wolves outside..." }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "Ну, ходімо до інших. І не забувай про вовків..." },
    [1617086965] = { ["english"] = { [1] = "Alright I'm going! Stop yelling!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Гаразд, йду я! Не кричи!" },
    [1617139051] = { ["english"] = { [1] = "You've angered me for the last time <name>!" }, ["npcs"] = { [1] = "Bloodlord Mandokir" }, ["priority"] = 1, ["text"] = "Пізнай мій гнів, {ім'я}!#time <name>!" },
    [1619714591] = { ["english"] = { [1] = "Aye, Fandral, remember these words: Let not your grief guide your faith. These thoughts you hold... dark places you go, night elf. Absolution cannot be had through misguided vengeance." }, ["npcs"] = { [1] = "Caelestrasz" }, ["priority"] = 1, ["text"] = "Гаразд, Фендрале, запам'ятай ці слова: не дозволяй своєму горю керувати твоєю вірою. Думки, в які ти занурюєшся... це темні речі, нічний ельфе. Сліпа помста — це хибний шлях до прощення." },
    [1620392510] = { ["english"] = { [1] = "You were always the troublemaker in the family, Noggle.  Always!" }, ["npcs"] = { [1] = "Beetix Ficklespragg" }, ["priority"] = 1, ["text"] = "Постійно ти вляпуєшся у щось, Ноґґл. Постійно!" },
    [1622429277] = { ["english"] = { [1] = "The Darkmoon Faire is the greatest event on all of Azeroth!" }, ["npcs"] = { [1] = "Darkmoon Faire Carnie" }, ["priority"] = 1, ["text"] = "Ярмарок Темного місяця — найвидатніша подія в усьому Азероті!" },
    [1625155266] = { ["english"] = { [1] = "I raise my brew and hope to be rid of the likes of you!  Cheers, you no good scoundrel, <name>!" }, ["npcs"] = { [1] = "Captured Mountaineer" }, ["priority"] = 1, ["text"] = "Я підіймаю цей келих за знищення таких, як ти! За твоє нездоров'я, {ім'я:к}!scoundrel, <name>!" },
    [1631192544] = { ["english"] = { [1] = "Tauren." }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Таурени." },
    [1632665881] = { ["english"] = { [1] = "Get out of here!" }, ["npcs"] = { [1] = "Theramore Sentry" }, ["priority"] = 1, ["text"] = "Забираймося звідси!" },
    [1633472919] = { ["english"] = { [1] = "The race will start in 1 minute!" }, ["npcs"] = { [1] = "Race Master Kronkrider" }, ["priority"] = 1, ["text"] = "Перегони почнуться через 1 хвилину!" },
    [1634154084] = { ["english"] = { [1] = "MmmmmMmmmm... Enormous chemically altered cracker...." }, ["npcs"] = { [1] = "Polly" }, ["priority"] = 1, ["text"] = "Мммммм... Величезний хімічно змінений крекер..." },
    [1634699872] = { ["english"] = { [1] = "This creature suffers from the effects of the fel... We must end its misery." }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Ця істота страждає від скверни... Ми повинні покласти край її стражданням." },
    [1641301060] = { ["english"] = { [1] = "%s attempts to casts Death Pact on his servants!" }, ["npcs"] = { [1] = "Baron Rivendare" }, ["priority"] = 1, ["text"] = "%s намагається накласти Пакт Смерті на своїх слуг!" },
    [1643841173] = { ["english"] = { [1] = "Ha! Ha! Ha! Thank you for freeing me, fools. Now let me repay you by charring the flesh from your bones." }, ["npcs"] = { [1] = "Pyroguard Emberseer" }, ["priority"] = 1, ["text"] = "Ха! Ха! Ха! Дякую, що звільнили мене, дурні. Дозвольте ж віддячити вам, випаливши плоть з ваших кісток." },
    [1646177819] = { ["english"] = { [1] = "ROARRRRR!!" }, ["npcs"] = { [1] = "Stitches" }, ["priority"] = 3, ["text"] = "РРРРРРАААА!!" },
    [1649641327] = { ["english"] = { [1] = "%s is knocked off his drake!" }, ["npcs"] = { [1] = "Warchief Rend Blackhand" }, ["priority"] = 1, ["text"] = "%s падає зі свого дракона!" },
    [1657121103] = { ["english"] = { [1] = "The Thandol Span fell to Ragnaros.  So shall the Stonewrought Dam!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Віадук Тандола скорився волі Раґнароса. Каменярська дамба буде наступною!" },
    [1664326422] = { ["english"] = { [1] = "Who dares awaken Archaedas? Who dares the wrath of the Makers?" }, ["npcs"] = { [1] = "Archaedas" }, ["priority"] = 1, ["text"] = "Хто сміє будити Аркедаса? Хто сміє гнівати Творців?" },
    [1668193331] = { ["english"] = { [1] = "My feet hurt." }, ["npcs"] = { [1] = "Gil" }, ["priority"] = 1, ["text"] = "Ноги болять." },
    [1669784066] = { ["english"] = { [1] = "Impossible! Stay your attack, mortals... I submit! I submit!" }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Це неможливо! Зупиніться, смертні... Я здаюсь! Здаюсь!" },
    [1670365174] = { ["english"] = { [1] = "Ah, much appreciated, Corbett.  We'll get these on the racks immediately." }, ["npcs"] = { [1] = "Harlan Bagley" }, ["priority"] = 1, ["text"] = "О, щиро вдячний, Корбете. Ми негайно розмістимо їх на полицях." },
    [1671150725] = { ["english"] = { [1] = "The High Order are the custodians of the Highborne ways, and we will master the magic holding this island in place and bend it to our will." }, ["npcs"] = { [1] = "Rathiril Sunlance" }, ["priority"] = 3, ["text"] = "Високий Орден — хранителі звичаїв Високородних, і ми опануємо магію, що утримує цей острів на місці, та підкоримо її своїй волі." },
    [1676306788] = { ["english"] = { [1] = "Intruders at the Service Gate! Baron Rivendare must be warned!" }, ["npcs"] = { [1] = "Magistrate Barthilas" }, ["priority"] = 1, ["text"] = "Чужинці біля службових воріт! Попередьте барона Рівендера!" },
    [1676833340] = { ["english"] = { [1] = "The enemy is upon us, stand ready!" }, ["npcs"] = { [1] = "Krug Skullsplit" }, ["priority"] = 1, ["text"] = "Ворог вже близько, приготуйтесь!" },
    [1678290462] = { ["english"] = { [1] = "This bridge should have been destroyed by now.  How long does it take for those lazy sods to get here from the Highlands!" }, ["npcs"] = { [1] = "Dark Iron Bombardier" }, ["priority"] = 1, ["text"] = "Цей міст вже мав лежати в руїнах. Скільки часу потрібно цим неробам, щоб дістатися сюди з височини?" },
    [1679302578] = { ["english"] = { [1] = "Oops! That was a bit off. I didn't even hit the target!" }, ["npcs"] = { [1] = "Guard Lasiter" }, ["priority"] = 1, ["text"] = "Ой! Це було трохи мимо. Я навіть не влучив у ціль!" },
    [1685116539] = { ["english"] = { [1] = "Me smash you!" }, ["npcs"] = { [1] = "Chok'sul" }, ["priority"] = 1, ["text"] = "Я тебе бити!" },
    [1686277878] = { ["english"] = { [1] = "All hail, <name>! Defender of The People!" }, ["npcs"] = { [1] = "Gryan Stoutmantle" }, ["priority"] = 3, ["text"] = "Слава {ім'я:д}! Захиснику Народу!" },
    [1688529508] = { ["english"] = { [1] = "FIRE IN THE HOLE!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "ПІДРИВАЮ!" },
    [1689660285] = { ["english"] = { [1] = "Annalise... You're right. I-I can't do this. I must find another way." }, ["npcs"] = { [1] = "Apothecary Staffron Lerent" }, ["priority"] = 1, ["text"] = "Анналіз... Ти маєш рацію. Я... Я не можу це зробити. Я мушу знайти інший шлях." },
    [1690150379] = { ["english"] = { [1] = "Thank you, <name>. Now my spirit will finally be at peace." }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Дякую тобі, {ім'я:к}. Мій дух нарешті може спочити з миром.#Thank you, <name>." },
    [1692302095] = { ["english"] = { [1] = "A worthless <race> such as you, <name>, has no right to walk these lands!" }, ["npcs"] = { [1] = "Balgaras the Foul" }, ["priority"] = 1, ["text"] = "{стать:Такий нікчемний:Така нікчемна} {раса:н} як ти, {ім'я:к}, не має права ходити цією землею!#worthless <race> such#you, <name>, has" },
    [169663453] = { ["english"] = { [1] = "For the Warchief!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "За вождя!" },
    [1697011773] = { ["english"] = { [1] = "Looking for these???? You'll never have em!" }, ["npcs"] = { [1] = "Ezra Grimm" }, ["priority"] = 1, ["text"] = "Не це шукаєте???? Ви ніколи його не отримаєте!" },
    [169740867] = { ["english"] = { [1] = "ENOUGH - this ends now!  You fools will be added to my bone collection!" }, ["npcs"] = { [1] = "Death Knight Darkreaver" }, ["priority"] = 1, ["text"] = "ДОСИТЬ! Я покінчу з вами тут і зараз! Ви, дурні, поповните мою колекцію кісток!" },
    [1697917331] = { ["english"] = { [1] = "Lapdogs, all of you!" }, ["npcs"] = { [1] = "Edwin VanCleef" }, ["priority"] = 1, ["text"] = "Ви нікчемні плазуни!" },
    [1723902132] = { ["english"] = { [1] = "<target>, no hurt A-Me. A-Me, good." }, ["npcs"] = { [1] = "A-Me 01" }, ["priority"] = 1, ["text"] = "{Ціль}, не шкодь Е-Мі. Е-Мі хороша.#<target>, no hurt" },
    [1724019306] = { ["english"] = { [1] = "Feeling blue? Come on down to the Blue Recluse for a good time!" }, ["npcs"] = { [1] = "Erich Lohan" }, ["priority"] = 3, ["text"] = "Засумував? Завітай до «Синього Самітника» — тут завжди весело!" },
    [1727224170] = { ["english"] = { [1] = "%s vanishes." }, ["npcs"] = { [1] = "Sorcerer Ashcrombe" }, ["priority"] = 1, ["text"] = "%s щезає." },
    [1728342456] = { ["english"] = { [1] = "You dare!  Outrageous!  I curse you, <class>.  I curse you with... death!" }, ["npcs"] = { [1] = "Prince Skaldrenox" }, ["priority"] = 1, ["text"] = "Як ти смієш! Це неприпустимо! Я проклинаю тебе, {клас:к}. Я проклинаю тебе... на смерть!#curse you, <class>." },
    [1728984980] = { ["english"] = { [1] = "Take heart, Alliance!  Throw these villains from Alterac Valley!" }, ["npcs"] = { [1] = "Captain Balinda Stonehearth" }, ["priority"] = 1, ["text"] = "Вище носа, Альянс! Проженіть цих покидьків з Альтерацької долини!" },
    [1729509759] = { ["english"] = { [1] = "My scepter will once again become whole!" }, ["npcs"] = { [1] = "Celebras the Redeemed" }, ["priority"] = 1, ["text"] = "Мій скіпетр знову стане цілісним!" },
    [1732189127] = { ["english"] = { [1] = "Is it true? Are there really crocilisks in the canals?" }, ["npcs"] = { [1] = "Gil" }, ["priority"] = 1, ["text"] = "Це правда? В каналах водяться кроколіски?" },
    [1732367292] = { ["english"] = { [1] = "Why do you chase me, Mechanical Yeti?! WHY?!" }, ["npcs"] = { [1] = "Quixxil" }, ["priority"] = 1, ["text"] = "Чому ти переслідуєш мене, механічний єті?! ЧОМУ?!" },
    [1734539088] = { ["english"] = { [1] = "The what-bringer? Oh, ASHbringer? Never heard of it... What? Stop bothering me!" }, ["npcs"] = { [1] = "Caretaker Alen" }, ["priority"] = 1, ["text"] = "Спопо-як? А, Спопелитель? Ніколи не чув про нього... Що? Відчепись від мене!" },
    [1734981631] = { ["english"] = { [1] = "That's it -- we made it!  The ritual is set in motion, and idol fires are about to go out for good!  You truly are the heroes I thought you would be!" }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Ось і все — нам вдалося! Ритуал завершено, і вогні ідолів ось-ось згаснуть назавжди! Ви справді ті герої, яких я чекав!" },
    [1735725932] = { ["english"] = { [1] = "Good to see you again, Amy. Be safe, luv. I'm off to Goldshire now." }, ["npcs"] = { [1] = "Antonio Perelli" }, ["priority"] = 1, ["text"] = "Радий знову бачити тебе, Емі. Бережи себе, дорогенька. Я вирушаю до Злотохрестя." },
    [1737895379] = { ["english"] = { [1] = "Explosions! MORE explosions! I got to have more explosions!" }, ["npcs"] = { [1] = "Mekgineer Thermaplugg" }, ["priority"] = 1, ["text"] = "Вибухи! БІЛЬШЕ вибухів! Мені потрібно БІЛЬШЕ ВИБУХІВ!" },
    [1738667585] = { ["english"] = { [1] = "Be warned that even your creators are fallible." }, ["npcs"] = { [1] = "Aman" }, ["priority"] = 1, ["text"] = "Будьте обережні, навіть ваші творці можуть помилятися." },
    [1739702883] = { ["english"] = { [1] = "I gonna make you into mojo!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Я з тебе моджо зроблю!" },
    [174188134] = { ["english"] = { [1] = "There's the mystical tome I was looking for." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "А ось і той містичний фоліант, який я шукала." },
    [1741994312] = { ["english"] = { [1] = "Blood and souls for Hakkar!  HAHAHAH!" }, ["npcs"] = { [1] = "Yeh'kinya" }, ["priority"] = 1, ["text"] = "Кров і душі для Гаккара! ХАХАХА!" },
    [1744596131] = { ["english"] = { [1] = "Good people of Goldshire, come take advantage of my incredible prices on rare goods. I shall not return for some time!" }, ["npcs"] = { [1] = "Antonio Perelli" }, ["priority"] = 1, ["text"] = "Добрі люди Злотохрестя, скористайтеся нагодою придбати мої рідкісні товари за неймовірними цінами. Я ще не скоро повернуся!" },
    [1746354766] = { ["english"] = { [1] = "Just release me already! I've had enough!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Та відпусти вже мене! З мене досить!" },
    [1749608592] = { ["english"] = { [1] = "It's good to see you again, Erland.  What is your report?" }, ["npcs"] = { [1] = "Rane Yorick" }, ["priority"] = 1, ["text"] = "Рада знову бачити тебе, Ерланде. Які новини?" },
    [1749707567] = { ["english"] = { [1] = "I have just the spell to get this door open. Too bad the cell doors weren't locked so haphazardly." }, ["npcs"] = { [1] = "Sorcerer Ashcrombe" }, ["priority"] = 1, ["text"] = "Я знаю гарне заклинання, щоб відкрити ці двері. Шкода, що камери не були зачинені так недбало." },
    [1751897367] = { ["english"] = { [1] = "<class> - I will consume your light!" }, ["npcs"] = { [1] = "Cauldron Lord Soulwrath" }, ["priority"] = 1, ["text"] = "{Клас:н} — я пожру твою душу!#<class> - I" },
    [1752245442] = { ["english"] = { [1] = "Can't you see I've got work to do here?" }, ["npcs"] = { [1] = "Darkmoon Faire Carnie" }, ["priority"] = 1, ["text"] = "Хіба не бачиш, що я тут зайнятий?" },
    [1752475137] = { ["english"] = { [1] = "%s goes into a rage after seeing a friend fall in battle!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s впадає в лють, коли бачить, як його побратим гине в бою!" },
    [1755078689] = { ["english"] = { [1] = "The People of Westfall salute Wreckin, a brave and valiant defender of freedom." }, ["npcs"] = { [1] = "Gryan Stoutmantle" }, ["priority"] = 3, ["text"] = "Народ Західного краю вітає Вреккіна, хороброго й доблесного захисника свободи." },
    [1755988605] = { ["english"] = { [1] = "Help me crush these punys!" }, ["npcs"] = { [1] = "Captain Kromcrush" }, ["priority"] = 1, ["text"] = "Допоможіть мені розчавити цих шмаркачів!" },
    [1760515395] = { ["english"] = { [1] = "You will never stop the Forsaken, <target>. The Dark Lady shall make you suffer." }, ["npcs"] = { [1] = "Apothecary Jorell" }, ["priority"] = 1, ["text"] = "Ти ніколи не зупиниш відречених, {ціль:к}. Темна Леді змусить тебе страждати.#the Forsaken, <target>. The" },
    [1764118232] = { ["english"] = { [1] = "DARKSHIRE...I HUNGER!!" }, ["npcs"] = { [1] = "Stitches" }, ["priority"] = 3, ["text"] = "ТЕМНОКРАЙ... Я ГОЛОДНИЙ!!" },
    [1764724327] = { ["english"] = { [1] = "Grimar, the translation is finished!" }, ["npcs"] = { [1] = "Sirra Von'Indi" }, ["priority"] = 3, ["text"] = "Ґрімаре, переклад завершено!" },
    [1773526762] = { ["english"] = { [1] = "%s obviously beaten, tries to run." }, ["npcs"] = { [1] = "Private Hendel" }, ["priority"] = 1, ["text"] = "%s, сильно побитий, намагається втекти." },
    [1778867007] = { ["english"] = { [1] = "Kill <target>!" }, ["npcs"] = { [1] = "Captain Tuubid" }, ["priority"] = 1, ["text"] = "Вбийте {ціль:з}!#Kill <target>!" },
    [1778868189] = { ["english"] = { [1] = "I should've grabbed a bigger sword." }, ["npcs"] = { [1] = "Captain Blackanvil" }, ["priority"] = 1, ["text"] = "Треба було взяти меча побільше." },
    [1780177135] = { ["english"] = { [1] = "Feel da big bad voodoo!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Відчуй вуду!" },
    [1780972926] = { ["english"] = { [1] = "Ahh... welcome to my parlor." }, ["npcs"] = { [1] = "Anub'Rekhan" }, ["priority"] = 1, ["text"] = "Ах... ласкаво прошу до моєї оселі." },
    [1781985468] = { ["english"] = { [1] = "Brashly, you have come to wrest the secrets of the Living Flame! You will soon regret the recklessness of your quest." }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Ви прийшли, щоб зухвало викрасти таємниці Живого Полум'я! Незабаром ви пошкодуєте про свою необачність." },
    [1786520930] = { ["english"] = { [1] = "%s lets out a battlecry!" }, ["npcs"] = { [1] = "Qiraji Slayer" }, ["priority"] = 1, ["text"] = "%s видає бойовий крик!" },
    [1788370995] = { ["english"] = { [1] = "Farewell, Cerellean, until we are joined once again..." }, ["npcs"] = { [1] = "Anaya" }, ["priority"] = 3, ["text"] = "Прощавай, Керелліане, доки ми знову не возз'єднаємося..." },
    [1790470271] = { ["english"] = { [1] = "Cliffspring Falls lies along the mountains to the east and north." }, ["npcs"] = { [1] = "Barithras Moonshade" }, ["priority"] = 1, ["text"] = "Скельноджерельні водоспади розташовані вздовж гір на північному сході." },
    [179147171] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You are constantly surprising me with what a person can live through." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Ти не перестаєш мене дивувати своїми історіями." } }, ["english"] = { [1] = "You are constantly surprising me with what a person can live through." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Ти не перестаєш мене дивувати своїми історіями." },
    [1802790572] = { ["english"] = { [1] = "Whatever. The revolting, unkempt Horde filth..." }, ["npcs"] = { [1] = "Scarlet Commander Marjhan" }, ["priority"] = 1, ["text"] = "Хай там як. Огидне, брудне поріддя Орди..." },
    [1803166653] = { ["english"] = { [1] = "I caught a big one last week, it had three eyes!" }, ["npcs"] = { [1] = "Billy" }, ["priority"] = 1, ["text"] = "Я таку величезну рибину спіймав на тому тижні, ще й з трьома очима!" },
    [1805306747] = { ["english"] = { [1] = "Tormil, Gamlor, Shefferd, Cowry..." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "Торміл, Ґамлор, Шефферд, Коврі..." },
    [1806848917] = { ["english"] = { [1] = "Your old lives, your mortal desires mean nothing... you are acolytes of the master now, and you will serve the cause without question! The greatest glory is to die in the master's service!" }, ["npcs"] = { [1] = "Grand Widow Faerlina" }, ["priority"] = 1, ["text"] = "Ваші старі життя, ваші смертні бажання нічого не значать... Тепер ви — слуги повелителя, і ви віддано виконуватиме його волю! Найвища честь — померти в служінні повелителю!" },
    [1808577072] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Well, you're still here. I'd say that is something worth drinking to." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Ну, ти все ще тут. Думаю, за це варто випити." } }, ["english"] = { [1] = "Well, you're still here. I'd say that is something worth drinking to." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Ну, ти все ще тут. Думаю, за це варто випити." },
    [1810684401] = { ["english"] = { [1] = "So many lost.  And so many more we must lose before this battle ends." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "Стільки втрат. І ще багатьох ми втратимо, перш ніж ця битва закінчиться." },
    [1811273319] = { ["english"] = { [1] = "I know it'll work this time..." }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "Цього разу точно все вийде..." },
    [1811569927] = { ["english"] = { [1] = "Sink your teeth into a fresh, ripe apple." }, ["npcs"] = { [1] = "Bimble Longberry" }, ["priority"] = 1, ["text"] = "Спробуйте мої свіжі, стиглі яблука." },
    [1811957995] = { ["english"] = { [1] = "Oh, quite succulent. Many thanks, Mrs. Chambers." }, ["npcs"] = { [1] = "Archmage Angela Dosantos" }, ["priority"] = 1, ["text"] = "О, яке соковите. Красно дякую, пані Чемберс." },
    [1817004874] = { ["english"] = { [1] = "Warm, wholesome bread!" }, ["npcs"] = { [1] = "Thomas Miller" }, ["priority"] = 1, ["text"] = "Теплий, свіжий хліб!" },
    [1817483286] = { ["english"] = { [1] = "When will someone do something about the undead?" }, ["npcs"] = { [1] = "Farrin Daris" }, ["priority"] = 3, ["text"] = "Коли вже хтось нарешті щось зробить із невмерлими?" },
    [1819267878] = { ["english"] = { [1] = "Nuh uh." }, ["npcs"] = { [1] = "Adam" }, ["priority"] = 1, ["text"] = "Нє-а." },
    [1821764902] = { ["english"] = { [1] = "How can I get anything done with the Scourge running amok around here?!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Як я можу щось робити, коли тут розгулює Скара?!" },
    [1823684029] = { ["english"] = { [1] = "We come from below! You can never stop us!" }, ["npcs"] = { [1] = "Grubbis" }, ["priority"] = 1, ["text"] = "Ми йдемо з глибин! Ви нас не зупините!" },
    [1825920115] = { ["english"] = { [1] = "Farewell, Cerellan, until we are joined once again..." }, ["npcs"] = { [1] = "Anaya" }, ["priority"] = 1, ["text"] = "Прощавай, Цереліане, допоки смерть не возз'єднає нас..." },
    [1826714446] = { ["english"] = { [1] = "NOW, STAGHELM! WE GO NOW! Prepare your magic!" }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "ЗАРАЗ, ОЛЕНЕРІГ! ЦЕЙ МОМЕНТ НАСТАВ! Приготуй свою магію!" },
    [1829340748] = { ["english"] = { [1] = "The ages have been cruel to you and I, my love, but be assured, it is, and at long last we are reunited." }, ["npcs"] = { [1] = "Anaya" }, ["priority"] = 1, ["text"] = "Час не змилувався ні над тобою, ні наді мною, коханий мій, та все ж ми нарешті знову зустрілися." },
    [1829623765] = { ["english"] = { [1] = "What have you done? FOOL! You brought it... NO!" }, ["npcs"] = { [1] = "Archmage Angela Dosantos" }, ["priority"] = 1, ["text"] = "Що ти {стать:накоїв:накоїла}? {стать:ДУРЕНЬ:ДУРЕПА}! Ти {стать:приніс:принесла}... НІ!" },
    [1834292233] = { ["english"] = { [1] = "Thank you for rescuing me! Word of your deed will not go unnoticed." }, ["npcs"] = { [1] = "Kernobee" }, ["priority"] = 1, ["text"] = "Дякую за порятунок! Я всім розкажу про ваше геройство." },
    [1838236757] = { ["english"] = { [1] = "Impossible!" }, ["npcs"] = { [1] = "Warchief Rend Blackhand" }, ["priority"] = 1, ["text"] = "Неможливо!" },
    [183895707] = { ["english"] = { [1] = "%s begins to channel his energy, focusing on the stone." }, ["npcs"] = { [1] = "Celebras the Redeemed" }, ["priority"] = 1, ["text"] = "%s починає спрямовувати свою енергію, зосереджуючись на камені." },
    [1839139285] = { ["english"] = { [1] = "I have a special message for <name>.  And it says you must die!" }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "У мене є особливе повідомлення для {ім'я:р}. І в ньому сказано, що ти маєш померти!#for <name>." },
    [1846255862] = { ["english"] = { [1] = "Time to die, <class>." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Час вмирати, {клас:к}.#die, <class>" },
    [1849810892] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Battling that band of Twilight Hammer in the Morass, I could think of better places for a war." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "А бій з тою бандою Сутінкового Молота в Чорних драгвах? Еге, кращого місця для битви не придумаєш." } }, ["english"] = { [1] = "Battling that band of Twilight Hammer in the Morass, I could think of better places for a war." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "А бій з тою бандою Сутінкового Молота в Чорних драгвах? Еге, кращого місця для битви не придумаєш." },
    [1853746822] = { ["english"] = { [1] = "Key... get the key... Gerstahn has... key." }, ["npcs"] = { [1] = "Commander Gor'shak" }, ["priority"] = 1, ["text"] = "Ключ... Знайди ключ... Він у... Ґерштан." },
    [1856009414] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Hehe, wimp." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Хе-хе, слабак." } }, ["english"] = { [1] = "Hehe, wimp." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Хе-хе, слабак." },
    [1856550413] = { ["english"] = { [1] = "Only the Windshapers can save Zephras Isle!" }, ["npcs"] = { [1] = "Windshaper Novice Seer" }, ["priority"] = 3, ["text"] = "Лише вітротворці можуть урятувати острів Зефрас!" },
    [1858026807] = { ["english"] = { [1] = "The Ash'ari Crystals have been destroyed! The Slaughterhouse is vulnerable!" }, ["npcs"] = { [1] = "Baron Rivendare" }, ["priority"] = 1, ["text"] = "Кристали Аш'арі знищено! Бійня втратила захист!" },
    [1860081449] = { ["english"] = { [1] = "The Stonewrought Dam has been saved!  Three cheers for <name>!" }, ["npcs"] = { [1] = "Chief Engineer Hinderweir VII" }, ["priority"] = 1, ["text"] = "Каменярську дамбу врятовано! Славімо {ім'я:з}!#for <name>!" },
    [186057672] = { ["english"] = { [1] = "HEY! HEY YOU! <race>! Get me out of here!" }, ["npcs"] = { [1] = "Commander Gor'shak" }, ["priority"] = 1, ["text"] = "ЕЙ! ЕЙ ТИ! {Раса:к}! Витягни мене звідси!#YOU! <race>! Get" },
    [186423165] = { ["english"] = { [1] = "COME FORTH, MY SERVANTS! DEFEND YOUR MASTER!" }, ["npcs"] = { [1] = "Ragnaros" }, ["priority"] = 1, ["text"] = "СЮДИ, МОЇ СЛУГИ! ЗАХИСТІТЬ СВОГО ПОВЕЛИТЕЛЯ!" },
    [187027466] = { ["english"] = { [1] = "If Gnoarn finds out about this, it'll be my hide!" }, ["npcs"] = { [1] = "Bingles Blastenheimer" }, ["priority"] = 1, ["text"] = "Якщо Ґноарн дізнається про це, мені гайки!" },
    [1871382043] = { ["english"] = { [1] = "This has gone too far.  How dare the Scourge attack Stormwind!  Destroy it before more come!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Це зайшло надто далеко. Як сміє Скара нападати на Штормовій? Знищте їх, поки не прийшло ще більше!" },
    [1872881764] = { ["english"] = { [1] = "I should get back before Rema starts to worry..." }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Треба повертатись, поки Рема не почала хвилюватися..." },
    [1878254050] = { ["english"] = { [1] = "If you just sit still and rest for a few more moments, you'll gain a benefit from having rested near the tent I have set up behind me." }, ["npcs"] = { [1] = "Raan Wildwind" }, ["priority"] = 3, ["text"] = "Якщо просто посидиш спокійно й відпочинеш ще кілька хвилин, отримаєш користь від відпочинку біля намету, який я встановив позаду." },
    [1879798305] = { ["english"] = { [1] = "The Affray is over!" }, ["npcs"] = { [1] = "Twiggy Flathead" }, ["priority"] = 1, ["text"] = "Побоїще завершено!" },
    [1879838754] = { ["english"] = { [1] = "Shhh! You're scaring the fish away." }, ["npcs"] = { [1] = "Adam" }, ["priority"] = 1, ["text"] = "Тссс! Ти розлякаєш всю рибу." },
    [1881619313] = { ["english"] = { [1] = "The people of Darkshire expect more from the Council.  We cannot let them suffer from this unholy wrath which plagues us." }, ["npcs"] = { [1] = "Role Dreuger" }, ["priority"] = 3, ["text"] = "Жителі Темнокраю очікують від Ради більшого. Ми не можемо дозволити їм страждати від цієї нечестивої люті, що терзає нас." },
    [1881959392] = { ["english"] = { [1] = "It'll take more than a rotting corpse to stop us!" }, ["npcs"] = { [1] = "Commander Althea Ebonlocke" }, ["priority"] = 1, ["text"] = "Щоб зупинити нас, знадобиться щось більше за гнилий труп!" },
    [1884877335] = { ["english"] = { [1] = "Burn in righteous fire!" }, ["npcs"] = { [1] = "Arcanist Doan" }, ["priority"] = 1, ["text"] = "Згоріть у праведному вогні!" },
    [1888085528] = { ["english"] = { [1] = "All hail <name>, a <class> of worth!" }, ["npcs"] = { [1] = "Angus Stern" }, ["priority"] = 1, ["text"] = "Шануймо {ім'я:з}! Гідний приклад для всіх {клас:мр}!#All hail <name>,#a <class> of worth" },
    [1890650978] = { ["english"] = { [1] = "When the time is right, my lady. All will be clear when the time is right. The master stirs even now. Look to the skies for the Brood of Nozdormu have returned." }, ["npcs"] = { [1] = "Baristolth of the Shifting Sands" }, ["priority"] = 1, ["text"] = "Коли настане час, моя пані. Все буде зрозуміло, коли настане час. Майстер готується навіть зараз. Погляньте на небеса, бо рід Ноздорму повернувся." },
    [1892509577] = { ["english"] = { [1] = "The Brotherhood will not be hampered by insects." }, ["npcs"] = { [1] = "Defias Dockmaster" }, ["priority"] = 1, ["text"] = "Непокірних не зупинять такі нікчеми." },
    [1892655863] = { ["english"] = { [1] = "Curious. A Servitor of Rastakhan that does not know the Hakkari do not converse in the old tongue?" }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Цікаво. Слуга Растахана, який не знає, що Гаккарі не розмовляють старою мовою?" },
    [1894889894] = { ["english"] = { [1] = "About time someone killed the wretch." }, ["npcs"] = { [1] = "Deathstalker Adamant" }, ["priority"] = 1, ["text"] = "Давно вже пора було комусь вбити цього покидька." },
    [1897953309] = { ["english"] = { [1] = "Ok, here I go!" }, ["npcs"] = { [1] = "Weegli Blastfuse" }, ["priority"] = 1, ["text"] = "Гаразд, я пішов!" },
    [1901191019] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You dare spill blood on neutral ground? OUT! OUT, I SAY!" }, ["npcs"] = { [1] = "Cenarion Hold Reservist" }, ["priority"] = 1, ["text"] = "Ти насмілюєшся проливати кров на нейтральній землі? ГЕТЬ! ГЕТЬ, КАЖУ!" } }, ["english"] = { [1] = "You dare spill blood on neutral ground? OUT! OUT, I SAY!" }, ["npcs"] = { [1] = "Cenarion Hold Infantry" }, ["priority"] = 1, ["text"] = "Ти насмілюєшся проливати кров на нейтральній землі? ГЕТЬ! ГЕТЬ, КАЖУ!" },
    [1901570217] = { ["english"] = { [1] = "Thank... you..." }, ["npcs"] = { [1] = "Thaddius" }, ["priority"] = 1, ["text"] = "Спасибі..." },
    [1903854084] = { ["english"] = { [1] = "Oh yes, old one, Hakkar has returned. Soon the world shall crumble beneath his might. Consumed. Left in ruin..." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "О, так, старий, Гаккар повернувся. Скоро світ здригнеться від його сили. Спопеліє і лежатиме в руїнах..." },
    [1904351712] = { ["english"] = { [1] = "Warning! Warning! Intruder alert! Intruder alert!" }, ["npcs"] = { [1] = "Mobile Alert System" }, ["priority"] = 1, ["text"] = "Тривога! Тривога! Порушники! Порушники!" },
    [1905289744] = { ["english"] = { [1] = "A-Me, home. A-Me go home! <target>, no stop A-Me." }, ["npcs"] = { [1] = "A-Me 01" }, ["priority"] = 1, ["text"] = "Е-Мі, дім. Е-Мі йти додому! {Ціль} не зупинити Е-Мі.#go home! <target>, no stop" },
    [1907083171] = { ["english"] = { [1] = "I am looking for some bodyguards that would like to protect the Gizelton Caravan. We are stopped on the road east of Kormek's Hut, north of Kolkar Centaur Village." }, ["npcs"] = { [1] = "Cork Gizelton" }, ["priority"] = 1, ["text"] = "Шукаю охоронців для супроводу каравану Ґізельтона. Ми зупинилися на дорозі на схід від хатини Кормека, північніше селища Колкарів." },
    [1907424612] = { ["english"] = { [1] = "Your message did reach us, Commander, but by no means is our involvement here sanctioned by the Grand Crusader." }, ["npcs"] = { [1] = "Scarlet Commander Marjhan" }, ["priority"] = 1, ["text"] = "Ми отримали ваше повідомлення, командире, але наша присутність тут не була схвалена верховним лицарем." },
    [1908386489] = { ["english"] = { [1] = "There is always... Ashbringer." }, ["npcs"] = { [1] = "Scarlet Commander Marjhan" }, ["priority"] = 1, ["text"] = "Все ще є... Спопелитель." },
    [1908733875] = { ["english"] = { [1] = "Your jail is ours!" }, ["npcs"] = { [1] = "Defias Rioter" }, ["priority"] = 1, ["text"] = "Ця в'язниця — наша!" },
    [1908926355] = { ["english"] = { [1] = "Terror, darkness, power? The Forsaken crave not these things; the Forsaken ARE these things." }, ["npcs"] = { [1] = "Caretaker Caice" }, ["priority"] = 1, ["text"] = "Страх, пітьма, сила? Відречені не прагнуть цього. Відречені і є цим." },
    [1911888767] = { ["english"] = { [1] = "You will be judged for defiling these sacred grounds!  The laws of the Ancients will not be challenged!  Trespassers will be annihilated!" }, ["npcs"] = { [1] = "Battleguard Sartura" }, ["priority"] = 1, ["text"] = "Вас судитимуть за осквернення цих священних земель! Закони древніх незмінні! Порушників буде знищено!" },
    [1914710648] = { ["english"] = { [1] = "Go about your business. My errand does not require your attention." }, ["npcs"] = { [1] = "Archmage Tervosh" }, ["priority"] = 1, ["text"] = "Займайся своїми справами. Моє доручення не потребує твоєї уваги." },
    [1915097451] = { ["english"] = { [1] = "Yiieeeee! Me run!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Їііііі! Я бігти!" },
    [1920234053] = { ["english"] = { [1] = "Hail to the king, baby!" }, ["npcs"] = { [1] = "Emperor Dagran Thaurissan" }, ["priority"] = 1, ["text"] = "Слава королю, крихітко!" },
    [1922809974] = { ["english"] = { [1] = "I heard that there are these huge fish that can walk on land to hunt, and eat people!" }, ["npcs"] = { [1] = "Billy" }, ["priority"] = 1, ["text"] = "Я чув про величезних риб, які можуть ходити по суші, щоб вбивати і їсти людей!" },
    [1923370996] = { ["english"] = { [1] = "Now is the time to attack!  For the Horde!" }, ["npcs"] = { [1] = "Captain Galvangar" }, ["priority"] = 1, ["text"] = "Настав час наступати! За Орду!" },
    [19235320] = { ["english"] = { [1] = "Run!" }, ["npcs"] = { [1] = "Theramore Sentry" }, ["priority"] = 1, ["text"] = "Біжіть!" },
    [1926378372] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I'll crush your skull beneath my boot!" }, ["npcs"] = { [1] = "Bruegal Ironknuckle" }, ["priority"] = 1, ["text"] = "Я розчавлю твій череп своїм чоботом!" } }, ["english"] = { [1] = "I'll crush your skull beneath my boot!" }, ["npcs"] = { [1] = "Bazil Thredd" }, ["priority"] = 1, ["text"] = "Я розчавлю твій череп своїм чоботом!" },
    [1928982482] = { ["english"] = { [1] = "They have broken into the Hall of Lights!  We must stop the intruders!" }, ["npcs"] = { [1] = "Crimson Gallant" }, ["priority"] = 1, ["text"] = "Вони увірвались до зали Світла! Ми маємо зупинити загарбників!" },
    [1932449259] = { ["english"] = { [1] = "Alright! Alright! We surrender... Just put your weapons down, I'll cooperate!" }, ["npcs"] = { [1] = "Balos Jacken" }, ["priority"] = 1, ["text"] = "Гаразд! Гаразд! Ми здаємося... Опустіть зброю, я все розкажу!" },
    [1935244356] = { ["english"] = { [1] = "TOO SOON! YOU HAVE AWAKENED ME TOO SOON, EXECUTUS! WHAT IS THE MEANING OF THIS INTRUSION???" }, ["npcs"] = { [1] = "Ragnaros" }, ["priority"] = 1, ["text"] = "ЗАНАДТО РАНО! ТИ РОЗБУДИВ МЕНЕ ЗАНАДТО РАНО, ЕКЗЕКУТУС! ЩО ВСЕ ЦЕ ОЗНАЧАЄ?" },
    [1936749167] = { ["english"] = { [1] = "I smell a <race>." }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Я чую запах {раса:р}.# a <race>." },
    [1939065914] = { ["english"] = { [1] = "If you will not serve my Master with your sword and knowledge of his enemies..." }, ["npcs"] = { [1] = "Arugal" }, ["priority"] = 1, ["text"] = "Якщо ти не будеш служити моєму майстру своїм мечем і знаннями про його ворогів..." },
    [1940417663] = { ["english"] = { [1] = "What?!  You no can beat me!  Me will return!" }, ["npcs"] = { [1] = "Avalanchion" }, ["priority"] = 1, ["text"] = "Що?! Ви не перемогти мене! Я повернусь!" },
    [1941310392] = { ["english"] = { [1] = "Captain Redpath is slain!" }, ["npcs"] = { [1] = "Darrowshire Defender" }, ["priority"] = 1, ["text"] = "Капітан Редпат мертвий!" },
    [1944953726] = { ["english"] = { [1] = "If you could catch a fish big enough for your mouth we'd never be hungry again." }, ["npcs"] = { [1] = "Adam" }, ["priority"] = 1, ["text"] = "Якби на твої вигадки ловилась риба — ми б нагодували весь Штормовій!" },
    [1945510360] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I have a piece of iron in my back that will remind me of that night for the rest of my days." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "З цим шматком заліза в спині я ту ніч до скону не забуду." } }, ["english"] = { [1] = "I have a piece of iron in my back that will remind me of that night for the rest of my days." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "З цим шматком заліза в спині я ту ніч до скону не забуду." },
    [1948564470] = { ["english"] = { [1] = "Protect the flight!  These intruders die now!" }, ["npcs"] = { [1] = "Death Talon Captain" }, ["priority"] = 1, ["text"] = "Захищайте зграю! Ці загарбники мають померти!" },
    [1955818156] = { ["english"] = { [1] = "Hey! Do you like the sauce? The sauce is good, no?" }, ["npcs"] = { [1] = "Caretaker Alen" }, ["priority"] = 1, ["text"] = "Можна бути нічим не ліпшим... Можна померти і стати іншим..." },
    [1961929919] = { ["english"] = { [1] = "Student will work harder, master!" }, ["npcs"] = { [1] = "Deathknight Understudy" }, ["priority"] = 1, ["text"] = "Учень працюватиме старанніше, вчителю!" },
    [1963466394] = { ["english"] = { [1] = "They were just getting in the way anyways." }, ["npcs"] = { [1] = "Emperor Dagran Thaurissan" }, ["priority"] = 1, ["text"] = "Вони все одно лише заважали." },
    [1969389060] = { ["english"] = { [1] = "Are they all... dead?" }, ["npcs"] = { [1] = "Artist Renfray" }, ["priority"] = 1, ["text"] = "Вони всі... мертві?" },
    [1971629161] = { ["english"] = { [1] = "And for the ladies, roast baby boar. Enjoy!" }, ["npcs"] = { [1] = "Jessica Chambers" }, ["priority"] = 1, ["text"] = "А для пані — запечене порося. Смачного!" },
    [1974919860] = { ["english"] = { [1] = "It has been a long time, Bethor, my friend." }, ["npcs"] = { [1] = "Gunther's Visage" }, ["priority"] = 1, ["text"] = "Беторе, друже мій, минуло багато часу." },
    [1976649100] = { ["english"] = { [1] = "Meow!" }, ["npcs"] = { [1] = "Effsee" }, ["priority"] = 1, ["text"] = "Няв!" },
    [1982025304] = { ["english"] = { [1] = "Who dares?! I will destroy you!" }, ["npcs"] = { [1] = "Blood Elf Defender" }, ["priority"] = 1, ["text"] = "Хто посмів?! Я тебе знищу!" },
    [1987851011] = { ["english"] = { [1] = "Footmen, make a line!" }, ["npcs"] = { [1] = "Captain Blackanvil" }, ["priority"] = 1, ["text"] = "Піхотинці, шикуйсь!" },
    [1990468925] = { ["english"] = { [1] = "Ah, fresh air at last! I need a moment to rest, <name>." }, ["npcs"] = { [1] = "Corporal Keeshan" }, ["priority"] = 1, ["text"] = "Ах, нарешті свіже повітря! Дай мені трохи перепочити, {ім'я:к}.#rest, <name>." },
    [1996563328] = { ["english"] = { [1] = "%s begins a spell of summoning..." }, ["npcs"] = { [1] = "Bath'rah the Windwatcher" }, ["priority"] = 1, ["text"] = "%s починає читати закляття виклику..." },
    [2006095919] = { ["english"] = { [1] = "The Old Gods will be restored.  You will not be allowed to interfere!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Старі Боги повернуться. Ви цьому не завадите!" },
    [2006902243] = { ["english"] = { [1] = "This land belongs to the Dark Iron Dwarves.  Prepare to see the afterlife, <class>!" }, ["npcs"] = { [1] = "Balgaras the Foul" }, ["priority"] = 1, ["text"] = "Ця земля належить дворфам Темного Заліза. Готуйся до смерті, {клас:к}!#afterlife, <class>!" },
    [2009678411] = { ["english"] = { [1] = "What... happen to-" }, ["npcs"] = { [1] = "Patchwerk" }, ["priority"] = 1, ["text"] = "Що... сталось..." },
    [2013154314] = { ["english"] = { [1] = "May this prisoner's death serve as a warning.  None shall defy the scourge and live!" }, ["npcs"] = { [1] = "Baron Rivendare" }, ["priority"] = 1, ["text"] = "Нехай смерть цього дівчиська послужить застереженням. Нікому не вдасться кинути виклик Скарі та лишитися живим!" },
    [2014750486] = { ["english"] = { [1] = "Okay, okay... gimmie a minute to rest now. You gone and beat me up good." }, ["npcs"] = { [1] = "Calvin Montague" }, ["priority"] = 1, ["text"] = "Гаразд, гаразд... Дай мені хвильку перепочити. Ти добряче мене {стать:побив:побила}." },
    [2015546310] = { ["english"] = { [1] = "Step right up and wet your whistle." }, ["npcs"] = { [1] = "Barkeep Hann" }, ["priority"] = 1, ["text"] = "Підходьте і візьміть щось випити." },
    [2016562275] = { ["english"] = { [1] = "Rivendare!  I come for you!" }, ["npcs"] = { [1] = "Aurius" }, ["priority"] = 1, ["text"] = "Рівендер! Я прийшов за тобою!" },
    [2020508815] = { ["english"] = { [1] = "At last, the serum is complete, <name>. Now, come closer. We must talk." }, ["npcs"] = { [1] = "Apothecary Faustin" }, ["priority"] = 1, ["text"] = "Нарешті, сироватка готова. Тепер підійди ближче, {ім'я:к}. Нам потрібно поговорити.#is complete, <name>." },
    [2021755180] = { ["english"] = { [1] = "All of a sudden they were everywhere." }, ["npcs"] = { [1] = "Warden Thelwater" }, ["priority"] = 3, ["text"] = "Раптом вони були вже повсюди." },
    [2022235803] = { ["english"] = { [1] = "You've really outdone yourself this time, Mrs. Chambers. Not a spot of mold to be found!" }, ["npcs"] = { [1] = "Father Inigo Montoy" }, ["priority"] = 1, ["text"] = "Ви перевершили себе, пані Чамберс. Жодних слідів плісняви!" },
    [2023686476] = { ["english"] = { [1] = "We're under attack!  A vast, ye swabs! Repel the invaders! " }, ["npcs"] = { [1] = "Mr. Smite" }, ["priority"] = 3, ["text"] = "На нас напали!  Агов, палубні щури! Відбийте нападників! " },
    [2026093713] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Fresh bread for sale!" }, ["npcs"] = { [1] = "Thomas Miller" }, ["priority"] = 1, ["text"] = "Продається свіжий хліб!" } }, ["english"] = { [1] = "Fresh bread for sale!" }, ["npcs"] = { [1] = "Myra Tyrngaarde" }, ["priority"] = 1, ["text"] = "Продається свіжий хліб!" },
    [203078977] = { ["english"] = { [1] = "None may challenge the Brotherhood!" }, ["npcs"] = { [1] = "Edwin VanCleef" }, ["priority"] = 1, ["text"] = "Ніхто не сміє кидати виклик Братству!" },
    [2033362439] = { ["english"] = { [1] = "Believe me when I tell you this: You're gonna wish you weren't born, sissy!" }, ["npcs"] = { [1] = "Cenarion Hold Infantry" }, ["priority"] = 1, ["text"] = "Ти пошкодуєш про це, мерзото!" },
    [203924225] = { ["english"] = { [1] = "Who is this mere dwarf that meddles with that which is past?  May the legend of Stalvan die along with you!" }, ["npcs"] = { [1] = "Forlorn Spirit" }, ["priority"] = 3, ["text"] = "Хто цей нікчемний дворф, що втручається в минуле?  Нехай легенда про Сталвана помре разом із тобою!" },
    [20405502] = { ["english"] = { [1] = "Why haven't the Stormwind guards come?" }, ["npcs"] = { [1] = "Hogan Ference" }, ["priority"] = 3, ["text"] = "Чому варта Штормовію досі не прибула?" },
    [2041083316] = { ["english"] = { [1] = "A bunch of thugs and thieves aren't going to get me to leave my land!" }, ["npcs"] = { [1] = "Farmer Saldean" }, ["priority"] = 1, ["text"] = "Купка злодіїв і бандитів не змусить мене покинути свою землю!" },
    [2041867510] = { ["english"] = { [1] = "Really?" }, ["npcs"] = { [1] = "Adam" }, ["priority"] = 1, ["text"] = "Справді?" },
    [2044220370] = { ["english"] = { [1] = "Your bones will break under my boot, <race>!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Я розтопчу твої кістки, {раса:к}!#boot, <race>!" },
    [2046447542] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Damn you mortals! All my plans of revenge, all my hate... all burned to ash..." }, ["npcs"] = { [1] = "Grand Crusader Dathrohan" }, ["priority"] = 1, ["text"] = "Кляті смертні! Всі мої плани помсти, вся моя лють... усе перетворилося на попіл..." } }, ["english"] = { [1] = "Damn you mortals! All my plans of revenge, all my hate... all burned to ash..." }, ["npcs"] = { [1] = "Balnazzar" }, ["priority"] = 1, ["text"] = "Кляті смертні! Всі мої плани помсти, вся моя лють... усе перетворилося на попіл..." },
    [2050811429] = { ["english"] = { [1] = "%s raises an undead servant back to life!" }, ["npcs"] = { [1] = "Baron Rivendare" }, ["priority"] = 1, ["text"] = "%s воскрешає невмерлого слугу!" },
    [2062470228] = { ["english"] = { [1] = "I hear little hearts beating. Yes... beating faster now... soon the beating will stop." }, ["npcs"] = { [1] = "Anub'Rekhan" }, ["priority"] = 1, ["text"] = "Я чую стукіт ваших маленьких сердець. Так... тепер вони б'ються швидше... та скоро вони зупиняться." },
    [2066772425] = { ["english"] = { [1] = "<name> brought us booze!  Let's party!" }, ["npcs"] = { [1] = "Goblin Pit Boss" }, ["priority"] = 1, ["text"] = "{ім'я:н} {стать:приніс:принесла} нам випивку! Влаштуймо вечірку!" },
    [207184652] = { ["english"] = { [1] = "Why are we goin' this way?" }, ["npcs"] = { [1] = "Gil" }, ["priority"] = 1, ["text"] = "Чому ми йдемо цією дорогою?" },
    [20730558] = { ["english"] = { [1] = "<race> flesh... must feed!" }, ["npcs"] = { [1] = "Cauldron Lord Bilemaw" }, ["priority"] = 1, ["text"] = "{Раса:н}... плоть... мушу їсти..." },
    [2074803005] = { ["english"] = { [1] = "<name>, can you hear me? I think the spell went a little haywire and dropped you and your friend in different locations. Hurry up and find him, then get what you need and get back to the Inn on the west side of town. The portal will be waiting!" }, ["npcs"] = { [1] = "Chromie" }, ["priority"] = 1, ["text"] = "{Ім'я:н}, ти мене чуєш? Здається, заклинання спрацювало трішки не так і вас перенесло в різні місця. Поквапся і знайди свого друга, потім візьміть те, що вам потрібно, і повертайтесь в таверну на західному краю міста. Там буде портал!" },
    [2075233499] = { ["english"] = { [1] = "Thank you kindly!" }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Щиро вам вдячний!" },
    [2077702451] = { ["english"] = { [1] = "Ahh... My experiments never seem to work out right. Maybe I should go back downstream." }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "Ех... Мої експерименти ніколи не вдаються. Може, мені слід почати спочатку." },
    [2080347245] = { ["english"] = { [1] = "It was a simple mistake. A wrong turn I tell you!" }, ["npcs"] = { [1] = "Acolyte Dellis" }, ["priority"] = 1, ["text"] = "Це було випадково. Кажу ж, я просто звернув не туди!" },
    [2084332427] = { ["english"] = { [1] = "%s gestures at the piles of books." }, ["npcs"] = { [1] = "Daryn Lightwind" }, ["priority"] = 1, ["text"] = "%s вказує на купу книг навколо." },
    [2084772259] = { ["english"] = { [1] = "%s looks up at you quizzically. Maybe you should inspect it?" }, ["npcs"] = { [1] = "Chicken" }, ["priority"] = 3, ["text"] = "%s здивовано дивиться на вас. Може, варто його оглянути?" },
    [2090208988] = { ["english"] = { [1] = "Digging too deep into your past might bring an abrupt end to your future." }, ["npcs"] = { [1] = "Aman" }, ["priority"] = 1, ["text"] = "Надмірне копання в минулому може ненароком знищити твоє майбутнє." },
    [2090385145] = { ["english"] = { [1] = "You!  Enter the fray!" }, ["npcs"] = { [1] = "Twiggy Flathead" }, ["priority"] = 1, ["text"] = "Гей, ти! До бою!" },
    [209065595] = { ["english"] = { [1] = "I thought I heard something." }, ["npcs"] = { [1] = "Roman" }, ["priority"] = 1, ["text"] = "Здається, я щось чув." },
    [2093730446] = { ["english"] = { [1] = "%s is demoralized and runs!" }, ["npcs"] = { [1] = "Affray Challenger" }, ["priority"] = 1, ["text"] = "%s здається і втікає!" },
    [2096701661] = { ["english"] = { [1] = "Get him!" }, ["npcs"] = { [1] = "Dark Iron Raider" }, ["priority"] = 1, ["text"] = "Схопіть {стать:його:її}!" },
    [2096984794] = { ["english"] = { [1] = "My talons will shred your puny body, <race>." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Мої пазурі розірвуть твоє нікчемне тіло, {раса:к}.#puny body, <race>." },
    [2097931599] = { ["english"] = { [1] = "Guards! Help me!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Варта! Допоможіть!" },
    [2099424499] = { ["english"] = { [1] = "I am released through you! Avenge me!" }, ["npcs"] = { [1] = "Chained Spirit" }, ["priority"] = 1, ["text"] = "Я вільний завдяки тобі! Помстись за мене!" },
    [2100716664] = { ["english"] = { [1] = "Barely hit the target that time. Hmmm,... maybe I need to adjust back to the right." }, ["npcs"] = { [1] = "Guard Lasiter" }, ["priority"] = 1, ["text"] = "Ледь влучив у ціль цього разу. Хмм... може, потрібно цілитись трохи правіше." },
    [2101560904] = { ["english"] = { [1] = "%s attempts to run away in fear!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s налякано тікає геть!" },
    [2102451766] = { ["english"] = { [1] = "Bash it!" }, ["npcs"] = { [1] = "Chok'sul" }, ["priority"] = 1, ["text"] = "Бити! Ламати!" },
    [2103885792] = { ["english"] = { [1] = "Open fire!" }, ["npcs"] = { [1] = "Captain Blackanvil" }, ["priority"] = 1, ["text"] = "Вогонь!" },
    [210703012] = { ["english"] = { [1] = "You're fired! <Cough...Cork clears throat.> I mean, help!" }, ["npcs"] = { [1] = "Cork Gizelton" }, ["priority"] = 1, ["text"] = "Тебе звільнено! Кхе-кхе... Тобто, допоможи!" },
    [2107571779] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "As if we don't have enough problems, you go and create more!" }, ["npcs"] = { [1] = "Cenarion Hold Reservist" }, ["priority"] = 1, ["text"] = "Нам тут вистачає проблем і без твоїх витівок!" } }, ["english"] = { [1] = "As if we don't have enough problems, you go and create more!" }, ["npcs"] = { [1] = "Cenarion Hold Infantry" }, ["priority"] = 1, ["text"] = "Нам тут вистачає проблем і без твоїх витівок!" },
    [2117600080] = { ["english"] = { [1] = "There is a way..." }, ["npcs"] = { [1] = "Merithra of the Dream" }, ["priority"] = 1, ["text"] = "Є спосіб..." },
    [2117704757] = { ["english"] = { [1] = "Hopefully the reinforcements from Stormwind show up soon. . . ." }, ["npcs"] = { [1] = "Chef Breanna" }, ["priority"] = 1, ["text"] = "Сподіваюся, підмога зі Штормовію скоро прибуде..." },
    [2119246472] = { ["english"] = { [1] = "Not a challenge at all it seems. Let us see how you handle your second test. Lysta, bring forth the minions of the Lich King." }, ["npcs"] = { [1] = "Brother Malach" }, ["priority"] = 1, ["text"] = "Здається, для вас це зовсім не виклик. Погляньмо, як ви справитесь із другим випробуванням. Лайсто, приведи слуг Короля-ліча." },
    [2119398776] = { ["english"] = { [1] = "The Night Watch alone cannot protect us forever.  We need the backing of the Stormwind Army." }, ["npcs"] = { [1] = "Lord Ello Ebonlocke" }, ["priority"] = 3, ["text"] = "Нічна варта не зможе захищати нас вічно. Нам потрібна підтримка армії Штормовію." },
    [212216446] = { ["english"] = { [1] = "By the Light!  This cursed spy was a good one!  I'm glad he's dead." }, ["npcs"] = { [1] = "Captain Garran Vimes" }, ["priority"] = 1, ["text"] = "Світлом клянуся! Цей проклятий шпигун був справжнім майстром своєї справи! Я радий, що він тепер мертвий." },
    [2122695541] = { ["english"] = { [1] = "Intruders in the keep! To arms!" }, ["npcs"] = { [1] = "Commander Springvale" }, ["priority"] = 1, ["text"] = "Чужинці проникли до фортеці! До зброї!" },
    [2126295736] = { ["english"] = { [1] = "Just a little taste..." }, ["npcs"] = { [1] = "Anub'Rekhan" }, ["priority"] = 1, ["text"] = "Скуштуємо свіжини..." },
    [2127726651] = { ["english"] = { [1] = "Kneel before me, worm!" }, ["npcs"] = { [1] = "Grand Widow Faerlina" }, ["priority"] = 1, ["text"] = "На коліна переді мною, мерзото!" },
    [2134163192] = { ["english"] = { [1] = "Destroy!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Нищити!" },
    [2135076495] = { ["english"] = { [1] = "Where we goin'?" }, ["npcs"] = { [1] = "Gil" }, ["priority"] = 1, ["text"] = "Куди ми йдемо?" },
    [2137705767] = { ["english"] = { [1] = "May your soul rest in peace." }, ["npcs"] = { [1] = "Baron Silverlaine" }, ["priority"] = 1, ["text"] = "Спочивай з миром." },
    [2140050443] = { ["english"] = { [1] = "Dying... See the light... gloriouss..." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Вмираю... Бачу світло... прекрасне..." },
    [2140768436] = { ["english"] = { [1] = "Hey, Harlan.  Here's a load of knitted cloth for you." }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Привіт, Гарлане. Я приніс нову партію в'язаних речей." },
    [2143712154] = { ["english"] = { [1] = "And crossing the line is the gnome car! The gnomes win!" }, ["npcs"] = { [1] = "Race Master Kronkrider" }, ["priority"] = 1, ["text"] = "І фінішну лінію перетинає машина гномів! Гноми перемогли!" },
    [2147860885] = { ["english"] = { [1] = "%s pokes the wooly sheep repeatedly." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "%s штрикає пальцем вівцю знову і знову." },
    [2156656195] = { ["english"] = { [1] = "Time to save the entire gnomish race. Here goes nothing!" }, ["npcs"] = { [1] = "Razzle Sprysprocket" }, ["priority"] = 1, ["text"] = "Час урятувати весь гном'ячий народ. Ну, поїхали!" },
    [2160407112] = { ["english"] = { [1] = "Another falls!" }, ["npcs"] = { [1] = "Archmage Arugal" }, ["priority"] = 1, ["text"] = "Чергова невдача!" },
    [2169209350] = { ["english"] = { [1] = "No time for beer!  The race is about to start." }, ["npcs"] = { [1] = "Gnome Pit Boss" }, ["priority"] = 1, ["text"] = "Немає часу на випивку! Перегони ось-ось почнуться." },
    [2169983480] = { ["english"] = { [1] = "The Brotherhood will not tolerate your actions." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Братство вам не пробачить." },
    [2173204924] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Wasn't that the night we had to pick up my thumb and carry it in your smoke pouch?" }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Хіба це не тоді ми пів ночі шукали мій палець в кущах?" } }, ["english"] = { [1] = "Wasn't that the night we had to pick up my thumb and carry it in your smoke pouch?" }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Хіба це не тоді ми пів ночі шукали мій палець в кущах?" },
    [2173460956] = { ["english"] = { [1] = "%s regains its power and breaks free of its bonds!" }, ["npcs"] = { [1] = "Pyroguard Emberseer" }, ["priority"] = 1, ["text"] = "%s відновлює силу та звільняється від пут!" },
    [2176189237] = { ["english"] = { [1] = "Grrrr... fresh meat!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Грррр... Свіже м'ясо!" },
    [2180022387] = { ["english"] = { [1] = "Annalise? Annalise! No, don't leave me!" }, ["npcs"] = { [1] = "Apothecary Staffron Lerent" }, ["priority"] = 1, ["text"] = "Анналіз? Анналіз! Ні, не покидай мене!" },
    [218870966] = { ["english"] = { [1] = "And Shindigger Stout too!  Thank the Light!  I was parched!" }, ["npcs"] = { [1] = "Captured Farmer" }, ["priority"] = 1, ["text"] = "Ще й \"Землекопське міцне\"! Хвала Світлу! Я вмираю від спраги!" },
    [2191519285] = { ["english"] = { [1] = "%s places the scroll on the table, and reads..." }, ["npcs"] = { [1] = "Captain Garran Vimes" }, ["priority"] = 1, ["text"] = "%s кладе сувій на стіл і читає..." },
    [2195518448] = { ["english"] = { [1] = "Get me out of here!" }, ["npcs"] = { [1] = "Kernobee" }, ["priority"] = 1, ["text"] = "Витягніть мене звідси!" },
    [2196148534] = { ["english"] = { [1] = "I may have ninety-nine problems, but dancin' ain't one of them!  Happy Hallow's End, <name>!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Обожнюю танці! Щасливого Повечір'я святих, {ім'я:к}!#Hallow's End, <name>!" },
    [219786331] = { ["english"] = { [1] = "%s only hits the side of the box!" }, ["npcs"] = { [1] = "Rifleman Wheeler" }, ["priority"] = 1, ["text"] = "%s влучає лише в бік ящика!" },
    [2201780582] = { ["english"] = { [1] = "Yes, Lord Mayor." }, ["npcs"] = { [1] = "Watcher Cutford" }, ["priority"] = 3, ["text"] = "Так, пане мер." },
    [2202791333] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ahh the Glustewelt twins!" }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Ух, ці близнюки Ґлустевельт!" } }, ["english"] = { [1] = "Ahh the Glustewelt twins!" }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Ух, ці близнюки Ґлустевельт!" },
    [2203045855] = { ["english"] = { [1] = "%s begins to regain its strength!" }, ["npcs"] = { [1] = "Pyroguard Emberseer" }, ["priority"] = 1, ["text"] = "%s починає відновлювати свої сили!" },
    [2204051357] = { ["english"] = { [1] = "Now, if I add the yellow ones..." }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "Отже, якщо додати жовті..." },
    [221045965] = { ["english"] = { [1] = "The secrets of Suntara will not leave these lands." }, ["npcs"] = { [1] = "Dark Iron Steelshifter" }, ["priority"] = 1, ["text"] = "Таємниці Сантари не покинуть ці землі." },
    [2210547466] = { ["english"] = { [1] = "I see right through your disguise, <race>. Number Two! Number Two kill!" }, ["npcs"] = { [1] = "Doctor Weavil" }, ["priority"] = 1, ["text"] = "Я бачу наскрізь твоє маскування, {раса:к}. Номер два! Номер два, вбити!#disguise, <race>." },
    [2211939] = { ["english"] = { [1] = "The beast is slain! All's well in Darkshire!" }, ["npcs"] = { [1] = "Town Crier" }, ["priority"] = 1, ["text"] = "Звіра переможено! Тепер Темноділ в безпеці!" },
    [2216953908] = { ["english"] = { [1] = "Bran!  I'm finished!" }, ["npcs"] = { [1] = "Tormus Deepforge" }, ["priority"] = 3, ["text"] = "Бране!  Я закінчив!" },
    [2217772030] = { ["english"] = { [1] = "Brazenly you have disregarded powers beyond your understanding." }, ["npcs"] = { [1] = "Gothik the Harvester" }, ["priority"] = 1, ["text"] = "Ви зухвало знехтували силами, що виходять за межі вашого розуміння." },
    [2225369516] = { ["english"] = { [1] = "This land belongs to the Defias Brotherhood now!" }, ["npcs"] = { [1] = "Defias Thug" }, ["priority"] = 1, ["text"] = "Ці землі тепер належать Братству Непокірних!" },
    [2225825820] = { ["english"] = { [1] = "Free drinks at the Blue Recluse!" }, ["npcs"] = { [1] = "Erich Lohan" }, ["priority"] = 1, ["text"] = "Безплатні напої у \"Синьому Відлюднику\"!" },
    [2226782816] = { ["english"] = { [1] = "No one get past me and threaten da king!  Ungh, take it!!" }, ["npcs"] = { [1] = "Captain Kromcrush" }, ["priority"] = 1, ["text"] = "Я нікому не дозволю погрожувать королю! На, ось тобі!!" },
    [222817313] = { ["english"] = { [1] = "BETRAYER!" }, ["npcs"] = { [1] = "Spirit of Trey Lightforge" }, ["priority"] = 1, ["text"] = "ЗРАДНИКИ!" },
    [2233079587] = { ["english"] = { [1] = "Die in the name of Edwin Van Cleef!" }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "Помри в імʼя Едвіна Ван-Кліфа!" },
    [2237871519] = { ["english"] = { [1] = "Stop pulling her hair out!" }, ["npcs"] = { [1] = "Donna" }, ["priority"] = 1, ["text"] = "Не виривай їй волосся!" },
    [2238634998] = { ["english"] = { [1] = "So dark..." }, ["npcs"] = { [1] = "Artist Renfray" }, ["priority"] = 1, ["text"] = "Як темно..." },
    [2245737145] = { ["english"] = { [1] = "Ahh there it is." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Ага, ось воно." },
    [224579938] = { ["english"] = { [1] = "It's Proudmoore! Get out of here!" }, ["npcs"] = { [1] = "Theramore Sentry" }, ["priority"] = 1, ["text"] = "Це Праудмур! Вшиваймося!" },
    [22490369] = { ["english"] = { [1] = "Die, outlander!" }, ["npcs"] = { [1] = "Chief Ukorz Sandscalp" }, ["priority"] = 1, ["text"] = "Помріть, чужинці!" },
    [2253542321] = { ["english"] = { [1] = "Sounds kinda like one of Billy's fish stories to me." }, ["npcs"] = { [1] = "Brandon" }, ["priority"] = 1, ["text"] = "Звучить, як одна з вигадок Біллі." },
    [2255274652] = { ["english"] = { [1] = "Get in position lads! The beasties are upon us. Wait for my signal!" }, ["npcs"] = { [1] = "Avarus Kharag" }, ["priority"] = 1, ["text"] = "Займіть позиції, хлопці! Звірі вже тут. Чекайте на мій сигнал!" },
    [2255858794] = { ["english"] = { [1] = "And might I add, that dress is lovely! You must tell me where you got it from." }, ["npcs"] = { [1] = "Scarlet Commander Marjhan" }, ["priority"] = 1, ["text"] = "Дозвольте зазначити, ця сукня неймовірно гарна! Вам дуже личить." },
    [2256885755] = { ["english"] = { [1] = "%s hands the Scepter of the Shifting Sands to Fandral Staghelm." }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "%s передає Фендралу Оленерогу скіпетр Мінливих Пісків." },
    [2257273925] = { ["english"] = { [1] = "Privates Fontane, MacDugal, Wilcott..." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "Рядові Фонтейн, МакДуґал, Вілкот..." },
    [2259865576] = { ["english"] = { [1] = "You outsiders will pay for encroaching on our land!" }, ["npcs"] = { [1] = "Charlga Razorflank" }, ["priority"] = 1, ["text"] = "Ви, чужинці, поплатитесь за вторгнення на нашу землю!" },
    [2261757394] = { ["english"] = { [1] = "You are no match for the Blackrock Orcs!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ти не рівня оркам Чорнокаменю!" },
    [2262083242] = { ["english"] = { [1] = "%s begins to summon in a Blackhand Veteran!" }, ["npcs"] = { [1] = "Blackhand Summoner" }, ["priority"] = 1, ["text"] = "%s починає викликати ветерана Чорнорука!" },
    [2262837276] = { ["english"] = { [1] = "We'll cut your throats and bleed you dry!" }, ["npcs"] = { [1] = "Dark Strand Assassin" }, ["priority"] = 1, ["text"] = "Ми переріжемо ваші горлянки й випустимо всю кров!" },
    [2266553691] = { ["english"] = { [1] = "Help the children of Stormwind... victims of the war and plague!" }, ["npcs"] = { [1] = "John Turner" }, ["priority"] = 1, ["text"] = "Допоможіть дітям Штормовію... жертвам війни та чуми!" },
    [2272647552] = { ["english"] = { [1] = "My weapon be thirsty!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Моя зброя хоче крові!" },
    [2274155253] = { ["english"] = { [1] = "A foul trogg if ever I saw one.  Die!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ще не бачив таких бридких трогів. Здохни!" },
    [2276861490] = { ["english"] = { [1] = "Skam!" }, ["npcs"] = { [1] = "Zandalar Enforcer" }, ["priority"] = 1, ["text"] = "Паскуда!" },
    [2280575392] = { ["english"] = { [1] = "What is this? Did Keever ask for a sheep? Keever wanted a weapon of great power and all he got was this sheep. Keever is very disappointed." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "Що це таке? Хіба Ківер хотів вівцю? Ківер хотів потужну зброю, а замість цього отримав лише цю вівцю. Ківер дуже розчарований." },
    [2282013531] = { ["english"] = { [1] = "First Westfall, next, all of Stormwind!" }, ["npcs"] = { [1] = "Defias Raider" }, ["priority"] = 1, ["text"] = "Спочатку Західний край, а далі — весь Штормовій!" },
    [2282864288] = { ["english"] = { [1] = "Guess there's nothing more to be done. Blast!" }, ["npcs"] = { [1] = "Rizzle Brassbolts" }, ["priority"] = 1, ["text"] = "Певно, тут вже нічого не вдієш. Прокляття!" },
    [2286549921] = { ["english"] = { [1] = "Anti-escape countermeasures activated. Self-destruct in t-minus 20 seconds...." }, ["npcs"] = { [1] = "Alarm-a-bomb 2600" }, ["priority"] = 1, ["text"] = "Засоби протидії втечі активовано. Самознищення через 20 секунд...." },
    [2290350830] = { ["english"] = { [1] = "Is this a mango? Stupendous!" }, ["npcs"] = { [1] = "Father Inigo Montoy" }, ["priority"] = 1, ["text"] = "Це що, манго? Дивовижно!" },
    [2296240160] = { ["english"] = { [1] = "Ramstein hunger for flesh!" }, ["npcs"] = { [1] = "Ramstein the Gorger" }, ["priority"] = 1, ["text"] = "Рамштайн жадає плоті!" },
    [2296559617] = { ["english"] = { [1] = "A warm tavern and a cold ale. What more could we ask for?" }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Тепла таверна і холодний ель. Що ще потрібно для щастя?" },
    [2303124667] = { ["english"] = { [1] = "Thieves! I shall smelt your remains!" }, ["npcs"] = { [1] = "Crimson Hammersmith" }, ["priority"] = 1, ["text"] = "Злодії! Я переплавлю ваші рештки!" },
    [2304120575] = { ["english"] = { [1] = "Oh, it's on now! Bet you thought I'd be alone too, huh?!" }, ["npcs"] = { [1] = "Tapoke \"Slim\" Jahn" }, ["priority"] = 1, ["text"] = "Ого, то все серйозно! Але ти ж не {стать:думав:думала}, що я теж буду сам, ге ж?!" },
    [2306586681] = { ["english"] = { [1] = "Hm... if you're looking to adle wits, <name>, then the secret behind Zanzil's zombies might just do the trick!" }, ["npcs"] = { [1] = "Crank Fizzlebub" }, ["priority"] = 1, ["text"] = "Хм... Знаю, {ім'я:н}! Щоб задурити голову, нам можуть допомогти ті безмізкі зомбі Занзіла!#wits, <name>, then" },
    [2307364207] = { ["english"] = { [1] = "We can only stay a few moments before returning to the tower. If you wish to speak to us more you may find us there." }, ["npcs"] = { [1] = "Archmage Tervosh" }, ["priority"] = 1, ["text"] = "Ми затримаємося на кілька хвилин перед поверненням до вежі. Якщо захочеш продовжити розмову — зустрінемось там." },
    [2310699347] = { ["english"] = { [1] = "Hullo, Trias clan!  A ball of your smoked mozzarella, if you please!" }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Вітаю, Тріаси! Мені кульку вашої копченої моцарели, будь ласка!" },
    [2317997572] = { ["english"] = { [1] = "Haha! Sturdy old Trollplow has just a few meager battle scars!" }, ["npcs"] = { [1] = "Pilot Stonegear" }, ["priority"] = 3, ["text"] = "Ха-ха! У міцного старого Тролеплуга всього кілька жалюгідних бойових шрамів!" },
    [2319402592] = { ["english"] = { [1] = "Scðpper!  I'm finished!" }, ["npcs"] = { [1] = "Tormus Deepforge" }, ["priority"] = 3, ["text"] = "Скіппере! Я закінчив!" },
    [232282228] = { ["english"] = { [1] = "Foolish <class>!  You are no match for the minions of Ragnaros!" }, ["npcs"] = { [1] = "Balgaras the Foul" }, ["priority"] = 1, ["text"] = "{стать:Дурний:Дурна} {клас:н}! Ти не рівня слугам Раґнароса!#Foolish <class>!" },
    [2323969113] = { ["english"] = { [1] = "Sweet, sweet embrace... take me..." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ніжні обійми... смерті... заберіть мене..." },
    [2325812430] = { ["english"] = { [1] = "Do not fail us!" }, ["npcs"] = { [1] = "Darrowshire Poltergeist" }, ["priority"] = 1, ["text"] = "Не підведи нас!" },
    [2328240315] = { ["english"] = { [1] = "Death is the only escape!" }, ["npcs"] = { [1] = "Gothik the Harvester" }, ["priority"] = 1, ["text"] = "Смерть — це єдиний порятунок!" },
    [2329284955] = { ["english"] = { [1] = "Mommy? Can I pet Fizzles?" }, ["npcs"] = { [1] = "Paige Chaddis" }, ["priority"] = 1, ["text"] = "Мамо? А можна я погладжу Бульчика?" },
    [2332994119] = { ["english"] = { [1] = "Your recklessness will doom us all!" }, ["npcs"] = { [1] = "Windshaper Novice Seer" }, ["priority"] = 3, ["text"] = "Твоя безрозсудність прирече нас усіх!" },
    [2335849233] = { ["english"] = { [1] = "Time to take matters into my own hands. Come. Enter my domain and challenge the might of the Scourge!" }, ["npcs"] = { [1] = "Baron Rivendare" }, ["priority"] = 1, ["text"] = "Час взяти все у свої руки. Вперед, увійдіть у мої володіння та киньте виклик могутності Скари!" },
    [2337038046] = { ["english"] = { [1] = "Bloody... Must have been the goblins... Let's see how bad the damage is." }, ["npcs"] = { [1] = "Rizzle Brassbolts" }, ["priority"] = 1, ["text"] = "Трясця… Певно, це були гобліни… Подивимося, наскільки пошкодження серйозні." },
    [233729184] = { ["english"] = { [1] = "Me smash! You die!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Я бити! Ти вмирати!" },
    [2338488513] = { ["english"] = { [1] = "%s breaks free of its spectral bonds with a tremendous crash of thunder!" }, ["npcs"] = { [1] = "Ancient Equine Spirit" }, ["priority"] = 1, ["text"] = "%s виривається зі своїх примарних пут із приголомшливим гуркотом!" },
    [2338815172] = { ["english"] = { [1] = "Stay on the roads.  The forest is overrun with undead." }, ["npcs"] = { [1] = "Commander Althea Ebonlocke" }, ["priority"] = 1, ["text"] = "Тримайтеся доріг. Ліс кишить невмерлими." },
    [2338899316] = { ["english"] = { [1] = "You think you've won already? Perhaps you'll need another lesson in pain!" }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Думаєте, ви вже перемогли? Можливо, вам варто засвоїти ще один урок болю!" },
    [2340035752] = { ["english"] = { [1] = "Looks like it's going to be one of those days." }, ["npcs"] = { [1] = "Captain Blackanvil" }, ["priority"] = 1, ["text"] = "Схоже, що сьогодні буде весело." },
    [2340797632] = { ["english"] = { [1] = "Edward. Tyler. Prepare for your first challenge." }, ["npcs"] = { [1] = "Brother Malach" }, ["priority"] = 1, ["text"] = "Едвард. Тайлер. Приготуйтесь до першого випробування." },
    [2348086744] = { ["english"] = { [1] = "%s hurls the Scepter of the Shifting Sands into the barrier, shattering it." }, ["npcs"] = { [1] = "Fandral Staghelm" }, ["priority"] = 1, ["text"] = "%s кидає скіпетр Мінливих Пісків у бар'єр, розбиваючи його." },
    [2348432499] = { ["english"] = { [1] = "Kill them all!" }, ["npcs"] = { [1] = "Defias Rioter" }, ["priority"] = 1, ["text"] = "Вбийте їх усіх!" },
    [2348985311] = { ["english"] = { [1] = "FOOL! YOU ALLOWED THESE INSECTS TO RUN RAMPANT THROUGH THE HALLOWED CORE? AND NOW YOU LEAD THEM TO MY VERY LAIR? YOU HAVE FAILED ME, EXECUTUS! JUSTICE SHALL BE MET, INDEED!" }, ["npcs"] = { [1] = "Ragnaros" }, ["priority"] = 1, ["text"] = "ДУРЕНЬ! ТИ ДОЗВОЛИВ ЦИМ КОМАХАМ РОЗГУЛЮВАТИ ПО СВЯЩЕННОМУ ЯДРУ? І ТЕПЕР ТИ ПРИВІВ ЇХ ДО МОГО ЛІГВА? ТИ ПІДВІВ МЕНЕ, ЕКЗЕКУТУС! І ТИ ОТРИМАЄШ СПРАВЕДЛИВЕ ПОКАРАННЯ!" },
    [2350960992] = { ["english"] = { [1] = "Lysta, summon in undead captives." }, ["npcs"] = { [1] = "Brother Malach" }, ["priority"] = 1, ["text"] = "Лайсто, виклич полонених невмерлих." },
    [2358623327] = { ["english"] = { [1] = "Billy says Fizzles used to be a great wizard. But he got turned into a rabbit when one of his spells went bad." }, ["npcs"] = { [1] = "Gil" }, ["priority"] = 1, ["text"] = "Біллі каже, що колись Бульчик був великим чарівником. Але він перетворився на кролика через невдале закляття." },
    [2360893354] = { ["english"] = { [1] = "I'm going to wear your skin as a smoking jacket! The stogies? You'll have to pry them from my cold dead... er... RAWR!!!!" }, ["npcs"] = { [1] = "Ezra Grimm" }, ["priority"] = 1, ["text"] = "Я з ваших шкур собі куртку зроблю! Сигари? Вам доведеться вирвати їх з моїх холодних.... мертвих... Е... РРРР!!!!" },
    [2360996199] = { ["english"] = { [1] = "It was your leadership that manipulated a grieving child to try and recover the sword. A child that has grown into a man with nothing but vengeance and hatred in his heart! And for what? You are no closer to the sword now than you were five years ago." }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Це ви маніпулювали скорботною дитиною, щоб спробувати повернути меч. І ця дитина стала чоловіком, серце якого сповнене лише помстою та ненавистю! І заради чого? Ви зараз не ближче до меча, ніж були п'ять років тому." },
    [23665151] = { ["english"] = { [1] = "Aber?  Is that you...?  Oh...I'm so hungry, Aber!  SO HUNGRY!!" }, ["npcs"] = { [1] = "Eliza" }, ["priority"] = 1, ["text"] = "Кромбі? Це ти...? Ох... Я така голодна, Кромбі! ТАКА ГОЛОДНА!" },
    [2368504048] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The only good <race> is a dead <race>!" }, ["npcs"] = { [1] = "Grawmug" }, ["priority"] = 1, ["text"] = "{стать:Хороший:Хороша} {раса:н} — {стать:мертвий:мертва} {раса:н}!#dead <race>!" }, [2] = { ["english"] = { [1] = "The only good <race> is a dead <race>!" }, ["npcs"] = { [1] = "Magosh" }, ["priority"] = 1, ["text"] = "{стать:Хороший:Хороша} {раса:н} — {стать:мертвий:мертва} {раса:н}!#dead <race>!" } }, ["english"] = { [1] = "The only good <race> is a dead <race>!" }, ["npcs"] = { [1] = "Boss Galgosh" }, ["priority"] = 1, ["text"] = "{стать:Хороший:Хороша} {раса:н} — {стать:мертвий:мертва} {раса:н}!#dead <race>!" },
    [2377395441] = { ["english"] = { [1] = "Intruders! Attack the intruders!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Чужинці! Вбийте їх!" },
    [2383577744] = { ["english"] = { [1] = "You hasten our... destruction..." }, ["npcs"] = { [1] = "Windshaper Novice Seer" }, ["priority"] = 3, ["text"] = "Ти наближаєш нашу... загибель..." },
    [2388096878] = { ["english"] = { [1] = "I heard a story about this golden fish, and if you caught it you would get three wishes!" }, ["npcs"] = { [1] = "Billy" }, ["priority"] = 1, ["text"] = "Я чув історію про золоту рибку. Здається, якщо її зловиш, то зможеш загадати три бажання!" },
    [2401232758] = { ["english"] = { [1] = "Huuup...Huuup...Bleeeeehh!" }, ["npcs"] = { [1] = "Hargin Mundar" }, ["priority"] = 3, ["text"] = "Хууп... Хууп... Бле-е-е-е!" },
    [2402606586] = { ["english"] = { [1] = "The king is dead - OH NOES!  Summon Mizzle da Crafty!  He knows what to do next!" }, ["npcs"] = { [1] = "Cho'Rush the Observer" }, ["priority"] = 1, ["text"] = "Король мертвий — О НІ! Покличте Міззла Кмітливого! Він знає, шо робить далі!" },
    [2402635574] = { ["english"] = { [1] = "Ah, that sure does hit the spot!  I think I'll get myself a couple more...can you watch these barrels for me, <name>?" }, ["npcs"] = { [1] = "Jarven Thunderbrew" }, ["priority"] = 3, ["text"] = "Ох, оце саме те, що треба!  Піду візьму собі ще парочку...приглянеш за цими бочками, {ім'я:к}, поки мене нема?" },
    [2402988584] = { ["english"] = { [1] = "The serum will only take a few minutes to prepare, <name>." }, ["npcs"] = { [1] = "Apothecary Faustin" }, ["priority"] = 1, ["text"] = "Приготування сироватки займе всього кілька хвилин, {ім'я:к}.#to prepare, <name>." },
    [2405539747] = { ["english"] = { [1] = "But of course I love you, Staffron. And it pains me to see you suffer so." }, ["npcs"] = { [1] = "Annalise Lerent" }, ["priority"] = 1, ["text"] = "Але я люблю тебе, Стаффроне. І мені боляче бачити, як ти страждаєш." },
    [2407662936] = { ["english"] = { [1] = "Help a poor bloke out?" }, ["npcs"] = { [1] = "Ol' Beasley" }, ["priority"] = 3, ["text"] = "Допоможете бідоласі?" },
    [2408862368] = { ["english"] = { [1] = "Lysta, summon in the captives." }, ["npcs"] = { [1] = "Brother Malach" }, ["priority"] = 1, ["text"] = "Лайсто, виклич полонених." },
    [2409443554] = { ["english"] = { [1] = "I shall enjoy this, <race>." }, ["npcs"] = { [1] = "Franklin the Friendly" }, ["priority"] = 1, ["text"] = "Я насолоджуватимусь цим, {раса:к}.#this, <race>." },
    [2411910374] = { ["english"] = { [1] = "Lord Mayor!  Our scouts report strange activity to the west." }, ["npcs"] = { [1] = "Watcher Cutford" }, ["priority"] = 3, ["text"] = "Пане мер!  Наші розвідники доповідають про дивну активність на заході." },
    [2413243812] = { ["english"] = { [1] = "Alexstrasza grant me the resolve to drive our enemies back!" }, ["npcs"] = { [1] = "Caelestrasz" }, ["priority"] = 1, ["text"] = "Алекстразо, даруй мені сил дати відсіч нашим ворогам!" },
    [2418585415] = { ["english"] = { [1] = "Well, back to business for me.  But it sure was nice taking that short break, and it's always nice drinking Thunder Ale!" }, ["npcs"] = { [1] = "Jarven Thunderbrew" }, ["priority"] = 1, ["text"] = "Ну, час повертатися до справ.  Але ж добре було трохи перепочити, та й Громовий ель завжди приємно випити!" },
    [2424546413] = { ["english"] = { [1] = "%s grabs the rabbit and pours the fluid down it's throat, then sets it back inside the cage." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "%s хапає кролика, заливає йому в горло рідину, а потім повертає його у клітку." },
    [2426320674] = { ["english"] = { [1] = "Reckless mortals! None may challenge the Sons of the Living flame!" }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Безрозсудні смертні! Ніхто не сміє кидати виклик Синам Живого Полум'я!" },
    [2427712795] = { ["english"] = { [1] = "Justice is done!" }, ["npcs"] = { [1] = "Sandfury Executioner" }, ["priority"] = 1, ["text"] = "Правосуддя здійснено!" },
    [2428518472] = { ["english"] = { [1] = "Our vigilance is eternal..." }, ["npcs"] = { [1] = "Commander Springvale" }, ["priority"] = 1, ["text"] = "Наша варта вічна..." },
    [2430883155] = { ["english"] = { [1] = "Do not lose hope, Darrowshire!  We will not fall!" }, ["npcs"] = { [1] = "Davil Lightfire" }, ["priority"] = 1, ["text"] = "Не втрачай надії, Дарроушире! Ми не здамося!" },
    [2431212618] = { ["english"] = { [1] = "My turn, meathead! I get to throw now." }, ["npcs"] = { [1] = "Blackhand Thug" }, ["priority"] = 1, ["text"] = "Моя черга, придурок! Зараз я кидаю." },
    [2435772989] = { ["english"] = { [1] = "Look alive, dogs! We got an operation to run here!" }, ["npcs"] = { [1] = "Defias Dockmaster" }, ["priority"] = 1, ["text"] = "Сюди, пси! У нас тут шпигун!" },
    [2436880928] = { ["english"] = { [1] = "Death to the Warden!" }, ["npcs"] = { [1] = "Defias Rioter" }, ["priority"] = 1, ["text"] = "Смерть наглядачу!" },
    [2437565958] = { ["english"] = { [1] = "Soldiers of Kalimdor! Heroes of Silithus! One among you has dealt a vicious blow to our mortal enemies! <name> and <his/her> allies have relieved the Ruins of Ahn'Qiraj of its merciless leader! Ossirian the Unscarred, scourge of Silithus, has finally been destroyed and his armies wholly dismantled!" }, ["npcs"] = { [1] = "Commander Mar'alith" }, ["priority"] = 1, ["text"] = "Воїни Калімдору! Герої Силітуса! Одні з вас завдали нещадного удару нашим ворогам! {ім'я:к} та {стать:його:її} союзники звільнили руїни Ан'Кіражу від їх безжального ватажка! Оссіріан Невразливий, лихо Силітуса, нарешті знищений, а його війська повністю розгромлені!#enemies! <name> and#and <his/her> allies" },
    [2443299200] = { ["english"] = { [1] = "I'm Augustus!  You want it, I got it!  You wanna sell it, then I want it!" }, ["npcs"] = { [1] = "Augustus the Touched" }, ["priority"] = 1, ["text"] = "Я Август! Хочеш щось купити — я це продам! Хочеш щось продати — я це куплю!" },
    [2445261194] = { ["english"] = { [1] = "Stand ready!" }, ["npcs"] = { [1] = "Captain Blackanvil" }, ["priority"] = 1, ["text"] = "Готуйсь!" },
    [2449643246] = { ["english"] = { [1] = "<name>!  Betrayer of Ragnaros!" }, ["npcs"] = { [1] = "Balgaras the Foul" }, ["priority"] = 1, ["text"] = "{ім'я:н}! {стать:Зрадник:Зрадниця} Раґнароса!#<name>!  Betrayer" },
    [245203085] = { ["english"] = { [1] = "Constant bickering will get us nowhere.  We need to take action." }, ["npcs"] = { [1] = "Role Dreuger" }, ["priority"] = 3, ["text"] = "Постійні чвари ні до чого нас не приведуть. Треба діяти." },
    [2455573458] = { ["english"] = { [1] = "The news from Stormwind does not bode well. . . ." }, ["npcs"] = { [1] = "Ambassador Berrybuck" }, ["priority"] = 1, ["text"] = "Новини зі Штормовію невтішні..." },
    [2458564180] = { ["english"] = { [1] = "No gnome will be left behind." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Не лишим жодного гнома в біді." },
    [2459955564] = { ["english"] = { [1] = "Who dares interfere with the business of the Defias Brotherhood?  Die <class>!" }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "Хто сміє втручатися в справи Братства Непокірних? Помри, {клас:к}!#Die <class>!" },
    [2463252334] = { ["english"] = { [1] = "I've been better.  Ivar the Foul got the better of me..." }, ["npcs"] = { [1] = "Quinn Yorick" }, ["priority"] = 1, ["text"] = "Бувало й краще. Айвар Нечистий трохи попсував життя..." },
    [2464402816] = { ["english"] = { [1] = "I have your dolly! Nyah nyah!" }, ["npcs"] = { [1] = "William" }, ["priority"] = 1, ["text"] = "У мене твоя лялька! Бе-бе-бе!" },
    [2465606605] = { ["english"] = { [1] = "TASTE THE FLAMES OF SULFURON!" }, ["npcs"] = { [1] = "Ragnaros" }, ["priority"] = 1, ["text"] = "СКУШТУЙТЕ ПОЛУМ'Я СУЛЬФУРОНА!" },
    [2469927355] = { ["english"] = { [1] = "A-Me good. Good, A-Me. Follow... follow A-Me. Home. A-Me go home." }, ["npcs"] = { [1] = "A-Me 01" }, ["priority"] = 1, ["text"] = "Е-Мі хороша. Е-Мі. Хороша. Йти... йти за Е-Мі. Дім. Е-Мі йти додому." },
    [2471242898] = { ["english"] = { [1] = "We will push them back, Anachronos. This I vow. Uphold your end of this task. Let not your hands falter as you seal our fates behind the barrier." }, ["npcs"] = { [1] = "Merithra of the Dream" }, ["priority"] = 1, ["text"] = "Ми відтіснимо їх, Анахроносе. Я клянуся. Виконай свою частину справи. Нехай твої руки не тремтять, коли ти запечатуватимеш нашу долю за бар'єром." },
    [2471581622] = { ["english"] = { [1] = "If you want her back you're gonna have to beg!" }, ["npcs"] = { [1] = "William" }, ["priority"] = 1, ["text"] = "Якщо хочеш повернути її — доведеться благати!" },
    [2473347045] = { ["english"] = { [1] = "Ha! You can't even begin to imagine the futility of your efforts." }, ["npcs"] = { [1] = "Emperor Dagran Thaurissan" }, ["priority"] = 1, ["text"] = "Ха! Ви навіть не здатні уявити всю марність ваших зусиль." },
    [2481788805] = { ["english"] = { [1] = "Now be silent and note where you are, lest I inform Lord Fordring and his knights that you are no longer here on amicable terms. I am certain he would take great pleasure in seeing to your 'atonement.'" }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "А тепер помовчіть та згадайте, де знаходитесь, інакше я повідомлю лорду Фордрінґу та його лицарям, що вам тут більше не раді. Я впевнений, що він буде радий бачити вашу \"спокуту\"." },
    [2484404171] = { ["english"] = { [1] = "And it's the Gnome Racer coming through turn one!" }, ["npcs"] = { [1] = "Fobeed" }, ["priority"] = 1, ["text"] = "І гонщик гномів проходить перший поворот!" },
    [2486665637] = { ["english"] = { [1] = "%s begins to summon wraiths out of the freezing cold air!" }, ["npcs"] = { [1] = "Amnennar the Coldbringer" }, ["priority"] = 1, ["text"] = "%s починає викликати морозних привидів!" },
    [2490125146] = { ["english"] = { [1] = "The charges are set. Get back before they blow!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Заряди встановлені. Відійдіть, поки вони не вибухнули!" },
    [2492664721] = { ["english"] = { [1] = "Merok!  Shai!  To my side!" }, ["npcs"] = { [1] = "Krug Skullsplit" }, ["priority"] = 1, ["text"] = "Мерок! Шаї! До мене!" },
    [2493098160] = { ["english"] = { [1] = "We hunger for vengeance." }, ["npcs"] = { [1] = "Bloodmage Thalnos" }, ["priority"] = 1, ["text"] = "Ми прагнемо помсти." },
    [2493772807] = { ["english"] = { [1] = "Glad to see you're doing so well, Harlan.  And I hope to see you again soon..." }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Радий бачити, що у тебе все гаразд, Гарлане. Сподіваюся, незабаром знову побачимось..." },
    [2501324654] = { ["english"] = { [1] = "Succumb to the endless dream, little ones. Let it consume you!" }, ["npcs"] = { [1] = "Merithra of the Dream" }, ["priority"] = 1, ["text"] = "Скоріться вічному сну, виродки. Нехай він поглине вас!" },
    [2501661725] = { ["english"] = { [1] = "DIE!" }, ["npcs"] = { [1] = "Defias Rioter" }, ["priority"] = 1, ["text"] = "ЗДОХНИ!" },
    [2501713200] = { ["english"] = { [1] = "Concentrate your attacks upon the healer!" }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Зосередьте атаки на цілителі!" },
    [2505577163] = { ["english"] = { [1] = "%s yawns." }, ["npcs"] = { [1] = "Doctor Weavil" }, ["priority"] = 1, ["text"] = "%s позіхає." },
    [2507800932] = { ["english"] = { [1] = "Okay, okay! No need to get all violent. I'll talk. I'll talk!" }, ["npcs"] = { [1] = "Tapoke \"Slim\" Jahn" }, ["priority"] = 1, ["text"] = "Гаразд, гаразд! Досить цього насильства. Я все скажу!" },
    [2508488588] = { ["english"] = { [1] = "NO! What have they done to you!?" }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "НІ! Що вони з тобою зробили!?" },
    [2509099507] = { ["english"] = { [1] = "I hope your spirit finds solace." }, ["npcs"] = { [1] = "Baron Silverlaine" }, ["priority"] = 1, ["text"] = "Сподіваюсь, твоя душа знайде спокій." },
    [2516590261] = { ["english"] = { [1] = "%s spots a zombie to devour!" }, ["npcs"] = { [1] = "Gluth" }, ["priority"] = 1, ["text"] = "%s помічає зомбі, якого можна зжерти!" },
    [2517211028] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Never seen anyone move so fast in my whole life." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Ніколи в житті не бачив, щоб хтось рухався так швидко." } }, ["english"] = { [1] = "Never seen anyone move so fast in my whole life." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Ніколи в житті не бачив, щоб хтось рухався так швидко." },
    [2518908346] = { ["english"] = { [1] = "No two-bit traitor will stop the powder from getting to Ironband!" }, ["npcs"] = { [1] = "Huldar" }, ["priority"] = 1, ["text"] = "Жоден жалюгідний зрадник не завадить доставити порох Залізносмугу!" },
    [2524513457] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "%s goes into a frenzy!" }, ["npcs"] = { [1] = "Gluth" }, ["priority"] = 1, ["text"] = "%s впадає в шаленство!" } }, ["english"] = { [1] = "%s goes into a frenzy!" }, ["npcs"] = { [1] = "Flamegor" }, ["priority"] = 1, ["text"] = "%s впадає в шаленство!" },
    [2524779254] = { ["english"] = { [1] = "How can I get anything done with the Scourge running amok in here?!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Як я можу щось робити, коли тут розгулює Скара?!" },
    [2537023594] = { ["english"] = { [1] = "The first stage is over.  Big Will... come on down!" }, ["npcs"] = { [1] = "Twiggy Flathead" }, ["priority"] = 1, ["text"] = "Перший етап завершено. Здоровань Вілл... до бою!" },
    [2539557602] = { ["english"] = { [1] = "My machines are the future! They'll destroy you all!" }, ["npcs"] = { [1] = "Mekgineer Thermaplugg" }, ["priority"] = 1, ["text"] = "Мої машини — це майбутнє! Вони знищать вас усіх!" },
    [2539742921] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Weak <class>! You are no match for the Stonesplinter Tribe!" }, ["npcs"] = { [1] = "Grawmug" }, ["priority"] = 1, ["text"] = "{стать:Слабкий:Слабка} {клас:н}! Ти не рівня племені Каменедробів!#Weak <class>!" }, [2] = { ["english"] = { [1] = "Weak <class>! You are no match for the Stonesplinter Tribe!" }, ["npcs"] = { [1] = "Magosh" }, ["priority"] = 1, ["text"] = "{стать:Слабкий:Слабка} {клас:н}! Ти не рівня племені Каменедробів!#Weak <class>!" } }, ["english"] = { [1] = "Weak <class>! You are no match for the Stonesplinter Tribe!" }, ["npcs"] = { [1] = "Boss Galgosh" }, ["priority"] = 1, ["text"] = "{стать:Слабкий:Слабка} {клас:н}! Ти не рівня племені Каменедробів!#Weak <class>!" },
    [2544152886] = { ["english"] = { [1] = "Bawk, bawk, bawk!  Happy Hallow's End, <name>!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Куд-куд-кудак! Щасливого Повечір'я святих, {ім'я:к}!#Hallow's End, <name>!" },
    [2546813352] = { ["english"] = { [1] = "King Magni Bronzebeard is a fool and a charlatan!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Король Маґні Бронзобородий — дурень і брехун!" },
    [2550831749] = { ["english"] = { [1] = "<target> coming this way fast!  Prepare for attack!" }, ["npcs"] = { [1] = "Corporal Keeshan" }, ["priority"] = 1, ["text"] = "{Ціль} йде сюди! Готуйся до атаки!#<target> coming" },
    [2552348317] = { ["english"] = { [1] = "Liar!" }, ["npcs"] = { [1] = "Adam" }, ["priority"] = 1, ["text"] = "Брехун!" },
    [2552379074] = { ["english"] = { [1] = "You are a little gnat to the Foulweald!  Die!" }, ["npcs"] = { [1] = "Chief Murgut" }, ["priority"] = 1, ["text"] = "Ти — лиш дрібна комаха для Гидколісових! Помри!" },
    [2554416143] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I tell ye, I don't miss the Great War at all. I remember when we fought at Darrowmere. All night in the fog, lying in a muddy trench." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Кажу ж, я зовсім не сумую за Великою Війною. Пам'ятаю, як ми билися при Дарроумері. Всю ніч у тумані, ще й по пояс в багнюці." } }, ["english"] = { [1] = "I tell ye, I don't miss the Great War at all. I remember when we fought at Darrowmere. All night in the fog, lying in a muddy trench." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Еге, я зовсім не сумую за Великою Війною. Пам'ятаю, як ми билися при Дарроумері. Всю ніч тоді човгали окопами по пояс в багнюці." },
    [2555134572] = { ["english"] = { [1] = "You better back me up on this one!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Краще допоможи мені!" },
    [255528522] = { ["english"] = { [1] = "Yip! Me kill!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Йой! Я вбивати!" },
    [2557944483] = { ["english"] = { [1] = "Mistress!! They seek to destroy your work!!" }, ["npcs"] = { [1] = "Blood Elf Defender" }, ["priority"] = 1, ["text"] = "Володарко!! Вони хочуть знищити вашу працю!!" },
    [2560020184] = { ["english"] = { [1] = "Yea?" }, ["npcs"] = { [1] = "Defias Tower Patroller" }, ["priority"] = 1, ["text"] = "А?" },
    [2560234548] = { ["english"] = { [1] = "Get your seats, folks!  The race is starting in 2 minutes!" }, ["npcs"] = { [1] = "Race Master Kronkrider" }, ["priority"] = 1, ["text"] = "Займайте місця, шановні! Перегони почнуться за 2 хвилини!" },
    [2560897068] = { ["english"] = { [1] = "Thanks for the cheese!" }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Дякую за сир!" },
    [2560977067] = { ["english"] = { [1] = "Be lifted by <name>'s accomplishment! Revel in <his/her> rallying cry!" }, ["npcs"] = { [1] = "High Overlord Saurfang" }, ["priority"] = 1, ["text"] = "Надихайтеся успіхом {ім'я:р}! Насолоджуйтесь {стать:його:її} кличем!#by <name>'s#in <his/her> rallying" },
    [2561065033] = { ["english"] = { [1] = "Anachronos, this diversion will give you and the young druid time enough to seal the gate. Do not falter. Now, let us see how they deal with chaotic magic." }, ["npcs"] = { [1] = "Arygos" }, ["priority"] = 1, ["text"] = "Анахроносе, це дасть тобі та юному друїду вдосталь часу, щоб запечатати ворота. Не відступайте. Подивимося, як вони впораються з хаотичною магією." },
    [256665921] = { ["english"] = { [1] = "This better be important!" }, ["npcs"] = { [1] = "Captain Blackanvil" }, ["priority"] = 1, ["text"] = "Сподіваюсь, це щось важливе!" },
    [2571183889] = { ["english"] = { [1] = "Do you know who I am, zealot?" }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "Ти знаєш, хто я, ревнителю?" },
    [2572027748] = { ["english"] = { [1] = "Reckless mortal!" }, ["npcs"] = { [1] = "Archaedas" }, ["priority"] = 1, ["text"] = "Бездумні смертні!" },
    [257681390] = { ["english"] = { [1] = "There is no way out." }, ["npcs"] = { [1] = "Anub'Rekhan" }, ["priority"] = 1, ["text"] = "Вам не втекти." },
    [2577116859] = { ["english"] = { [1] = "Ah! Fresh air at last! I never thought I'd see the day..." }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Ах! Нарешті свіже повітря! Я вже й не сподівалася, що дочекаюся цього..." },
    [2577265293] = { ["english"] = { [1] = "You know there are crocilisks in the Canals. They were brought from the swamp as pets, but got thrown in the canals." }, ["npcs"] = { [1] = "Justin" }, ["priority"] = 1, ["text"] = "Ви знаєте, що в каналах водяться кроколіски? Їх привезли як домашніх улюбленців з болота, але викинули в канали." },
    [2581656095] = { ["english"] = { [1] = "I'm telling Mommy!" }, ["npcs"] = { [1] = "Donna" }, ["priority"] = 1, ["text"] = "Я скажу мамі!" },
    [2586688164] = { ["english"] = { [1] = "Die, non-believer!" }, ["npcs"] = { [1] = "Al'Aketh Ambusher" }, ["priority"] = 3, ["text"] = "Помри, невірний!" },
    [2590159585] = { ["english"] = { [1] = "There we are, <name>.  The toxin is ready." }, ["npcs"] = { [1] = "Apothecary Lydon" }, ["priority"] = 1, ["text"] = "Ось так, {ім'я:к}. Токсин готовий.#There we are, <name>." },
    [2591205306] = { ["english"] = { [1] = "Help arrives at last..." }, ["npcs"] = { [1] = "Argent Guard Thaelrid" }, ["priority"] = 1, ["text"] = "Допомога нарешті прибула..." },
    [259426270] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "HELP! ASSASSINS HAVE COME TO KILL ME!" }, ["npcs"] = { [1] = "Weldon Barov" }, ["priority"] = 1, ["text"] = "ДОПОМОЖІТЬ! ВБИВЦІ ПРИЙШЛИ ПО МОЮ ДУШУ!" } }, ["english"] = { [1] = "HELP! ASSASSINS HAVE COME TO KILL ME!" }, ["npcs"] = { [1] = "Alexi Barov" }, ["priority"] = 1, ["text"] = "ДОПОМОЖІТЬ! ВБИВЦІ ПРИЙШЛИ ПО МОЮ ДУШУ!" },
    [2594912878] = { ["english"] = { [1] = "Do you hate me, my love? That I was forced to destroy your living form, that your spirit be released from unhappy bondage." }, ["npcs"] = { [1] = "Cerellean Whiteclaw" }, ["priority"] = 1, ["text"] = "Чи ненавидиш ти мене, любове моя? За те, що змушений був знищити твоє втілення в надії врятувати твою душу." },
    [2597719801] = { ["english"] = { [1] = "I don't get paid enough for this bull excrement!" }, ["npcs"] = { [1] = "Caretaker Alen" }, ["priority"] = 1, ["text"] = "Мені надто мало платять для такого лайна!" },
    [2598063859] = { ["english"] = { [1] = "This should only take a moment, <name>." }, ["npcs"] = { [1] = "Collin Mauren" }, ["priority"] = 1, ["text"] = "Це займе лиш мить, {ім'я:к}.#moment, <name>." },
    [2598451708] = { ["english"] = { [1] = "And thank you, <name>.  Without your aid I may never have found my way to the Forsaken." }, ["npcs"] = { [1] = "Gunther's Visage" }, ["priority"] = 1, ["text"] = "І дякую тобі, {ім'я:к}. Без твоєї допомоги я б можливо ніколи не знайшов свій шлях до відречених.#thank you, <name>." },
    [2600192313] = { ["english"] = { [1] = "Please, follow me." }, ["npcs"] = { [1] = "Donova Snowden" }, ["priority"] = 1, ["text"] = "Прошу, йди за мною." },
    [2603669844] = { ["english"] = { [1] = "How dare you enter my sanctum!" }, ["npcs"] = { [1] = "Witch Doctor Zum'rah" }, ["priority"] = 1, ["text"] = "Як ви смієте входити в мій храм!" },
    [2611723147] = { ["english"] = { [1] = "With pleasure..." }, ["npcs"] = { [1] = "Warchief Rend Blackhand" }, ["priority"] = 1, ["text"] = "Із задоволенням..." },
    [2618955613] = { ["english"] = { [1] = "Foolsss... Kill the one in the dress!" }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Недоумки... Вбийте того, що в сукні!" },
    [2624863341] = { ["english"] = { [1] = "Self-destruct sequence activated." }, ["npcs"] = { [1] = "Alarm-a-bomb 2600" }, ["priority"] = 1, ["text"] = "Процес самознищення активовано." },
    [2625527617] = { ["english"] = { [1] = "That I must fight against my own kind deeply saddens me." }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Мене глибоко засмучує те, що я змушений битися проти свого ж роду." },
    [2630398725] = { ["english"] = { [1] = "Annalise? Is that you?" }, ["npcs"] = { [1] = "Apothecary Staffron Lerent" }, ["priority"] = 1, ["text"] = "Анналіз? Це ти?" },
    [2630946131] = { ["english"] = { [1] = "I'm glad the commotions died down some around here. The last thing this place needs is another brawl." }, ["npcs"] = { [1] = "Mikhail" }, ["priority"] = 1, ["text"] = "Я радий, що ця метушня трохи вщухла. Останнє, що потрібно цьому місцю, — це ще одне побоїще." },
    [2632300111] = { ["english"] = { [1] = "I can't believe it! You've destroyed my pack... Now face my wrath!" }, ["npcs"] = { [1] = "Wolf Master Nandos" }, ["priority"] = 1, ["text"] = "Не можу в це повірити! Ви знищили мою зграю... Тепер ви відчуєте мій гнів!" },
    [2633782526] = { ["english"] = { [1] = "Very well, <name>." }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Добре, {ім'я:к}.#well, <name>." },
    [2634157291] = { ["english"] = { [1] = "That is the wrong answer, <name>. Be off with you." }, ["npcs"] = { [1] = "Braug Dimspirit" }, ["priority"] = 1, ["text"] = "Це неправильна відповідь, {ім'я:к}. Йди звідси.#answer, <name>." },
    [2643626745] = { ["english"] = { [1] = "Aaaaahhh! So close to escaping." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ааааааа! Я майже втік." },
    [2644594677] = { ["english"] = { [1] = "Taste in my power!" }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Відчуйте мою силу!" },
    [2645264341] = { ["english"] = { [1] = "Privates Marcus, Tremane, Osgood, Lampret..." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "Рядові Маркус, Треман, Осґуд, Лампрет..." },
    [2649662079] = { ["english"] = { [1] = "I want nothing to do with Silithus, the Qiraji and least of all, any damned dragons!" }, ["npcs"] = { [1] = "Fandral Staghelm" }, ["priority"] = 1, ["text"] = "Я не хочу мати нічого спільного з Силітусом, кіражами, і тим паче з клятими драконами!" },
    [2651574993] = { ["english"] = { [1] = "The last of the embers are gone." }, ["npcs"] = { [1] = "Relathor Moonsong" }, ["priority"] = 1, ["text"] = "Здається, вже не тліє." },
    [2653272304] = { ["english"] = { [1] = "Beware!  A <target> is upon us!" }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "Стережися! {Ціль:н} йде на нас!" },
    [2654955622] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Please tell me that you didn't just do what I think you just did. Please tell me that I'm not going to have to hurt you..." }, ["npcs"] = { [1] = "Cenarion Hold Reservist" }, ["priority"] = 1, ["text"] = "Прошу, скажи, що це не те, що я думаю. Скажи, що мені не доведеться робити тобі боляче..." } }, ["english"] = { [1] = "Please tell me that you didn't just do what I think you just did. Please tell me that I'm not going to have to hurt you..." }, ["npcs"] = { [1] = "Cenarion Hold Infantry" }, ["priority"] = 1, ["text"] = "Прошу, скажи, що це не те, що я думаю. Скажи, що мені не доведеться робити тобі боляче..." },
    [2656952024] = { ["english"] = { [1] = "Death to any <race> that stands in my way!" }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "Смерть усім {раса:мн}, що стоять на моєму шляху!#any <race> that" },
    [2659055032] = { ["english"] = { [1] = "Still no sign of the final shipment of explosives." }, ["npcs"] = { [1] = "Dark Iron Bombardier" }, ["priority"] = 1, ["text"] = "Нової поставки вибухівки досі не видно." },
    [2663519648] = { ["english"] = { [1] = "Oh so much pain..." }, ["npcs"] = { [1] = "Emperor Vek'nilash" }, ["priority"] = 1, ["text"] = "Ох, як боляче..." },
    [266602064] = { ["english"] = { [1] = "This better be the last one!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Сподіваюсь, це останній!" },
    [2682603865] = { ["english"] = { [1] = "%s begins to summon a lava spawn!" }, ["npcs"] = { [1] = "Bael'Gar" }, ["priority"] = 1, ["text"] = "%s починає викликати породження лави!" },
    [2687204469] = { ["english"] = { [1] = "Please wait while I attempt to bind the shards together so that they will be whole once again." }, ["npcs"] = { [1] = "Aurora Skycaller" }, ["priority"] = 1, ["text"] = "Будь ласка, зачекай, поки я спробую поєднати уламки в одне ціле." },
    [268868155] = { ["english"] = { [1] = "Here's a singing telegram for <name>: Roses are red, violets are blue, I will kill any <race> I see, including you!" }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "Ось музичне послання для {ім'я:р}: Скільки себе пам'ятаю, завше хотілось мені, вбити нікчему-{раса:з}, прямо {стать:такого, як ти:таку, як і ти}!" },
    [2689863562] = { ["english"] = { [1] = "Raaaaaaaaaaaaaaaaaaaaaaaaaaaaaar!!! Me smash <target>!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Рррааааааааааааааааааааааааррррр!!! Моя бити {ціль}!#Me smash <target>!" },
    [2690426857] = { ["english"] = { [1] = "Before I leave this place, I make one final offering to you, Lord Staghelm. Should a time arise in which you must gain entry to this accursed fortress, use the Scepter of the Shifting Sands on the sacred gong. The magic holding the barrier together will dissipate and the horrors of Ahn'Qiraj will be unleashed upon the world once more." }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "Перш ніж я покину це місце, я маю передати тобі останній обов'язок, лорд Оленеріг. Якщо коли-небудь виникне потреба увійти до цієї проклятої фортеці, вдар скіпетром Мінливих Пісків у священний гонг. Магія, що утримує бар'єр, розвіється, і жахи Ан'Кіража знову будуть випущені на волю." },
    [2690650590] = { ["english"] = { [1] = "Sure are a lot of litter bugs around here." }, ["npcs"] = { [1] = "Darkmoon Faire Carnie" }, ["priority"] = 1, ["text"] = "Ну звісно, тут знову буде купа сміття" },
    [2697920918] = { ["english"] = { [1] = "Wait...you are not my husband.  But he must have sent you.  And you...look..delicious!" }, ["npcs"] = { [1] = "Eliza" }, ["priority"] = 1, ["text"] = "Зачекай… ти не мій чоловік. Але він, мабуть, прислав тебе. А ти... виглядаєш... смачно!" },
    [2700027791] = { ["english"] = { [1] = "Goodbye, cruel world... I'm leavin' you today... goodbye... goodbye... goodbye..." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Прощавай, жорстокий світ... Сьогодні я тебе покину... прощавай... прощавай... прощавай..." },
    [2701434042] = { ["english"] = { [1] = "I've been saving this spot for something special. I don't think it gets any more special than this, <name>." }, ["npcs"] = { [1] = "Curator Thorius" }, ["priority"] = 1, ["text"] = "Я беріг це місце для чогось особливого. Не думаю, що ми знайдемо щось особливіше за це, {ім'я:к}.#this, <name>." },
    [2701974162] = { ["english"] = { [1] = "Kneel! Kneel before the Ashbringer!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "На коліна! Схиліться перед Спопелителем!" },
    [2707894409] = { ["english"] = { [1] = "You are free of His control. And while you will be judged by lesser beings, at least you have chances that the Scourge do not!" }, ["npcs"] = { [1] = "Caretaker Caice" }, ["priority"] = 1, ["text"] = "Ми вільні від Його контролю. І хоча нас зневажатимуть нижчі істоти, принаймні у вас є воля, якої не має Скара!" },
    [2708045785] = { ["english"] = { [1] = "And... do you expect to defeat the Primal Gods?" }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "І... ви очікуєте перемогти Первісних Богів?" },
    [270915395] = { ["english"] = { [1] = "Get'em while they are nice and fresh! Loaves of bread here!" }, ["npcs"] = { [1] = "Greishan Ironstove" }, ["priority"] = 1, ["text"] = "Налітайте, поки свіжі! Свіжі буханці хліба!" },
    [2709498338] = { ["english"] = { [1] = "Be sure to read over the notes in my journal, <name>. You will find them to be invaluable in overcoming the tower's defenses." }, ["npcs"] = { [1] = "Agent Kearnen" }, ["priority"] = 1, ["text"] = "Обов'язково переглянь мої записи, {ім'я:к}. Вони значно спростять проникнення до вежі.#in my journal, <name>." },
    [2709654253] = { ["english"] = { [1] = "Intruders!  The Hammer shall fall upon you." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Чужинці! Молот покарає вас." },
    [271109146] = { ["english"] = { [1] = "My bones are weak, my eyes see only darkness, and my body feels only pain; but these things are good because my will is my own." }, ["npcs"] = { [1] = "Caretaker Caice" }, ["priority"] = 1, ["text"] = "Мої кістки слабкі, мої очі бачать лише пітьму, а тіло відчуває лише біль. Але це ніщо, адже моя воля належить мені." },
    [27160099] = { ["english"] = { [1] = "I'll feed your souls to Hakkar himself!" }, ["npcs"] = { [1] = "Bloodlord Mandokir" }, ["priority"] = 1, ["text"] = "Я згодую ваші душі самому Гаккару!" },
    [2717536644] = { ["english"] = { [1] = "Corbett, you there?  Harlan needs another load of knitted goods.  Can you take it to him?" }, ["npcs"] = { [1] = "Rema Schneider" }, ["priority"] = 1, ["text"] = "Корбете, ти там? Гарлану потрібна ще одна партія одягу. Зможеш віднести її?" },
    [2719533950] = { ["english"] = { [1] = "Help!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Допоможіть!" },
    [2722975165] = { ["english"] = { [1] = "Once your campfire is down, you can place all sorts of camp fixtures around it." }, ["npcs"] = { [1] = "Raan Wildwind" }, ["priority"] = 3, ["text"] = "Коли багаття вже розпалене, довкола нього можна розставити всіляке табірне приладдя." },
    [272455808] = { ["english"] = { [1] = "Clever, mortals - but I am not so easily lured away from my sanctum!" }, ["npcs"] = { [1] = "Broodlord Lashlayer" }, ["priority"] = 1, ["text"] = "Розумно, смертні — але мене не так легко виманити з мого святилища!" },
    [272557243] = { ["english"] = { [1] = "This desert be mine!" }, ["npcs"] = { [1] = "Chief Ukorz Sandscalp" }, ["priority"] = 1, ["text"] = "Пустеля буде моєю!" },
    [272845343] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "It'll be quick, but it won't be painless!" }, ["npcs"] = { [1] = "Bruegal Ironknuckle" }, ["priority"] = 1, ["text"] = "Це буде швидко, але не безболісно!" } }, ["english"] = { [1] = "It'll be quick, but it won't be painless!" }, ["npcs"] = { [1] = "Bazil Thredd" }, ["priority"] = 1, ["text"] = "Це буде швидко, але не безболісно!" },
    [2729013794] = { ["english"] = { [1] = "Stonemasons. . .errr. . Defias be warned:  The rusty anchor sinks tonight." }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "Каменярі... еее... Непокірні, остерігайтеся: Іржавий якір опуститься цієї ночі." },
    [272927630] = { ["english"] = { [1] = "Hear me, denizens of the Crater!  I come to burn this land of its impurity!" }, ["npcs"] = { [1] = "Baron Charr" }, ["priority"] = 1, ["text"] = "Слухайте сюди, мешканці кратеру! Я прийшов, щоб випалити нечисть з цієї землі!" },
    [2730521272] = { ["english"] = { [1] = "Oh well... Maybe next time." }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "Ну що ж... Може, якось іншим разом." },
    [273250980] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "%s is splashed by the blood and becomes irradiated!" }, ["npcs"] = { [1] = "Caverndeep Burrower" }, ["priority"] = 1, ["text"] = "%s вкривається кров'ю і стає опроміненим!" }, [2] = { ["english"] = { [1] = "%s is splashed by the blood and becomes irradiated!" }, ["npcs"] = { [1] = "Caverndeep Invader" }, ["priority"] = 1, ["text"] = "%s вкривається кров'ю і стає опроміненим!" }, [3] = { ["english"] = { [1] = "%s is splashed by the blood and becomes irradiated!" }, ["npcs"] = { [1] = "Caverndeep Pillager" }, ["priority"] = 1, ["text"] = "%s вкривається кров'ю і стає опроміненим!" }, [4] = { ["english"] = { [1] = "%s is splashed by the blood and becomes irradiated!" }, ["npcs"] = { [1] = "Caverndeep Reaver" }, ["priority"] = 1, ["text"] = "%s вкривається кров'ю і стає опроміненим!" } }, ["english"] = { [1] = "%s is splashed by the blood and becomes irradiated!" }, ["npcs"] = { [1] = "Caverndeep Ambusher" }, ["priority"] = 1, ["text"] = "%s вкривається кров'ю і стає опроміненим!" },
    [273264594] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "%s is now armed!" }, ["npcs"] = { [1] = "Goblin Land Mine" }, ["priority"] = 1, ["text"] = "%s активована!" } }, ["english"] = { [1] = "%s is now armed!" }, ["npcs"] = { [1] = "Dark Iron Land Mine" }, ["priority"] = 1, ["text"] = "%s активована!" },
    [2734348061] = { ["english"] = { [1] = "It shall NEVER happen. We are legion. We are united. Where are your heroes? Vol'jin sits in sanctuary at the side of the young Warchief, unaware. Zul'jin missing, probably dead." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Цього НІКОЛИ не станеться. Ми — легіон. Ми єдині. Де ваші герої? Вол'джин сидить у безпеці поряд з юним вождем, ні про що не підозрюючи. Зул'джин зник, ймовірно, загинув." },
    [2734844591] = { ["english"] = { [1] = "%s glances at her compatriots." }, ["npcs"] = { [1] = "Merithra of the Dream" }, ["priority"] = 1, ["text"] = "%s дивиться на інших драконів." },
    [2735028224] = { ["english"] = { [1] = "The swamp was horrible! I was so... so... scared!" }, ["npcs"] = { [1] = "Acolyte Dellis" }, ["priority"] = 1, ["text"] = "Болото було жахливим! Мені було так... так... страшно!" },
    [2738702649] = { ["english"] = { [1] = "Argh, I need help here!" }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Аргх, мені потрібна допомога!" },
    [2740256230] = { ["english"] = { [1] = "Eat... your... bones..." }, ["npcs"] = { [1] = "Thaddius" }, ["priority"] = 1, ["text"] = "Їсти... ваші... кістки..." },
    [2740491117] = { ["english"] = { [1] = "I would have just dropped some Evershine in my tank and been back home before they realized I'd gone!" }, ["npcs"] = { [1] = "Pilot Bellowfiz" }, ["priority"] = 3, ["text"] = "Та я б просто хлюпнув трохи Вічносяю в бак і вже був би вдома, перш ніж вони збагнули б, що мене нема!" },
    [2740583002] = { ["english"] = { [1] = "Hey, you call yourself a body guard? Get to work and protect us..." }, ["npcs"] = { [1] = "Cork Gizelton" }, ["priority"] = 1, ["text"] = "І ти називаєшся охоронцем? То до роботи, захищай нас!" },
    [2750494422] = { ["english"] = { [1] = "My son's soul will find no comfort in this hollow victory, dragon. I will have him back. Though it takes a millennia, I WILL have my son back!" }, ["npcs"] = { [1] = "Fandral Staghelm" }, ["priority"] = 1, ["text"] = "Душа мого сина не знайде спокою від цієї марної перемоги, драконе. Я поверну його. Навіть якщо для цього знадобляться тисяча років, Я ПОВЕРНУ свого сина!" },
    [2751344743] = { ["english"] = { [1] = "Good day, Corbett.  Here's your cheese, fresh made this morning!  And how are things at your shop?" }, ["npcs"] = { [1] = "Elaine Trias" }, ["priority"] = 1, ["text"] = "Доброго дня, Корбете. Ось твій сир, вранішній! Як справи у крамниці?" },
    [2751371603] = { ["english"] = { [1] = "You be too scared!  Me find you!" }, ["npcs"] = { [1] = "Avalanchion" }, ["priority"] = 1, ["text"] = "Ви боятися! Я вас знайти!" },
    [2753768394] = { ["english"] = { [1] = "<name>!  Prepare to meet your doom!" }, ["npcs"] = { [1] = "Balgaras the Foul" }, ["priority"] = 1, ["text"] = "{ім'я:н}! Приготуйся зустріти свою загибель!#<name>!  Prepare" },
    [2758958107] = { ["english"] = { [1] = "I'm ready, <name>. Let's find my equipment and get out of here. I think I know where it is." }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Я готова, {ім'я:к}. Ходімо, знайдемо моє спорядження та виберемось звідси. Думаю, я знаю, де воно знаходиться." },
    [2759381457] = { ["english"] = { [1] = "Wahehe! I'm taking you down with me!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Вахаха! Я заберу тебе з собою!" },
    [2759932824] = { ["english"] = { [1] = "You can't hide from us.  Prepare to burn!" }, ["npcs"] = { [1] = "Anvilrage Guardsman" }, ["priority"] = 1, ["text"] = "Вам не сховатися. Ви згорите!" },
    [2760472643] = { ["english"] = { [1] = "%s goes into a killing frenzy!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s впадає в смертоносне шаленство!" },
    [2763433507] = { ["english"] = { [1] = "Now there is only one way out- to walk the lonely path of the damned." }, ["npcs"] = { [1] = "Gothik the Harvester" }, ["priority"] = 1, ["text"] = "Тепер є лиш один вихід — йти самотньою стежкою проклятих." },
    [2764595154] = { ["english"] = { [1] = "All hail, Bobby! Defender of The People!" }, ["npcs"] = { [1] = "Gryan Stoutmantle" }, ["priority"] = 3, ["text"] = "Слава Боббі! Захисникові народу!" },
    [276748922] = { ["english"] = { [1] = "DIE, INSECT!" }, ["npcs"] = { [1] = "Ragnaros" }, ["priority"] = 1, ["text"] = "ЗДОХНИ, КОМАХО!" },
    [2770016986] = { ["english"] = { [1] = "The battle is won! Watch as they flee to the safety of their precious temple. Soon all will be razed... Their leaders destroyed!" }, ["npcs"] = { [1] = "High Overlord Saurfang" }, ["priority"] = 1, ["text"] = "Битву виграно! Вони втікають до свого дорогоцінного храму. Скоро ми зачистимо його... Їхніх ватажків буде знищено!" },
    [2770019137] = { ["english"] = { [1] = "After all we've been through?  Well, I didn't like you anyway!!" }, ["npcs"] = { [1] = "Sergeant Bly" }, ["priority"] = 1, ["text"] = "Після всього, що ми пережили? Ну, ти мені все одно не подобаєшся!!" },
    [2778345075] = { ["english"] = { [1] = "I have just the spot for this horn!" }, ["npcs"] = { [1] = "Curator Thorius" }, ["priority"] = 1, ["text"] = "У мене є чудове місце для цього рога!" },
    [2782667029] = { ["english"] = { [1] = "Hello, Quinn.  How are you faring?" }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "Привіт, Квінн. Як справи?" },
    [2787868111] = { ["english"] = { [1] = "Kneel, heathen." }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "На коліна, єретик." },
    [2790504842] = { ["english"] = { [1] = "I can sense it now, <name>. Ashenvale lies down this path." }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Я відчуваю це, {ім'я:к}. Ясенеділ знаходиться там." },
    [2791033887] = { ["english"] = { [1] = "Tonight, your blood will run red on the stones of our altars." }, ["npcs"] = { [1] = "Caedakar the Vicious" }, ["priority"] = 1, ["text"] = "Ваша кров тектиме каменями наших жертовників." },
    [2798737973] = { ["english"] = { [1] = "You will not escape death!" }, ["npcs"] = { [1] = "Emperor Vek'lor" }, ["priority"] = 1, ["text"] = "Ви не втечете від смерті!" },
    [2799873790] = { ["english"] = { [1] = "A paladin! Slaying him would please the master. Attack!" }, ["npcs"] = { [1] = "Forsaken Scout" }, ["priority"] = 1, ["text"] = "Паладин! Його смерть задовольнить майстра. В атаку!" },
    [2800264874] = { ["english"] = { [1] = "I regret that I must fight this <target>." }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Мені дуже шкода, але {ціль} має померти.#fight this <target>." },
    [2804246636] = { ["english"] = { [1] = "Business must be good down at the bazaar.  I'll get him resupplied right away!" }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Певно продажі йдуть надзвичайно добре. Я негайно віднесу йому товари!" },
    [2804871413] = { ["english"] = { [1] = "Okay, okay! Enough fighting. No one else needs to get hurt." }, ["npcs"] = { [1] = "Dashel Stonefist" }, ["priority"] = 1, ["text"] = "Гаразд, все! Досить битися. Ми можемо поговорити." },
    [2805587126] = { ["english"] = { [1] = "I smell an intruder..." }, ["npcs"] = { [1] = "Defias Dockmaster" }, ["priority"] = 1, ["text"] = "Я відчуваю непроханого гостя..." },
    [28073367] = { ["english"] = { [1] = "Intruders!  More pawns of the Argent Dawn, no doubt.  I already count one of their number among my prisoners.  Withdraw from my domain before she is executed!" }, ["npcs"] = { [1] = "Baron Rivendare" }, ["priority"] = 1, ["text"] = "Чужинці! Чергові пішаки Сріблястого Світанку, ну звісно. Одна з них вже у мене в полоні. Покиньте мої володіння, поки її не стратили!" },
    [281329027] = { ["english"] = { [1] = "These three again?" }, ["npcs"] = { [1] = "Feero Ironhand" }, ["priority"] = 1, ["text"] = "Знову ці троє?" },
    [2818239379] = { ["english"] = { [1] = "You will be easy prey, <class>." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ти будеш легкою здобиччю, {клас:к}.#prey, <class>." },
    [2818513147] = { ["english"] = { [1] = "How pathetic. I am infused with the power of the Soulflayer. I fear nothing but the wrath of the almighty Hakkar. I serve no one but my master, Jin." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Як жалюгідно. Я сповнений силою Здирача Душ. Я не боюся нічого, окрім гніву всемогутнього Гаккара. Я не служу нікому, крім свого повелителя, Джина." },
    [2824099260] = { ["english"] = { [1] = "Blue plus red... I predict..." }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "Сині та червоні... Я так і думала..." },
    [2833447782] = { ["english"] = { [1] = "The Stormpike Quatermaster keeps his supplies under an awning, just west of here." }, ["npcs"] = { [1] = "Corporal Noreg Stormpike" }, ["priority"] = 1, ["text"] = "Квартирмейстер Бурешпиля тримає свої припаси під навісом, трохи на захід звідси." },
    [2835001628] = { ["english"] = { [1] = "Yet you think that recovering Ashbringer will somehow turn the tide of battle? Let me let you in on a little secret, Commander: The power of the Ashbringer came from the man who would wield it... I was there, Commander. I watched him burn legions of undead in righteous fire before he would even unsheathe the blade. Alas, your grasp on history is ... lacking." }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Ви справді думаєте, що повернення Спопелителя може змінити хід битви? Дозвольте відкрити вам невелику таємницю, командире: сила Спопелителя походила від людини, що його носила... Я був там, командире. Я бачив, як він спопеляв легіони невмерлих праведним вогнем, навіть не оголюючи леза. На жаль, ваші знання історії... посередні." },
    [2835480692] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You screamed like a little girl, funniest thing I ever saw." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Ти кричав, як мале дівчисько. Це було дуже кумедно." } }, ["english"] = { [1] = "You screamed like a little girl, funniest thing I ever saw." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Ти кричав, як мале дівчисько. Це було дуже кумедно." },
    [2835729909] = { ["english"] = { [1] = "I don't think it's strong enough." }, ["npcs"] = { [1] = "Bath'rah the Windwatcher" }, ["priority"] = 1, ["text"] = "Здається, цього буде недостатньо." },
    [2835891999] = { ["english"] = { [1] = "Free from this wretched cell at last! Let me show you to the courtyard...." }, ["npcs"] = { [1] = "Deathstalker Adamant" }, ["priority"] = 1, ["text"] = "Нарешті я вибрався з цієї нікчемної камери! Дозвольте показати вам внутрішній двір..." },
    [283623795] = { ["english"] = { [1] = "Three cheers for Gear!  This land shall be ours once again!" }, ["npcs"] = { [1] = "Gryan Stoutmantle" }, ["priority"] = 3, ["text"] = "Тричі слава Ґіру!  Ця земля знову буде нашою!" },
    [2839291088] = { ["english"] = { [1] = "%s begins to summon in a Blackhand Dreadweaver!" }, ["npcs"] = { [1] = "Blackhand Summoner" }, ["priority"] = 1, ["text"] = "%s починає викликати жахоткача Чорнорука!" },
    [2842274590] = { ["english"] = { [1] = "You seek to lure me from my clutch? You shall pay for your insolence!" }, ["npcs"] = { [1] = "Onyxia" }, ["priority"] = 1, ["text"] = "Ви намагаєтеся виманити мене з мого гнізда? Ви заплатите за вашу зухвалість!" },
    [2843177413] = { ["english"] = { [1] = "The abomination has overrun the Night Watch camp! Quickly, we must intercept it before it reaches town!" }, ["npcs"] = { [1] = "Town Crier" }, ["priority"] = 1, ["text"] = "Потвора напала на табір Нічної варти! Швидше, ми маємо зупинити її, поки вона не дійшла до міста!" },
    [2843803955] = { ["english"] = { [1] = "I need help!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Мені потрібна допомога!" },
    [2844111563] = { ["english"] = { [1] = "I hope that was a fish!" }, ["npcs"] = { [1] = "Roman" }, ["priority"] = 1, ["text"] = "Сподіваюся, це риба!" },
    [2848529481] = { ["english"] = { [1] = "Evil makes me so sleepy..." }, ["npcs"] = { [1] = "Doctor Weavil" }, ["priority"] = 1, ["text"] = "Від зла мені так зочеться спати..." },
    [2849704895] = { ["english"] = { [1] = "Ah, here at last! It's going to feel so good to get rid of these barrels." }, ["npcs"] = { [1] = "Miran" }, ["priority"] = 1, ["text"] = "А, нарешті на місці! Як же добре буде нарешті позбутися цих бочок." },
    [2852446815] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What?  Such a small, frail thing beckons me?  This will not go unpunished!" }, ["npcs"] = { [1] = "The Duke of Fathoms" }, ["priority"] = 1, ["text"] = "Що? Мене викликала така мала, немічна істота? Я покараю тебе за це!" }, [2] = { ["english"] = { [1] = "What?  Such a small, frail thing beckons me?  This will not go unpunished!" }, ["npcs"] = { [1] = "The Duke of Shards" }, ["priority"] = 1, ["text"] = "Що? Мене викликала така мала, немічна істота? Я покараю тебе за це!" }, [3] = { ["english"] = { [1] = "What?  Such a small, frail thing beckons me?  This will not go unpunished!" }, ["npcs"] = { [1] = "The Duke of Zephyrs" }, ["priority"] = 1, ["text"] = "Що? Мене викликала така мала, немічна істота? Я покараю тебе за це!" } }, ["english"] = { [1] = "What?  Such a small, frail thing beckons me?  This will not go unpunished!" }, ["npcs"] = { [1] = "The Duke of Cynders" }, ["priority"] = 1, ["text"] = "Що? Мене викликала така мала, немічна істота? Я покараю тебе за це!" },
    [2855240268] = { ["english"] = { [1] = "What was that!" }, ["npcs"] = { [1] = "Rizzle Brassbolts" }, ["priority"] = 1, ["text"] = "Що це було?!" },
    [2856017680] = { ["english"] = { [1] = "Ah, Private Hendel. A pleasure to meet one of the men who would betray his kingdom for pride." }, ["npcs"] = { [1] = "Archmage Tervosh" }, ["priority"] = 1, ["text"] = "Ах, рядовий Гіндель. Радий зустріти одного з тих, хто готовий зрадити королівство через свою гордість." },
    [2860631378] = { ["english"] = { [1] = "%s devours all nearby zombies!" }, ["npcs"] = { [1] = "Gluth" }, ["priority"] = 1, ["text"] = "%s пожирає всіх зомбі поблизу!" },
    [2860707376] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You can thank me anytime for making your life more interesting." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Подякуєш якось потім за те, що я роблю твоє життя цікавішим." } }, ["english"] = { [1] = "You can thank me anytime for making your life more interesting." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Подякуєш якось потім за те, що я роблю твоє життя цікавішим." },
    [2863205161] = { ["english"] = { [1] = "Let them feel the wrath of the Blue Flight! May Malygos protect me!" }, ["npcs"] = { [1] = "Arygos" }, ["priority"] = 1, ["text"] = "Нехай вони пізнають гнів синіх драконів! Маліґос, захисти мене!" },
    [2863626944] = { ["english"] = { [1] = "DING!" }, ["npcs"] = { [1] = "Bloodlord Mandokir" }, ["priority"] = 1, ["text"] = "ДЗИНЬ!" },
    [2863874437] = { ["english"] = { [1] = "%s summons a Blackhand Dreadweaver to his aid!" }, ["npcs"] = { [1] = "Blackhand Summoner" }, ["priority"] = 1, ["text"] = "%s викликає жахоткача Чорнорука на допомогу!" },
    [2873151215] = { ["english"] = { [1] = "Commerce!  I crave it!" }, ["npcs"] = { [1] = "Augustus the Touched" }, ["priority"] = 1, ["text"] = "Комерція! Обожнюю її!" },
    [2874678113] = { ["english"] = { [1] = "FINISH THE SPELL, STAGHELM! I CANNOT HOLD THE GLYPHS OF WARDING IN PLACE MUCH LONGER! CALL FORTH THE ROOTS!" }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "ЗАКІНЧИ ЗАКЛЯТТЯ, ОЛЕНЕРІГ! Я НЕ ЗМОЖУ ДОВГО УТРИМУВАТИ ПЕЧАТКУ! ВИКЛИЧ КОРІННЯ!" },
    [2876286454] = { ["english"] = { [1] = "Hey Fizzer, I ever tell you the time I was riding through the canals and some goblins in shredder suits tried to ambush me?" }, ["npcs"] = { [1] = "Pilot Stonegear" }, ["priority"] = 3, ["text"] = "Гей, Фіззере, я вже розповідав тобі, як їхав каналами, а якісь гобліни в костюмах подрібнювачів спробували влаштувати мені засідку?" },
    [2876933296] = { ["english"] = { [1] = "All clear on Sentinel Hill, Lord Stoutmantle.  Heavy Defias movement reported in Moonbrook, however." }, ["npcs"] = { [1] = "Captain Danuvin" }, ["priority"] = 1, ["text"] = "На Сторожовому пагорбі все чисто, лорде Міцнокрив. Проте повідомляється про значну активність Непокірних у Місяцеграї." },
    [2878531745] = { ["english"] = { [1] = "Come, brothers." }, ["npcs"] = { [1] = "Arch Druid Renferal" }, ["priority"] = 1, ["text"] = "Ходімо, браття." },
    [2886096622] = { ["english"] = { [1] = "Flee while you still have a chance, mortals. You will pray for a swift death should I enter the arena." }, ["npcs"] = { [1] = "Warchief Rend Blackhand" }, ["priority"] = 1, ["text"] = "Тікайте, поки ще маєте шанс, смертні. Ви будете благати про швидку смерть, якщо я вийду на арену." },
    [2887099998] = { ["english"] = { [1] = "No! Anaya... Anaya! Don't leave me! Please..." }, ["npcs"] = { [1] = "Cerellean Whiteclaw" }, ["priority"] = 1, ["text"] = "Ні! Анайя... Анайя! Не покидай мене! Прошу..." },
    [2888305722] = { ["english"] = { [1] = "%s pokes the skittish rabbit." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "%s штрикає пальцем полохливого кролика." },
    [2891836007] = { ["english"] = { [1] = "If I am excused, then I'd like to check on Quinn..." }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "Якщо можна, я б хотів поглянути, як там Квінн..." },
    [2894411990] = { ["english"] = { [1] = "They're coming out of the woodwork today. Let's keep moving or we may find more things that want me dead." }, ["npcs"] = { [1] = "Feero Ironhand" }, ["priority"] = 1, ["text"] = "Вони сьогодні виповзають з усіх щілин. Продовжуймо рухатися, поки не натрапили ще на когось, хто хоче мене вбити." },
    [2902262480] = { ["english"] = { [1] = "Brahaha! Tha look on their faces as old Trollplow's gun came swiveling around to meet them! Their saws couldn't even touch me!" }, ["npcs"] = { [1] = "Pilot Stonegear" }, ["priority"] = 3, ["text"] = "Бра-ха-ха! Бачив би ти їхні пики, коли гармата старого Тролеплуга розвернулася просто на них! Їхні пилки мене навіть не зачепили!" },
    [2902496179] = { ["english"] = { [1] = "Having a good time?" }, ["npcs"] = { [1] = "Darkmoon Faire Carnie" }, ["priority"] = 1, ["text"] = "Розважаєтесь?" },
    [2905478527] = { ["english"] = { [1] = "Shluhpickle ran the Gauntlet!  Three cheers for Shluhpickle!" }, ["npcs"] = { [1] = "Yorus Barleybrew" }, ["priority"] = 3, ["text"] = "Шлухпікл пройшов Випробування!  Тричі слава Шлухпіклу!" },
    [2905831805] = { ["english"] = { [1] = "YOU CANNOT DEFEAT THE LIVING FLAME!" }, ["npcs"] = { [1] = "Ragnaros" }, ["priority"] = 1, ["text"] = "ВАМ НЕ ЗДОЛАТИ ЖИВЕ ПОЛУМ'Я!" },
    [2906820234] = { ["english"] = { [1] = "Finally, I am free! I come home soon, my dear!" }, ["npcs"] = { [1] = "Elder Torntusk" }, ["priority"] = 1, ["text"] = "Нарешті, я вільний! Я скоро вернусь, моя люба!" },
    [2910584342] = { ["english"] = { [1] = "If you are looking for more work, I'm sure there are some folks in town that are also looking for help with one task or another. Just ask around, you are bound to find something." }, ["npcs"] = { [1] = "Constable Aonda" }, ["priority"] = 3, ["text"] = "Якщо шукаєш ще роботи, певен, у містечку є люди, яким також потрібна допомога з тією чи іншою справою. Просто розпитай — неодмінно щось знайдеш." },
    [2913129679] = { ["english"] = { [1] = "What happens when I do this?!" }, ["npcs"] = { [1] = "William" }, ["priority"] = 1, ["text"] = "А що, якщо зроблю от так?!" },
    [291321759] = { ["english"] = { [1] = "%s laughs maniacally." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "%s несамовито сміється." },
    [2913678441] = { ["english"] = { [1] = "I'll deliver you, weak <class>, to the afterlife!" }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "Я відправлю тебе, {стать:нікчемний:нікчемна} {клас:к}, у потойбіччя!#weak <class>, to" },
    [291494010] = { ["english"] = { [1] = "OK, OK! It's your turn!" }, ["npcs"] = { [1] = "Blackhand Thug" }, ["priority"] = 1, ["text"] = "Гаразд, гаразд! Твоя черга!" },
    [2915418226] = { ["english"] = { [1] = "%s forces his Firesworn minions to regain their strength!" }, ["npcs"] = { [1] = "Garr" }, ["priority"] = 1, ["text"] = "%s змушує своїх вогнеклятів відновити сили!" },
    [2916633754] = { ["english"] = { [1] = "Psssst.  We just got some Moonshine in. . . ." }, ["npcs"] = { [1] = "Barkeep Hann" }, ["priority"] = 1, ["text"] = "Псс. Ми щойно отримали відмінний самогон..." },
    [291839565] = { ["english"] = { [1] = "I shall take great pleasure in taking this poor wretch's life!  It's not too late, she needn't suffer in vain.  Turn back and her death shall be merciful!" }, ["npcs"] = { [1] = "Baron Rivendare" }, ["priority"] = 1, ["text"] = "Вбивство цієї нікчеми розважить мене! Ви ж не хочете, щоб вона страждала? Йдіть геть, і я подарую їй швидку смерть!" },
    [2920668000] = { ["english"] = { [1] = "Learn your place, mortal!" }, ["npcs"] = { [1] = "Onyxia" }, ["priority"] = 1, ["text"] = "Знайте своє місце, смертні!" },
    [2921053496] = { ["english"] = { [1] = "You there! Check out that noise." }, ["npcs"] = { [1] = "Mr. Smite" }, ["priority"] = 3, ["text"] = "Гей, ти! Перевір, що там за шум." },
    [2921104914] = { ["english"] = { [1] = "Here is a beacon for you, <name>.  You must keep it in your possession if you are to find the corrupted items we will need." }, ["npcs"] = { [1] = "Arathandris Silversky" }, ["priority"] = 1, ["text"] = "Ось твій маяк, {ім'я:к}. Ти маєш тримати його при собі, якщо хочеш знайти осквернені матеріали для бальзаму." },
    [2922560754] = { ["english"] = { [1] = "If I could just find \"Magic and the Ways of Power\". Ahh here it is, what was it doing over here?" }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Якби я тільки могла знайти \"Магію і Шляхи Сили\". О, а ось і вона. Що вона тут робила?" },
    [2925531799] = { ["english"] = { [1] = "Bah! My power rules here!" }, ["npcs"] = { [1] = "Charlga Razorflank" }, ["priority"] = 1, ["text"] = "Ха! Тут панує моя сила!" },
    [2926983904] = { ["english"] = { [1] = "%s whimpers obediently." }, ["npcs"] = { [1] = "Frostwolf" }, ["priority"] = 1, ["text"] = "%s покірно скиглить." },
    [2927997206] = { ["english"] = { [1] = "You only delay the inevitable!" }, ["npcs"] = { [1] = "The Prophet Skeram" }, ["priority"] = 1, ["text"] = "Ви лише відкладаєте неминуче!" },
    [2928146937] = { ["english"] = { [1] = "You will abide by our rules around here, miscreant!" }, ["npcs"] = { [1] = "Argent Sentry" }, ["priority"] = 1, ["text"] = "Ти підкорятимешся нашим правилам, мерзото!" },
    [2929047577] = { ["english"] = { [1] = "Thank you for the spores, <name>.  They are now prepared for transport." }, ["npcs"] = { [1] = "Apothecary Helbrim" }, ["priority"] = 1, ["text"] = "Дякую за спори, {ім'я:к}. Тепер вони готові до транспортування.#the spores, <name>." },
    [2930352498] = { ["english"] = { [1] = "You are a fool, soon to forfeit his life. No?" }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Ти дурень, що скоро розпрощається з життям. Хіба ні?" },
    [2931401145] = { ["english"] = { [1] = "Nothing will stop us!  You will die!" }, ["npcs"] = { [1] = "Daggerspine Marauder" }, ["priority"] = 1, ["text"] = "Ніщо не зупинить нас! Ти помреш!" },
    [2933078400] = { ["english"] = { [1] = "Horgus, your nightmare ends!  Now!" }, ["npcs"] = { [1] = "Davil Lightfire" }, ["priority"] = 1, ["text"] = "Горґус, твоєму злу прийшов кінець!" },
    [2934665551] = { ["english"] = { [1] = "You carry the taint of the scourge.  Prepare to enter the twisting nether." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ви заплямовані Скарою. Приготуйтесь відправитись в Підсвітню Крутоверть." },
    [2936017095] = { ["english"] = { [1] = "Well done. A blow to Arugal no doubt!" }, ["npcs"] = { [1] = "Deathstalker Faerleia" }, ["priority"] = 1, ["text"] = "Гарна робота. І який потужний удар по Аруґалу!" },
    [2937636264] = { ["english"] = { [1] = "Faire's a coming!" }, ["npcs"] = { [1] = "Darkmoon Faire Carnie" }, ["priority"] = 1, ["text"] = "Ярмарок наближається!" },
    [2937661199] = { ["english"] = { [1] = "There we go!" }, ["npcs"] = { [1] = "Deathstalker Adamant" }, ["priority"] = 1, ["text"] = "Ось так!" },
    [2938500255] = { ["english"] = { [1] = "Help! We're being attacked! Dark Irons!" }, ["npcs"] = { [1] = "Miran" }, ["priority"] = 1, ["text"] = "Допоможіть! На нас напали! Дворфи Темного Заліза!" },
    [2943090952] = { ["english"] = { [1] = "All those who betray Ragnaros must die!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Кожен, хто йде проти Раґнароса, має померти!" },
    [2944506931] = { ["english"] = { [1] = "Knall ran the Gauntlet!  Three cheers for Knall!" }, ["npcs"] = { [1] = "Yorus Barleybrew" }, ["priority"] = 3, ["text"] = "Кналл пройшов Випробування!  Тричі слава Кналлу!" },
    [2947532470] = { ["english"] = { [1] = "Delicious!" }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Смакота!" },
    [2953512755] = { ["english"] = { [1] = "Do not force my hand, children! I shall use your hides to line my boots." }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Не випробовуйте мого терпіння, діти! Я обшию свої чоботи вашою шкірою." },
    [2955895145] = { ["english"] = { [1] = "There, it is done.  The book has been enhanced..." }, ["npcs"] = { [1] = "Chromie" }, ["priority"] = 1, ["text"] = "Ось і все. Я дещо покращила цю книгу..." },
    [29569834] = { ["english"] = { [1] = "%s feeds the squirrel some of the viscous fluid." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "%s годує білку в'язкою сумішшю." },
    [2958662936] = { ["english"] = { [1] = "Troll mojo da strongest mojo!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Трольське моджо — найкраще моджо!" },
    [2961950009] = { ["english"] = { [1] = "Tesoran! I need someone--Falgran Hastil, preferably--to take care of <name>'s lead on the prints near the Shady Rest Inn." }, ["npcs"] = { [1] = "Captain Garran Vimes" }, ["priority"] = 1, ["text"] = "Тесоране! Мені потрібно, щоб хтось — бажано, Фальґран Гастіл — зайнявся зачіпками {ім'я:р} щодо слідів біля таверни «Відпочинок у затінку»." },
    [2963527754] = { ["english"] = { [1] = "May this evil aura be banished from this artifact!" }, ["npcs"] = { [1] = "Eridan Bluewind" }, ["priority"] = 1, ["text"] = "Нехай зло покине цей артефакт!" },
    [2969683093] = { ["english"] = { [1] = "%s fumbles with the rusty lock on the courtyard door." }, ["npcs"] = { [1] = "Deathstalker Adamant" }, ["priority"] = 1, ["text"] = "%s возиться з іржавим замком на дверях внутрішнього двору." },
    [2979483088] = { ["english"] = { [1] = "Come, little ones." }, ["npcs"] = { [1] = "Emperor Vek'lor" }, ["priority"] = 1, ["text"] = "Підходьте, малята." },
    [2979810240] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Was that the third or fourth time you nearly got me gutted trying one of your crazy stunts?" }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "То був третій чи четвертий раз, коли ми мало не подохли через твої божевільні витівки?" } }, ["english"] = { [1] = "Was that the third or fourth time you nearly got me gutted trying one of your crazy stunts?" }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "То був третій чи четвертий раз, коли ми мало не подохли через твої божевільні витівки?" },
    [2979811118] = { ["english"] = { [1] = "I can't take these taxes! F.I.C.A. me? F.I.C.A. YOU!" }, ["npcs"] = { [1] = "Caretaker Alen" }, ["priority"] = 1, ["text"] = "Скільки можна терпіти всі ці податки? ПДФО? ПДНХ!" },
    [2980465660] = { ["english"] = { [1] = "I am Balgaras the Foul.  And you, <name>, are about to become nothing more than ash and dust." }, ["npcs"] = { [1] = "Balgaras the Foul" }, ["priority"] = 1, ["text"] = "Я — Балґарас Паскудний. А ти, {ім'я:к}, скоро станеш нікчемною купою попелу.#you, <name>, are" },
    [2985966305] = { ["english"] = { [1] = "We're doomed!" }, ["npcs"] = { [1] = "Blackhand Elite" }, ["priority"] = 1, ["text"] = "Нам кінець!" },
    [2992182168] = { ["english"] = { [1] = "But this can't be right. Where did I put that other book?" }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Але щось тут не сходиться. Куди я поклала іншу книгу?" },
    [2992655228] = { ["english"] = { [1] = "There is no escape for you.  The Crusade shall destroy all who carry the scourge's taint." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Вам немає спасіння. Похід знищить усіх, хто заплямований Скарою." },
    [2999204935] = { ["english"] = { [1] = "This will be my best experiment yet!" }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "Це буде мій найкращий експеримент!" },
    [3001936519] = { ["english"] = { [1] = "Let's go <name>!" }, ["npcs"] = { [1] = "Feero Ironhand" }, ["priority"] = 1, ["text"] = "Ходімо, {ім'я:к}!#Let's go <name>!" },
    [3017400878] = { ["english"] = { [1] = "You there. You're welcome to take the contents of my cauldron. It was to be the second stage of my plan - amorous clothing." }, ["npcs"] = { [1] = "Apothecary Staffron Lerent" }, ["priority"] = 1, ["text"] = "Гей, ти. Можеш забирати все з цього казана. Це мав бути другий етап мого плану — любовний одяг." },
    [3017851498] = { ["english"] = { [1] = "I can feel the presence of evil leaving..." }, ["npcs"] = { [1] = "Eridan Bluewind" }, ["priority"] = 1, ["text"] = "Я відчуваю, як зло відступає..." },
    [3021715985] = { ["english"] = { [1] = "It is time to face your final challenge young warriors! Prepare for your hardest fight yet." }, ["npcs"] = { [1] = "Brother Malach" }, ["priority"] = 1, ["text"] = "Час зіткнутись з вашим останнім випробуванням, юні воїни! Готуйтеся до вашого найважчого бою." },
    [3022050934] = { ["english"] = { [1] = "Hope is a DISEASE of the soul! This land shall wither and die!" }, ["npcs"] = { [1] = "Emeriss" }, ["priority"] = 1, ["text"] = "Надія — це ХВОРОБА душі! Ця земля приречена на загибель!" },
    [3025329287] = { ["english"] = { [1] = "%s shares his powers with his brethren." }, ["npcs"] = { [1] = "Anubisath Sentinel" }, ["priority"] = 1, ["text"] = "%s ділиться силами зі своїми побратимами." },
    [3025511735] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Move back and hold the line!  We cannot fail or all will be lost!" }, ["npcs"] = { [1] = "Crimson Guardsman" }, ["priority"] = 1, ["text"] = "Відступайте і тримайте оборону! Ми не можемо програти, інакше втратимо все!" }, [2] = { ["english"] = { [1] = "Move back and hold the line!  We cannot fail or all will be lost!" }, ["npcs"] = { [1] = "Crimson Initiate" }, ["priority"] = 1, ["text"] = "Відступайте і тримайте оборону! Ми не можемо програти, інакше втратимо все!" } }, ["english"] = { [1] = "Move back and hold the line!  We cannot fail or all will be lost!" }, ["npcs"] = { [1] = "Crimson Conjuror" }, ["priority"] = 1, ["text"] = "Відступайте і тримайте оборону! Ми не можемо програти, інакше втратимо все!" },
    [3031771785] = { ["english"] = { [1] = "Davil Lightfire is defeated!  Darrowshire is lost!" }, ["npcs"] = { [1] = "Darrowshire Defender" }, ["priority"] = 1, ["text"] = "Дейвіл Сяйносвіт мертвий! Дарроушир приречений!" },
    [3032670814] = { ["english"] = { [1] = "Three cheers for <name>!  This land shall be ours once again!" }, ["npcs"] = { [1] = "Gryan Stoutmantle" }, ["priority"] = 3, ["text"] = "Тричі слава {ім'я:д}!  Ця земля знову буде нашою!" },
    [3042997807] = { ["english"] = { [1] = "You, too, shall serve!" }, ["npcs"] = { [1] = "Archmage Arugal" }, ["priority"] = 1, ["text"] = "Ви теж будете служити!" },
    [30440407] = { ["english"] = { [1] = "Wolves head this way, as if fleeing from...something." }, ["npcs"] = { [1] = "Watcher Cutford" }, ["priority"] = 3, ["text"] = "Вовки прямують сюди, ніби тікають від... чогось." },
    [3049915890] = { ["english"] = { [1] = "An Ash'ari Crystal has fallen! Stay true to the Lich King, my brethren, and attempt to resummon it." }, ["npcs"] = { [1] = "Thuzadin Acolyte" }, ["priority"] = 1, ["text"] = "Кристал Аш'арі знищено! Залишайтеся вірними Королю-лічу, брати мої, і спробуйте відновити його." },
    [3054697045] = { ["english"] = { [1] = "%s surveys the ground and nods approvingly." }, ["npcs"] = { [1] = "Bath'rah the Windwatcher" }, ["priority"] = 1, ["text"] = "%s оглядає землю і схвально киває." },
    [306071217] = { ["english"] = { [1] = "My brother, no!" }, ["npcs"] = { [1] = "Emperor Vek'lor" }, ["priority"] = 1, ["text"] = "Брате мій, ні!" },
    [3066683783] = { ["english"] = { [1] = "Staffron..." }, ["npcs"] = { [1] = "Annalise Lerent" }, ["priority"] = 1, ["text"] = "Стаффрон..." },
    [3068117024] = { ["english"] = { [1] = "Excellent... it would appear as if the meddlesome insects have arrived just in time to feed my legion. Welcome, mortals!" }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Прекрасно... схоже, ці нікчеми прибули якраз вчасно, щоб стати кормом для мого легіону. Ласкаво прошу, смертні!" },
    [3070068773] = { ["english"] = { [1] = "You have disturbed my rest, <class>.  Now face my wrath!" }, ["npcs"] = { [1] = "Lillith Nefara" }, ["priority"] = 1, ["text"] = "Ти смієш порушувати мій спокій, {клас:н}? Пізнай мій гнів!#my rest, <class>." },
    [307243455] = { ["english"] = { [1] = "Vincent!  You and your pathetic ilk will find no more success in routing my sons and I than those beggardly remnants of the Kirin Tor." }, ["npcs"] = { [1] = "Arugal" }, ["priority"] = 1, ["text"] = "Вінсент! Спроби твого поріддя здолати мене та моїх синів ще нікчемніші за намагання жалюгідних решток Кірін-Тору." },
    [3077646605] = { ["english"] = { [1] = "Yes, commander!" }, ["npcs"] = { [1] = "Watcher Cutford" }, ["priority"] = 3, ["text"] = "Так, командире!" },
    [3077904620] = { ["english"] = { [1] = "Ashbringer..." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Спопелитель..." },
    [3080313064] = { ["english"] = { [1] = "Times have changed. The young races will join us. You will never succeed." }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "Часи змінилися. Молоді раси приєднаються до нас. Ми вас зупинимо." },
    [3081484674] = { ["english"] = { [1] = "I just saw a Scourge!  Kill it!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Тут Скара! Захищайте місто!" },
    [3082491081] = { ["english"] = { [1] = "%s explodes into poisonous goo!" }, ["npcs"] = { [1] = "Carrion Devourer" }, ["priority"] = 1, ["text"] = "%s вибухає отруйним слизом!" },
    [3083612335] = { ["english"] = { [1] = "You dare! Now feel my wrath, <target>." }, ["npcs"] = { [1] = "Magus Rimtori" }, ["priority"] = 1, ["text"] = "Як ти смієш! Відчуй мій гнів, {ціль:к}.#wrath, <target>." },
    [3084819251] = { ["english"] = { [1] = "Help me with this <target>!" }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Допоможи мені, тут {ціль}!#this <target>!" },
    [3085303866] = { ["english"] = { [1] = "Into the box me pretties! Thas it. One by one ye go." }, ["npcs"] = { [1] = "Monty" }, ["priority"] = 3, ["text"] = "У коробку, мої красунчики! Отак. Один за одним." },
    [308550878] = { ["english"] = { [1] = "Be bathed in my power! Drink in my might! Battle for the glory of the Horde!" }, ["npcs"] = { [1] = "Thrall" }, ["priority"] = 1, ["text"] = "Купайтеся в моїй силі! Сповнюйтесь моєю могутністю! Бийтеся за славу Орди!" },
    [3095622983] = { ["english"] = { [1] = "Your actions will not be tolerated!" }, ["npcs"] = { [1] = "Argent Sentry" }, ["priority"] = 1, ["text"] = "Ми не терпітимемо такої поведінки!" },
    [3096012755] = { ["english"] = { [1] = "Who dares disturb our master?" }, ["npcs"] = { [1] = "Black Guard Sentry" }, ["priority"] = 1, ["text"] = "Хто сміє турбувати нашого господаря?" },
    [309602857] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The best had to have been the look on Perenolde's face when our army comes marchin' right up to his front door. What a battle!" }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Хотів би я бачити пику Перенольда, коли наша армія підійшла прямо до його воріт. Ех, яка була битва!" } }, ["english"] = { [1] = "The best had to have been the look on Perenolde's face when our army comes marchin' right up to his front door. What a battle!" }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "От би побачити пику Перенольда, як наша армія підійшла прямо до його воріт. Ех, яка була битва!" },
    [3098218602] = { ["english"] = { [1] = "This death is only a temporary respite from my curse." }, ["npcs"] = { [1] = "Baron Silverlaine" }, ["priority"] = 1, ["text"] = "Ця смерть — лиш тимчасовий перепочинок від мого прокляття." },
    [3098926150] = { ["english"] = { [1] = "Death tarnishes %s's soul." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Смерть залишила свій слід на душі %s." },
    [3100550450] = { ["english"] = { [1] = "Ah, good.  These spores have rendered nicely.  Thank you, <name>." }, ["npcs"] = { [1] = "Apothecary Helbrim" }, ["priority"] = 1, ["text"] = "А, добре. Ці спори гарно сформувались. Дякую, {ім'я:к}.#Thank you, <name>." },
    [3102042338] = { ["english"] = { [1] = "Privates Theoric, Kitrin, Blythe, Agmond..." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "Рядові Теорик, Кітрін, Блайт, Аґмонд..." },
    [3105574118] = { ["english"] = { [1] = "Rise and defend your master!" }, ["npcs"] = { [1] = "Antu'sul" }, ["priority"] = 1, ["text"] = "Повстань і захищай свого господаря!" },
    [3106407048] = { ["english"] = { [1] = "What was that?" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Що це було?" },
    [3107140130] = { ["english"] = { [1] = "I really need a better system for filing these books. Ahh that's the one I wanted." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Треба б придумати кращу систему сортування книг. Ага, ось те, що я шукала." },
    [310723902] = { ["english"] = { [1] = "Sure, Paige. Just be gentle." }, ["npcs"] = { [1] = "Karlee Chaddis" }, ["priority"] = 1, ["text"] = "Звичайно, Пейдж. Тільки будь обережна." },
    [311034595] = { ["english"] = { [1] = "%s creates his toxin..." }, ["npcs"] = { [1] = "Apothecary Lydon" }, ["priority"] = 1, ["text"] = "%s створює свій токсин..." },
    [3114309360] = { ["english"] = { [1] = "Please, help me to get through this cursed forest, <race>." }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Прошу, допоможи мені пройти через цей проклятий ліс, {раса:к}.#cursed forest, <race>." },
    [311698368] = { ["english"] = { [1] = "Your moldering remains will serve ME as a testament to what happens when one is foolish enough to trespass in my domain!" }, ["npcs"] = { [1] = "Arugal" }, ["priority"] = 1, ["text"] = "Твої гнилі рештки служитимуть МЕНІ, як приклад того, що трапляється, коли хтось бездумно вдирається в мої володіння!" },
    [3123384480] = { ["english"] = { [1] = "How goes the barrel watching...?" }, ["npcs"] = { [1] = "Jarven Thunderbrew" }, ["priority"] = 1, ["text"] = "Ну як там бочки, цілі...?" },
    [312646525] = { ["english"] = { [1] = "What the squawk??? Squawk squawk, squawk? SQUAWK!" }, ["npcs"] = { [1] = "Polly" }, ["priority"] = 1, ["text"] = "Що за крраа? Крра кррраа, крррааа! КРРРАА!" },
    [3129544794] = { ["english"] = { [1] = "%s is weakened!" }, ["npcs"] = { [1] = "C'Thun" }, ["priority"] = 1, ["text"] = "%s ослаблений!" },
    [3135359180] = { ["english"] = { [1] = "It... It is over, Lord Staghelm. We are victorious. Albeit the cost for this victory was great." }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "Все... Все скінчено, Оленеріг. Ми перемогли. Хоча ціна цієї перемоги була великою." },
    [3135435259] = { ["english"] = { [1] = "Well done! I should be fine on my own from here. Remember to talk to Delgren when you return to Maestra's Post in Ashenvale." }, ["npcs"] = { [1] = "Feero Ironhand" }, ["priority"] = 1, ["text"] = "Молодець! Далі я, певно, впораюся сам. Не забудь поговорити з Дельґреном, коли повернешся на заставу Маєстри в Ясенеділ." },
    [3135509075] = { ["english"] = { [1] = "Gimme my dolly!!" }, ["npcs"] = { [1] = "Donna" }, ["priority"] = 1, ["text"] = "Віддай мою ляльку!!" },
    [3139041594] = { ["english"] = { [1] = "No sign of the final explosives shipment to the west either.  Where are those lollygaggers?" }, ["npcs"] = { [1] = "Dark Iron Bombardier" }, ["priority"] = 1, ["text"] = "На заході жодного вантажу вибухівки теж немає. Де ці ледацюги?" },
    [3142518824] = { ["english"] = { [1] = "You will not stop me from escaping here, <target>!" }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Ти не завадиш мені втекти звідси, {ціль}!#here, <target>!" },
    [3143501708] = { ["english"] = { [1] = "The Ashbringer is dead and there will never be another like him. The lesser Mograine is a far cry from the man his father was. You know this, Commander! It was, after all, your own leadership that was responsible for the death of the Scarlet Highlord Mograine." }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Спопелитель мертвий, і такого, як він, більше не буде. Молодший Моґрейн далекий від того, яким був його батько. Ви знаєте це, командире! Зрештою, саме ваше керівництво призвело до загибелі верховного повелителя Моґрейна." },
    [3147407079] = { ["english"] = { [1] = "And now, even those nations that you would have called allies have recoiled and joined forces with us... Yes, old one, do not look so surprised." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "І тепер навіть ті, кого ви вважали союзниками, приєдналися до нас... Так, старий, не дивуйся." },
    [3147804312] = { ["english"] = { [1] = "Where to go? What to do? So many choices that all end in pain, end in death." }, ["npcs"] = { [1] = "Anub'Rekhan" }, ["priority"] = 1, ["text"] = "Куди йти? Що робити? Так багато варіантів, але все одно в результаті вас чекає лише смерть." },
    [3156476458] = { ["english"] = { [1] = "How could this happen?" }, ["npcs"] = { [1] = "Warden Thelwater" }, ["priority"] = 3, ["text"] = "Як таке могло статися?" },
    [3156629050] = { ["english"] = { [1] = "Behold!  The Blue Recluse holds a feast in <his/her> honor!" }, ["npcs"] = { [1] = "Angus Stern" }, ["priority"] = 1, ["text"] = "\"Синій Відлюдник\" влаштовує бенкет на {стать:його:її} честь!#feast in <his/her> honor" },
    [315664060] = { ["english"] = { [1] = "The Light is with us this day!" }, ["npcs"] = { [1] = "Daphne Stilwell" }, ["priority"] = 1, ["text"] = "Світло береже нас!" },
    [3158386481] = { ["english"] = { [1] = "%s goes into a berserker rage!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s впадає в лють берсерка!" },
    [3162055176] = { ["english"] = { [1] = "Hiccup!" }, ["npcs"] = { [1] = "Brewmeister Bilger" }, ["priority"] = 1, ["text"] = "Гик!" },
    [3162950862] = { ["english"] = { [1] = "Your challenge has failed!" }, ["npcs"] = { [1] = "Doom'rel" }, ["priority"] = 1, ["text"] = "Не варто було кидати нам виклик!" },
    [3165421339] = { ["english"] = { [1] = "I don't think one charge is going to cut it. Keep fending them off!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Не думаю, що одного заряду вистачить. Продовжуйте стримувати їх!" },
    [3165568186] = { ["english"] = { [1] = "Hello, Charys. I have my list, could you get me all of that, especially the last ingredient." }, ["npcs"] = { [1] = "Karlee Chaddis" }, ["priority"] = 1, ["text"] = "Привіт, Черіс. Ось список, чи не могла б ти зібрати все це? Особливо останній інгредієнт." },
    [3166034954] = { ["english"] = { [1] = "Let me give you my regards for Greatfather Winter, scum..." }, ["npcs"] = { [1] = "Dark Iron Kidnapper" }, ["priority"] = 1, ["text"] = "Передавай мої вітання Дідусю Зимі, мерзото..." },
    [3166277165] = { ["english"] = { [1] = "Taste blade, mongrel!" }, ["npcs"] = { [1] = "Cenarion Hold Infantry" }, ["priority"] = 1, ["text"] = "Скуштуй клинка, падло!" },
    [3168470879] = { ["english"] = { [1] = "And now you know all that there is to know, mortal..." }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "Тепер ти знаєш усе, що потрібно, {стать:смертний:смертна}..." },
    [317449904] = { ["english"] = { [1] = "You must save him!" }, ["npcs"] = { [1] = "Darrowshire Poltergeist" }, ["priority"] = 1, ["text"] = "Ти маєш врятувати його!" },
    [317468712] = { ["english"] = { [1] = "This <target> has been driven mad from the corruption!" }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "{Ціль} божеволіє від скверни!#This <target> has been" },
    [3174793144] = { ["english"] = { [1] = "Run! They are coming!" }, ["npcs"] = { [1] = "Blackwing Technician" }, ["priority"] = 1, ["text"] = "Тікайте! Вони наближаються!" },
    [3178091955] = { ["english"] = { [1] = "My pleasure, sugar drop.  I'll be back soon..." }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "З радістю, люба. Скоро повернусь..." },
    [3179164387] = { ["english"] = { [1] = "Marshal Marris, sir.  Corporal Keeshan of the 12th Sabre Regiment returned from battle and reporting for duty!" }, ["npcs"] = { [1] = "Corporal Keeshan" }, ["priority"] = 1, ["text"] = "Маршале Марріс, сер. Капрал Кішан з дванадцятого кавалерійського полку повернувся з бою та готовий до служби!" },
    [3184902515] = { ["english"] = { [1] = "You... die now!!" }, ["npcs"] = { [1] = "Thaddius" }, ["priority"] = 1, ["text"] = "Ви... помрете!!" },
    [318609294] = { ["english"] = { [1] = "Hmm, it would seem Keever needs a new subject. If that fool Abernathy keeps taking Keever's subjects, Keever may have to have a word with him." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "Хмм, здається, Ківеру потрібний новий об'єкт для досліджень. Якщо цей дурень Абернаті продовжить забирати об'єкти у Ківера, Ківеру доведеться з ним поговорити." },
    [3192372511] = { ["english"] = { [1] = "There it is! Wide open. Good luck to you conquering what lies beyond. I must report back to the Kirin Tor at once!" }, ["npcs"] = { [1] = "Sorcerer Ashcrombe" }, ["priority"] = 1, ["text"] = "Ось так! Бажаю успіху з тим, що чекає на вас попереду. Я маю негайно повертатися до Кірін-Тору!" },
    [3192909156] = { ["english"] = { [1] = "%s uses his index finger to make a cutting motion across his neck." }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "%s проводить пальцем по шиї" },
    [3192992274] = { ["english"] = { [1] = "It wasn't my fault, Master Mazen!" }, ["npcs"] = { [1] = "Acolyte Dellis" }, ["priority"] = 1, ["text"] = "Це не моя вина, майстре Мазене!" },
    [3194759557] = { ["english"] = { [1] = "The only thing Metzen is going to be doing this Winter Veil is roasting on a spit!" }, ["npcs"] = { [1] = "Dark Iron Kidnapper" }, ["priority"] = 1, ["text"] = "Цієї Зимової Покрови Метцен буде смажитися на рожні!" },
    [3197241107] = { ["english"] = { [1] = "The Scourge are defeated!  Darrowshire is saved!" }, ["npcs"] = { [1] = "Darrowshire Defender" }, ["priority"] = 1, ["text"] = "Ми перемогли Скару! Дарроушир врятовано!" },
    [3198040626] = { ["english"] = { [1] = "%s collapses and begins to smolder." }, ["npcs"] = { [1] = "Core Hound" }, ["priority"] = 1, ["text"] = "%s падає і починає тліти." },
    [3200050258] = { ["english"] = { [1] = "Heeellp meee... ri... ribss... bro... broken." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Допоможіть мені... рe... ребра... з... зламані." },
    [320391416] = { ["english"] = { [1] = "Yes, run! It makes the blood pump faster!" }, ["npcs"] = { [1] = "Anub'Rekhan" }, ["priority"] = 1, ["text"] = "Біжіть, біжіть! Так м'ясо буде смачнішим!" },
    [3206429797] = { ["english"] = { [1] = "For so long I have drifted in my cursed form. You have freed me... Your hard work shall be repaid." }, ["npcs"] = { [1] = "Celebras the Redeemed" }, ["priority"] = 1, ["text"] = "Я так довго блукав у своїй проклятій подобі. Ви звільнили мене... і ви не залишитесь без винагороди." },
    [3209471463] = { ["english"] = { [1] = "You lack tact, Commander. This is not surprising. However, you are right in that the Horde will be forced to act. But not just the Horde. They already come - heroes from across the world." }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Вам бракує тактовності, командире. Це й не дивно. Проте, ви маєте рацію щодо того, що Орда буде змушена діяти. Але не лише Орда. Вони вже прибули — герої з усього світу." },
    [3214665951] = { ["english"] = { [1] = "The blood samples must be protected!  Destroy the intruders!" }, ["npcs"] = { [1] = "Death Talon Overseer" }, ["priority"] = 1, ["text"] = "Захищайте зразки крові! Знищте загарбників!" },
    [3216440276] = { ["english"] = { [1] = "%s refuses to die while its master is endangered!" }, ["npcs"] = { [1] = "Core Rager" }, ["priority"] = 1, ["text"] = "%s відмовляється помирати, поки його хазяїн в небезпеці!" },
    [3217790050] = { ["english"] = { [1] = "Try and make yourself useful, <race>. GET ME OUT OF HERE! The High Interrogator has the key." }, ["npcs"] = { [1] = "Commander Gor'shak" }, ["priority"] = 1, ["text"] = "Спробуй зробити щось корисне, {раса:к}. ЗВІЛЬНИ МЕНЕ ЗВІДСИ! Ключ у верховного допитувача.#useful, <race>." },
    [3222180413] = { ["english"] = { [1] = "%s, too injured, gives up the chase." }, ["npcs"] = { [1] = "Private Hendel" }, ["priority"] = 1, ["text"] = "%s надто поранений, щоб продовжувати спротив." },
    [3225973648] = { ["english"] = { [1] = "%s then takes aim at the bottles..." }, ["npcs"] = { [1] = "Rifleman Wheeler" }, ["priority"] = 1, ["text"] = "%s тоді прицілюється в пляшки..." },
    [322865156] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Your life is a fitting sacrifice for my master, <class>." }, ["npcs"] = { [1] = "Crimson Templar" }, ["priority"] = 1, ["text"] = "Ти будеш гарною жертвою для мого повелителя, {клас:к}.#my master, <class>." }, [2] = { ["english"] = { [1] = "Your life is a fitting sacrifice for my master, <class>." }, ["npcs"] = { [1] = "Earthen Templar" }, ["priority"] = 1, ["text"] = "Ти будеш гарною жертвою для мого повелителя, {клас:к}.#my master, <class>." }, [3] = { ["english"] = { [1] = "Your life is a fitting sacrifice for my master, <class>." }, ["npcs"] = { [1] = "Hoary Templar" }, ["priority"] = 1, ["text"] = "Ти будеш гарною жертвою для мого повелителя, {клас:к}.#my master, <class>." } }, ["english"] = { [1] = "Your life is a fitting sacrifice for my master, <class>." }, ["npcs"] = { [1] = "Azure Templar" }, ["priority"] = 1, ["text"] = "Ти будеш гарною жертвою для мого повелителя, {клас:к}.#my master, <class>." },
    [3232331725] = { ["english"] = { [1] = "The feast of souls begins now..." }, ["npcs"] = { [1] = "Emperor Vek'nilash" }, ["priority"] = 1, ["text"] = "Зараз ми поласуємо вашими душами..." },
    [3235846580] = { ["english"] = { [1] = "Oops!" }, ["npcs"] = { [1] = "William" }, ["priority"] = 1, ["text"] = "Ой!" },
    [3237535020] = { ["english"] = { [1] = "Kneel before me, mortal! Kneel before Zod!" }, ["npcs"] = { [1] = "Qiraji Officer Zod" }, ["priority"] = 1, ["text"] = "На коліна, смертні! На коліна перед Зодом!" },
    [3252111585] = { ["english"] = { [1] = "This doesn't bode well.  Send scouts to gather more intelligence, and stay on alert." }, ["npcs"] = { [1] = "Commander Althea Ebonlocke" }, ["priority"] = 1, ["text"] = "Це не віщує нічого доброго. Відправте розвідників і лишайтеся насторожі." },
    [325494198] = { ["english"] = { [1] = "Strike me down. I shall be reborn... Even more powerful..." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Вбий мене! Я відроджусь... Могутнішим..." },
    [3259821901] = { ["english"] = { [1] = "I'm jumpy as it is... and people insist on scaring me... Next time, though, I'll be ready!" }, ["npcs"] = { [1] = "Quixxil" }, ["priority"] = 1, ["text"] = "Я й так на нервах... а тут ще й всілякі недоумки лякають мене... Але наступного разу я буду готовий!" },
    [3260333702] = { ["english"] = { [1] = "Be gone from this place!" }, ["npcs"] = { [1] = "Windshaper Novice Seer" }, ["priority"] = 3, ["text"] = "Геть із цього місця!" },
    [3263720165] = { ["english"] = { [1] = "Pssst... <name>... Come closer, we need to talk." }, ["npcs"] = { [1] = "Doan Karhan" }, ["priority"] = 1, ["text"] = "Псс... {ім'я:н}... Підійди ближче, нам потрібно поговорити.#Pssst... <name>... Come" },
    [3263823540] = { ["english"] = { [1] = "And stay down!" }, ["npcs"] = { [1] = "Edwin VanCleef" }, ["priority"] = 1, ["text"] = "І не вставай!" },
    [3265273335] = { ["english"] = { [1] = "Well, that is just not right. The creature is far too small. Let us see what Keever's third batch will do." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "Ні, це зовсім не те. Створіння надто маленьке. Подивимося, що зробить третя формула Ківера." },
    [3266069665] = { ["english"] = { [1] = "I haven't really figured out what it is, but there's something strange about the hot springs..." }, ["npcs"] = { [1] = "Donova Snowden" }, ["priority"] = 1, ["text"] = "Я поки що не зовсім розібралася, але в цих гарячих джерелах є щось дивне..." },
    [3267096158] = { ["english"] = { [1] = "Superb! Because of your help, my people stand a chance of re-taking our beloved city. Three cheers to you!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Супер! Завдяки вашій допомозі у мого народу з'явився шанс повернути наше рідне місто. Ви найкращі!" },
    [3268175398] = { ["english"] = { [1] = "Now how am I supposed to get those mechanical wretches out of my fields?" }, ["npcs"] = { [1] = "Farmer Saldean" }, ["priority"] = 1, ["text"] = "І як я маю позбутися тих механічних потвор на полях?" },
    [3279297740] = { ["english"] = { [1] = "THIS CANNOT BE!!! Rend, deal with these insects." }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "ЦЬОГО НЕ МОЖЕ БУТИ!!! Ренд, розберись з цими нікчемами." },
    [3281845547] = { ["english"] = { [1] = "The cart! How did this happen? Relathor, come quickly, there's a fire!" }, ["npcs"] = { [1] = "Cyriden Farseeker" }, ["priority"] = 1, ["text"] = "Віз! Як це сталося? Релаторе, швидше, тут пожежа!" },
    [3284293977] = { ["english"] = { [1] = "Well done! Without your help I would have never been able to thwart that wave of troggs." }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Гарна робота! Без вашої допомоги я б ніколи не впоралась з цими трогами." },
    [3285418074] = { ["english"] = { [1] = "Me no run from <class> like you!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Я не тікати від {клас:н}!#from <class> like" },
    [3285806137] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You will pay the ultimate price for this insolence, little vermin.  Your soul is mine!" }, ["npcs"] = { [1] = "The Duke of Fathoms" }, ["priority"] = 1, ["text"] = "Ти заплатиш найвищу ціну за цю зухвалість, наволоч. Твоя душа буде моєю!" }, [2] = { ["english"] = { [1] = "You will pay the ultimate price for this insolence, little vermin.  Your soul is mine!" }, ["npcs"] = { [1] = "The Duke of Shards" }, ["priority"] = 1, ["text"] = "Ти заплатиш найвищу ціну за цю зухвалість, наволоч. Твоя душа буде моєю!" }, [3] = { ["english"] = { [1] = "You will pay the ultimate price for this insolence, little vermin.  Your soul is mine!" }, ["npcs"] = { [1] = "The Duke of Zephyrs" }, ["priority"] = 1, ["text"] = "Ти заплатиш найвищу ціну за цю зухвалість, наволоч. Твоя душа буде моєю!" } }, ["english"] = { [1] = "You will pay the ultimate price for this insolence, little vermin.  Your soul is mine!" }, ["npcs"] = { [1] = "The Duke of Cynders" }, ["priority"] = 1, ["text"] = "Ти заплатиш найвищу ціну за цю зухвалість, наволоч. Твоя душа буде моєю!" },
    [3285937107] = { ["english"] = { [1] = "We are saved! The peasants have escaped the Scourge!" }, ["npcs"] = { [1] = "Eris Havenfire" }, ["priority"] = 1, ["text"] = "Ми врятовані! Жителі втекли від Скари!" },
    [3286677349] = { ["english"] = { [1] = "You have my word that I shall find a use for your body after I've killed you, <target>." }, ["npcs"] = { [1] = "Apothecary Jorell" }, ["priority"] = 1, ["text"] = "Я знайду гарне застосування твоєму тілу після того, як вб'ю тебе, {ціль:к}.#killed you, <target>." },
    [3287285933] = { ["english"] = { [1] = "Killing you be easy." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Вбить тебе легко." },
    [3288429795] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Back to the drawing board." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Так, що там було в моїх записах..." } }, ["english"] = { [1] = "Back to the drawing board." }, ["npcs"] = { [1] = "Ozzie Togglevolt" }, ["priority"] = 1, ["text"] = "Доведеться повернутися до креслень." },
    [3297333262] = { ["english"] = { [1] = "HOORAY! I AM SAVED!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "УРА! Я ВРЯТОВАНИЙ!" },
    [3297564456] = { ["english"] = { [1] = "%s is nearly at full strength!" }, ["npcs"] = { [1] = "Pyroguard Emberseer" }, ["priority"] = 1, ["text"] = "%s майже повністю відновив сили!" },
    [3299754592] = { ["english"] = { [1] = "Thank you, Jessica." }, ["npcs"] = { [1] = "Scarlet Commander Marjhan" }, ["priority"] = 1, ["text"] = "Дякую, Джесіко." },
    [3301521119] = { ["english"] = { [1] = "Die!  Your kind has no place in Alterac Valley!" }, ["npcs"] = { [1] = "Captain Galvangar" }, ["priority"] = 1, ["text"] = "Згиньте! Таким, як ви, не місце в Альтерацькій долині!" },
    [3306693484] = { ["english"] = { [1] = "%s gives a negative shake of his head." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s заперечливо хитає головою." },
    [3308303532] = { ["english"] = { [1] = "Bah! That's no fun!" }, ["npcs"] = { [1] = "Pilot Stonegear" }, ["priority"] = 3, ["text"] = "Пхе! Так нецікаво!" },
    [3309896393] = { ["english"] = { [1] = "%s nods." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s киває." },
    [3309956292] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ah, <priest/priestess>, you came along just in time. I appreciate it." }, ["npcs"] = { [1] = "Sentinel Shaya" }, ["priority"] = 1, ["text"] = "А, {стать:жрець:жриця}, ти вчасно. Я дуже тобі вдячна.#Ah, <priest/priestess>, you" } }, ["english"] = { [1] = "Ah, <priest/priestess>, you came along just in time. I appreciate it." }, ["npcs"] = { [1] = "Deathguard Kel" }, ["priority"] = 1, ["text"] = "А, {стать:жрець:жриця}, ти вчасно. Я дуже тобі вдячний.#Ah, <priest/priestess>, you" },
    [3314734570] = { ["english"] = { [1] = "Such devastation... what a horrible mess..." }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Така руїна... який жахливий безлад..." },
    [3324038007] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I woke up in a bed in Northshire three weeks later. Don't remember a damn thing." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Я прокинувся тоді у Північнокраї через три тижні. Ні біса не пам'ятаю." } }, ["english"] = { [1] = "I woke up in a bed in Northshire three weeks later. Don't remember a damn thing." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Я прокинувся тоді у Північнокраї через три тижні. Ніц не пам'ятаю." },
    [3326678457] = { ["english"] = { [1] = "Move!" }, ["npcs"] = { [1] = "Zandalar Enforcer" }, ["priority"] = 1, ["text"] = "Ворушись!" },
    [3334184221] = { ["english"] = { [1] = "Why don't we deal with you now, Hendel? Lady Proudmoore will speak to you back in the tower." }, ["npcs"] = { [1] = "Archmage Tervosh" }, ["priority"] = 1, ["text"] = "Чому б нам не розібратися з тобою прямо зараз, Гіндель? Леді Праудмур поговорить з тобою у вежі." },
    [3335878221] = { ["english"] = { [1] = "Take a look around, <name>. Perhaps you will find something that I have missed." }, ["npcs"] = { [1] = "Daryn Lightwind" }, ["priority"] = 1, ["text"] = "Поглянь навкруги, {ім'я:к}. Можливо, ти знайдеш те, що я пропустила.#around, <name>." },
    [3338139917] = { ["english"] = { [1] = "No hello for your old friend, Narain? Who were you expecting???" }, ["npcs"] = { [1] = "Doctor Weavil" }, ["priority"] = 1, ["text"] = "Навіть не привітаєш свого старого друга, Нараін? Кого ти думав тут побачити???" },
    [3340575194] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You fools think you can defeat me so easily? Face the true might of the Nathrezim!" }, ["npcs"] = { [1] = "Grand Crusader Dathrohan" }, ["priority"] = 1, ["text"] = "Ви, дурні, думаєте, що можете так легко мене перемогти? Відчуйте справжню міць натрезима!" } }, ["english"] = { [1] = "You fools think you can defeat me so easily? Face the true might of the Nathrezim!" }, ["npcs"] = { [1] = "Balnazzar" }, ["priority"] = 1, ["text"] = "Ви, дурні, думаєте, що можете так легко мене перемогти? Відчуйте справжню міць натрезима!" },
    [3343124007] = { ["english"] = { [1] = "%s laughs." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s сміється." },
    [334368482] = { ["english"] = { [1] = "Right away, Servitor." }, ["npcs"] = { [1] = "Zandalar Enforcer" }, ["priority"] = 1, ["text"] = "Слухаюсь, Слуго." },
    [3346081443] = { ["english"] = { [1] = "Be cleansed by blade, filth!" }, ["npcs"] = { [1] = "Fallen Hero" }, ["priority"] = 1, ["text"] = "Очистись моїм клинком, погань!" },
    [3347873813] = { ["english"] = { [1] = "Baby wants her dolly!" }, ["npcs"] = { [1] = "William" }, ["priority"] = 1, ["text"] = "Малявка хоче свою ляльку!" },
    [3351208450] = { ["english"] = { [1] = "More bones to gnaw on..." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ррр, погриземо кістки..." },
    [3353565053] = { ["english"] = { [1] = "To me, my servants!" }, ["npcs"] = { [1] = "Amnennar the Coldbringer" }, ["priority"] = 1, ["text"] = "До мене, мої слуги!" },
    [3353703483] = { ["english"] = { [1] = "Are you so eager to die? I will be happy to accommodate you..." }, ["npcs"] = { [1] = "The Prophet Skeram" }, ["priority"] = 1, ["text"] = "Ви так жадаєте померти? Я з радістю допоможу вам..." },
    [3359642403] = { ["english"] = { [1] = "%s charges!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s стрімко атакує!" },
    [3360722367] = { ["english"] = { [1] = "Who dares interfere with the Sons of Arugal?" }, ["npcs"] = { [1] = "Archmage Arugal" }, ["priority"] = 1, ["text"] = "Хто сміє перешкоджати Синам Аруґала?" },
    [3361043165] = { ["english"] = { [1] = "Shaha lor'ma. Elune be with you." }, ["npcs"] = { [1] = "Tyrande Whisperwind" }, ["priority"] = 3, ["text"] = "Shaha lor'ma. Нехай Елуна буде з тобою." },
    [33615730] = { ["english"] = { [1] = "How could you love me, Annalise? Look at me. I am not the man you once knew." }, ["npcs"] = { [1] = "Apothecary Staffron Lerent" }, ["priority"] = 1, ["text"] = "Як ти можеш кохати мене, Анналіз? Поглянь на мене. Я не той чоловік, якого ти колись знала." },
    [3369569650] = { ["english"] = { [1] = "Farewell. We shall speak again, I'm sure." }, ["npcs"] = { [1] = "Archmage Tervosh" }, ["priority"] = 1, ["text"] = "Бувай. Певен, ми ще зустрінемось." },
    [3375493715] = { ["english"] = { [1] = "Think I'm starting to wear a rut in the paving stones." }, ["npcs"] = { [1] = "Ol' Emma" }, ["priority"] = 1, ["text"] = "Здається, я вже протоптала доріжку в бруківці." },
    [3386259729] = { ["english"] = { [1] = "Hello, Antonio. It's good to see you safely made it here again. Let me know if you need anything." }, ["npcs"] = { [1] = "Amy Davenport" }, ["priority"] = 1, ["text"] = "Привіт, Антоніо. Рада, що ти знову безнапасно дістався сюди. Дай знати, якщо тобі щось знадобиться." },
    [3388687722] = { ["english"] = { [1] = "Come get yer fresh bread!" }, ["npcs"] = { [1] = "Myra Tyrngaarde" }, ["priority"] = 1, ["text"] = "Підходьте по свіжий хліб!" },
    [3388711179] = { ["english"] = { [1] = "Sir, student requests that you beat him for his lack of understanding!" }, ["npcs"] = { [1] = "Deathknight Understudy" }, ["priority"] = 1, ["text"] = "Пане, учень просить, щоб ви побили його за нерозуміння!" },
    [3392640379] = { ["english"] = { [1] = "Usurpers! Gnomeregan is mine!" }, ["npcs"] = { [1] = "Mekgineer Thermaplugg" }, ["priority"] = 1, ["text"] = "Загарбники! Гномреґан мій!" },
    [3396214677] = { ["english"] = { [1] = "The sands of time will halt, but only for a moment! I will now conjure the barrier." }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "Піски часу зупинять їх, але лиш на мить! Зараз я вичарую бар'єр." },
    [3396598166] = { ["english"] = { [1] = "...too quiet." }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "...занадто тихо." },
    [3399884994] = { ["english"] = { [1] = "%s pokes the small toad." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "%s штрикає пальцем маленьку жабу." },
    [3408401762] = { ["english"] = { [1] = "You will pay for what you've done to Trey, <target>!" }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Ти заплатиш за те, що сталось з Треєм, {ціль}!#Trey, <target>!" },
    [3413150736] = { ["english"] = { [1] = "Don't let them catch you!" }, ["npcs"] = { [1] = "Theramore Sentry" }, ["priority"] = 1, ["text"] = "Не дай їм себе спіймати!" },
    [3414947130] = { ["english"] = { [1] = "Can we take a break? My feet are killing me and those ... those things down there are creeping me out." }, ["npcs"] = { [1] = "Defias Tower Patroller" }, ["priority"] = 1, ["text"] = "Може, зробимо перерву? Мої ноги вже відпадають, і ті... ті створіння внизу мене лякають." },
    [3415591140] = { ["english"] = { [1] = "Your undeath is not the end of your life, but the beginning. It is up to you to decide where your fate lies now." }, ["npcs"] = { [1] = "Caretaker Caice" }, ["priority"] = 1, ["text"] = "Твоє нежиття — це не кінець твого життя, а лише початок. Твоя доля залежить лише від тебе." },
    [3420136106] = { ["english"] = { [1] = "Stay close..." }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "Тримайся поруч..." },
    [3420974449] = { ["english"] = { [1] = "Never cross a Dark Iron, <class>." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ніколи не переходь дорогу Темному Залізу, {клас:к}.#Iron, <class>" },
    [3424761200] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "%s will be armed in 5 seconds!" }, ["npcs"] = { [1] = "Goblin Land Mine" }, ["priority"] = 1, ["text"] = "%s активується через 5 секунд!" } }, ["english"] = { [1] = "%s will be armed in 5 seconds!" }, ["npcs"] = { [1] = "Dark Iron Land Mine" }, ["priority"] = 1, ["text"] = "%s активується через 5 секунд!" },
    [343338757] = { ["english"] = { [1] = "%s begins translating ..." }, ["npcs"] = { [1] = "Sirra Von'Indi" }, ["priority"] = 3, ["text"] = "%s починає перекладати..." },
    [3434480918] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I miss the dwarven ale we used to get at that inn in Lordaeron. Remember that fight we started there?" }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Я сумую за дворфійським елем, який ми пили у тій таверні в Лордероні. Пам'ятаєш, яку ми там бійку влаштували?" } }, ["english"] = { [1] = "I miss the dwarven ale we used to get at that inn in Lordaeron. Remember that fight we started there?" }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Я сумую за дворфійським елем, який ми пили у тій таверні в Лордероні. Пам'ятаєш, яку ми там бійку влаштували?" },
    [3444230028] = { ["english"] = { [1] = "Take care of yourself, Antonio. I'll see you in another week." }, ["npcs"] = { [1] = "Amy Davenport" }, ["priority"] = 1, ["text"] = "Бережи себе, Антоніо. Побачимось наступного тижня." },
    [3447518874] = { ["english"] = { [1] = "So why are you here? What are we to do if there is no hope?" }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "То чому ж ви тут? Що нам робити, якщо надії немає?" },
    [3450036535] = { ["english"] = { [1] = "Good day, Elling!  Hullo Elaine!  Let me have a wheel of bleu cheese, eh?" }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Доброго дня, Елінг!  Вітаю, Елейн! Дайте мені трішки того чудового дарнаського блю." },
    [3454624716] = { ["english"] = { [1] = "Who dares disturb me?  Die <name>!" }, ["npcs"] = { [1] = "Stalvan Mistmantle" }, ["priority"] = 3, ["text"] = "Хто сміє мене турбувати?  Помри, <name>!" },
    [345562914] = { ["english"] = { [1] = "BY FIRE BE PURGED!" }, ["npcs"] = { [1] = "Ragnaros" }, ["priority"] = 1, ["text"] = "ВОГОНЬ ОЧИСТИТЬ ВАС!" },
    [3458693954] = { ["english"] = { [1] = "I heard something over there." }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Я чула щось звідти." },
    [3459181620] = { ["english"] = { [1] = "Father, you had the bowl of fruit? Right?" }, ["npcs"] = { [1] = "Jessica Chambers" }, ["priority"] = 1, ["text"] = "Отче, ви хотіли фрукти, правильно?" },
    [3462387118] = { ["english"] = { [1] = "Your leader takes residence at the doorstep to Naxxramas. Do you think he does not feel the pressure?" }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Ваш очільник оселився прямо під самим Наксрамасом. Думаєте, він не відчуває загрози?" },
    [3462643851] = { ["english"] = { [1] = "Stay back vile creatures!" }, ["npcs"] = { [1] = "Rane Yorick" }, ["priority"] = 1, ["text"] = "Ідіть геть, мерзенні створіння!" },
    [3464553593] = { ["english"] = { [1] = "Assassins from that cult you found... Let's get moving before someone else finds us out here." }, ["npcs"] = { [1] = "Feero Ironhand" }, ["priority"] = 1, ["text"] = "Душогуби з того нового культу... Потрібно рушати, поки нас тут хтось ще не знайшов." },
    [3465496111] = { ["english"] = { [1] = "The corruption of the fel has not left any of the creatures of Felwood untouched, <name>. Please, be on your guard." }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Скверна не оминула жодної істоти в Скверноліссі, {ім'я:к}. Будь ласка, будь насторожі.#untouched, <name>." },
    [3470112421] = { ["english"] = { [1] = "Am I carrying any letters addressed to <name>? Why, no!  Looks like it's time for you to die!" }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "Хм, чи є в мене листи для {ім'я:р}? Ні! Здається, тобі доведеться вмерти!#to <name>?" },
    [3476828457] = { ["english"] = { [1] = "%s forces the fluid down the weary man's throat." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "%s вливає рідину в горло змученої людини." },
    [3476960721] = { ["english"] = { [1] = "School is in session!" }, ["npcs"] = { [1] = "Darkmaster Gandling" }, ["priority"] = 1, ["text"] = "Заняття починаються!" },
    [34787713] = { ["english"] = { [1] = "Indeed... lovely dress, Jessica." }, ["npcs"] = { [1] = "Archmage Angela Dosantos" }, ["priority"] = 1, ["text"] = "Справді, чудова сукня, Джессіко." },
    [3482326861] = { ["english"] = { [1] = "Feel the power of the Blackrock Orcs!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Відчуй силу орків Чорнокаменю!" },
    [3483107944] = { ["english"] = { [1] = "Juicy fruits for sale!" }, ["npcs"] = { [1] = "Bimble Longberry" }, ["priority"] = 1, ["text"] = "Купуйте соковиті фрукти!" },
    [3486896047] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "It's done <name>, and I think you'll be satisfied with the results." }, ["npcs"] = { [1] = "Apothecary Dithers" }, ["priority"] = 1, ["text"] = "Готово, {ім'я:к}, і я думаю, що тобі сподобається результат.#It's done <name>," } }, ["english"] = { [1] = "It's done <name>, and I think you'll be satisfied with the results." }, ["npcs"] = { [1] = "Alchemist Arbington" }, ["priority"] = 1, ["text"] = "Готово, {ім'я:к}, і я думаю, що тобі сподобається результат.#It's done <name>," },
    [3491563912] = { ["english"] = { [1] = "Horgus is slain!  Take heart, defenders of Darrowshire!" }, ["npcs"] = { [1] = "Darrowshire Defender" }, ["priority"] = 1, ["text"] = "Горґус мертвий! Тримайтесь, захисники Дарроушира!" },
    [3492394895] = { ["english"] = { [1] = "My mind. . .my flesh. . .I'm. . .rotting. . . .!" }, ["npcs"] = { [1] = "Captured Scarlet Zealot" }, ["priority"] = 1, ["text"] = "Мій розум... моя плоть... я... гнию!" },
    [350043122] = { ["english"] = { [1] = "He's mine..." }, ["npcs"] = { [1] = "Dark Iron Marksman" }, ["priority"] = 1, ["text"] = "Він мій..." },
    [3503380824] = { ["english"] = { [1] = "You have failed!" }, ["npcs"] = { [1] = "Grand Widow Faerlina" }, ["priority"] = 1, ["text"] = "Жалюгідно!" },
    [3503533118] = { ["english"] = { [1] = "Awake, ye servants! Defend the Disks!" }, ["npcs"] = { [1] = "Archaedas" }, ["priority"] = 1, ["text"] = "Прокиньтесь, слуги! Захищайте диски!" },
    [350414861] = { ["english"] = { [1] = "The deeds are mine, brother! Soon you shall be out of my way for good!" }, ["npcs"] = { [1] = "Alexi Barov" }, ["priority"] = 1, ["text"] = "Документи мої, брате! Скоро ти назавжди зникнеш з мого життя!" },
    [3508941530] = { ["english"] = { [1] = "Privates Horus, Tilling, Rockwell..." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "Рядові Горус, Тіллінг, Роквелл..." },
    [351131910] = { ["english"] = { [1] = "Greetings, <class>!  Welcome to the Cathedral of Light!" }, ["npcs"] = { [1] = "Brother Sarno" }, ["priority"] = 1, ["text"] = "Вітаю, {клас:к}! Ласкаво просимо до собору Світла!#Greetings, <class>!" },
    [3515783640] = { ["english"] = { [1] = "You know not what you do!  We must destroy you for your own good." }, ["npcs"] = { [1] = "Dreamscythe" }, ["priority"] = 1, ["text"] = "Ви не знаєте, що робите! Ми маємо знищити вас заради вашого блага." },
    [3517079076] = { ["english"] = { [1] = "We'll have your heads!" }, ["npcs"] = { [1] = "Dark Strand Assassin" }, ["priority"] = 1, ["text"] = "Ми відрубаємо вам голови!" },
    [3517227850] = { ["english"] = { [1] = "It's okay, boys. Back off. You've done enough. I'll meet up with you later." }, ["npcs"] = { [1] = "Dashel Stonefist" }, ["priority"] = 1, ["text"] = "Все гаразд, хлопці. Досить, ви добре впорались. Побачимось пізніше." },
    [3523209634] = { ["english"] = { [1] = "Break... you!!" }, ["npcs"] = { [1] = "Thaddius" }, ["priority"] = 1, ["text"] = "Нищити... вас!!" },
    [3529954952] = { ["english"] = { [1] = "Danger. Danger! <target> try hurt A-Me." }, ["npcs"] = { [1] = "A-Me 01" }, ["priority"] = 1, ["text"] = "Небезпека. Небезпека! {Ціль} намагається зашкодити Е-Мі.#Danger! <target> try hurt" },
    [3541837878] = { ["english"] = { [1] = "Have I forgotten? Of course I have... I have forgotten about love, happiness... of life itself." }, ["npcs"] = { [1] = "Apothecary Staffron Lerent" }, ["priority"] = 1, ["text"] = "Чи забув я? Звісно, що забув... Я забув про любов, щастя... про саме життя." },
    [3541841561] = { ["english"] = { [1] = "Is that the best you can do?" }, ["npcs"] = { [1] = "High Overlord Saurfang" }, ["priority"] = 1, ["text"] = "Це все, що ти можеш?" },
    [3549731622] = { ["english"] = { [1] = "A fine trophy your head will make, <race>." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "З твоєї голови буде гарний трофей, {раса:к}.#will make, <race>." },
    [3551363608] = { ["english"] = { [1] = "I see the exit! Hurry, hurry!" }, ["npcs"] = { [1] = "Kernobee" }, ["priority"] = 1, ["text"] = "Я бачу вихід! Швидше, швидше!" },
    [35523535] = { ["english"] = { [1] = "Do not forget the sacrifices made on this day, night elf. We have all suffered immensely at the hands of these beasts." }, ["npcs"] = { [1] = "Caelestrasz" }, ["priority"] = 1, ["text"] = "Не забувай про жертви, принесені в цей день, нічний ельфе. Ми всі безмірно постраждали від цих звірів." },
    [3552517599] = { ["english"] = { [1] = "What?  How dare you say that to me?!?" }, ["npcs"] = { [1] = "Sergeant Bly" }, ["priority"] = 1, ["text"] = "Що? Як ти смієш таке казати?!?" },
    [3554348730] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ahh yes, now I remember, your wedding night wasn't it?" }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "А-а-а, так, згадав. Це ж в тебе тоді весілля було?" } }, ["english"] = { [1] = "Ahh yes, now I remember, your wedding night wasn't it?" }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "А-а-а, так, згадав. Це ж в тебе тоді весілля було?" },
    [3555320301] = { ["english"] = { [1] = "Let me install these Gyromechanic Gears and Restabilization Cogs and we'll fire up The Recombobulator." }, ["npcs"] = { [1] = "Razzle Sprysprocket" }, ["priority"] = 1, ["text"] = "Дай мені встановити ці гіромеханічні шестірні та зубці рестабілізації, і ми запустимо Рекомбобулятор." },
    [3559739940] = { ["english"] = { [1] = "One more minute!  Hold on now, the ritual is about to take hold!" }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Ще одна хвилина! Тримайтесь, ритуал от-от завершиться!" },
    [3560486642] = { ["english"] = { [1] = "And it's the Goblin Racer coming through turn one!" }, ["npcs"] = { [1] = "Fobeed" }, ["priority"] = 1, ["text"] = "І гонщик гоблінів проходить перший поворот!" },
    [3562114341] = { ["english"] = { [1] = "Sands consume you!" }, ["npcs"] = { [1] = "Witch Doctor Zum'rah" }, ["priority"] = 1, ["text"] = "Піски поглинуть вас!" },
    [3563165462] = { ["english"] = { [1] = "Very interesting. But if that's the case then my theory is wrong. I must reread the other sections to see what I missed." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Дуже цікаво. Але якщо це так, то моя теорія помилкова. Мені потрібно перечитати інші розділи, щоб зрозуміти, що я пропустила." },
    [3565400157] = { ["english"] = { [1] = "Time to get back to the shop..." }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Пора повертатись до крамниці..." },
    [3572161721] = { ["english"] = { [1] = "A <target> attacks!" }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "{Ціль:н} атакує!#A <target> attacks" },
    [3573377595] = { ["english"] = { [1] = "Stop! You'll pull her head off!" }, ["npcs"] = { [1] = "Donna" }, ["priority"] = 1, ["text"] = "Перестань! Ти відірвеш їй голову!" },
    [3577516266] = { ["english"] = { [1] = "If this is correct then I have a lot more research to do." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Якщо це дійсно так, мені доведеться провести значно більше досліджень." },
    [3577903710] = { ["english"] = { [1] = "You challenge the charge of the Blue Dragonflight? DIE, vermin." }, ["npcs"] = { [1] = "Azuregos" }, ["priority"] = 1, ["text"] = "Ви кидаєте виклик синім драконам? ПОМРІТЬ, паразити." },
    [3577917781] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Only a fool would remain in this battle. Farewell, coward." }, ["npcs"] = { [1] = "Franklin the Friendly" }, ["priority"] = 1, ["text"] = "Тільки дурень продовжував би цю битву. Бувай, {стать:боягузе:боягузко}." } }, ["english"] = { [1] = "Only a fool would remain in this battle. Farewell, coward." }, ["npcs"] = { [1] = "Artorius the Amiable" }, ["priority"] = 1, ["text"] = "Тільки дурень продовжував би цю битву. Бувай, {стать:боягузе:боягузко}." },
    [3579486760] = { ["english"] = { [1] = "Oomph!  Here's another load of supplies, Harlan.  It must be selling fast!" }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Ох! Ось ще одна партія товарів, Гарлане. Бачу, у вас тут ажіотаж!" },
    [359057526] = { ["english"] = { [1] = "The master will avenge me!!" }, ["npcs"] = { [1] = "Grand Widow Faerlina" }, ["priority"] = 1, ["text"] = "Повелитель помститься за мене!!" },
    [3590975022] = { ["english"] = { [1] = "You won't find better prices anywhere!" }, ["npcs"] = { [1] = "Augustus the Touched" }, ["priority"] = 1, ["text"] = "Ви ніде не знайдете кращих цін!" },
    [3595477418] = { ["english"] = { [1] = "I come from the land down under... where women plague and men sunder." }, ["npcs"] = { [1] = "Caretaker Alen" }, ["priority"] = 1, ["text"] = "І гуля нема, немає вже гуля... Немає ніц вопше, сама сира земля..." },
    [3596548516] = { ["english"] = { [1] = "Home again, home again." }, ["npcs"] = { [1] = "Antonio Perelli" }, ["priority"] = 1, ["text"] = "Дім, любий дім." },
    [3598012517] = { ["english"] = { [1] = "I am the hand of the Lich King!" }, ["npcs"] = { [1] = "Amnennar the Coldbringer" }, ["priority"] = 1, ["text"] = "Я — рука Короля-ліча!" },
    [3604749006] = { ["english"] = { [1] = "Anaya...? Do my eyes deceive me? Is it really you?" }, ["npcs"] = { [1] = "Cerellean Whiteclaw" }, ["priority"] = 1, ["text"] = "Анайя...? Може, я марю? Невже це дійсно ти?" },
    [3611397749] = { ["english"] = { [1] = "Kill her! Take the farm!" }, ["npcs"] = { [1] = "Defias Raider" }, ["priority"] = 1, ["text"] = "Вбийте її! Захопіть ферму!" },
    [3615298387] = { ["english"] = { [1] = "Take a stone from the table, <name>.  You will need it for your quest." }, ["npcs"] = { [1] = "Ak'Zeloth" }, ["priority"] = 1, ["text"] = "Візьми камінь зі столу, {ім'я:к}. Він знадобиться тобі для цього завдання.#from the table, <name>" },
    [361545900] = { ["english"] = { [1] = "We showed that one!" }, ["npcs"] = { [1] = "Daphne Stilwell" }, ["priority"] = 1, ["text"] = "Ми їх провчили!" },
    [3616868007] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "This act of defiance will not go unpunished.  You, and your world, will die!" }, ["npcs"] = { [1] = "The Duke of Fathoms" }, ["priority"] = 1, ["text"] = "Цей акт непокори не залишиться безкарним. Ти загинеш, як і твій світ!" }, [2] = { ["english"] = { [1] = "This act of defiance will not go unpunished.  You, and your world, will die!" }, ["npcs"] = { [1] = "The Duke of Shards" }, ["priority"] = 1, ["text"] = "Цей акт непокори не залишиться безкарним. Ти загинеш, як і твій світ!" }, [3] = { ["english"] = { [1] = "This act of defiance will not go unpunished.  You, and your world, will die!" }, ["npcs"] = { [1] = "The Duke of Zephyrs" }, ["priority"] = 1, ["text"] = "Цей акт непокори не залишиться безкарним. Ти загинеш, як і твій світ!" } }, ["english"] = { [1] = "This act of defiance will not go unpunished.  You, and your world, will die!" }, ["npcs"] = { [1] = "The Duke of Cynders" }, ["priority"] = 1, ["text"] = "Цей акт непокори не залишиться безкарним. Ти загинеш, як і твій світ!" },
    [3617044492] = { ["english"] = { [1] = "Foolishly you have sought your own demise." }, ["npcs"] = { [1] = "Gothik the Harvester" }, ["priority"] = 1, ["text"] = "Ваша дурість привела вас до власної загибелі." },
    [3618533912] = { ["english"] = { [1] = "Mayor Ello!  Our graveyard scouts return with ominous reports..." }, ["npcs"] = { [1] = "Watcher Cutford" }, ["priority"] = 3, ["text"] = "Мере Елло! Наші розвідники з кладовища повернулися з лихими звістками..." },
    [3618540451] = { ["english"] = { [1] = "Shadow, the translation is finished!" }, ["npcs"] = { [1] = "Sirra Von'Indi" }, ["priority"] = 3, ["text"] = "Шедоу, переклад завершено!" },
    [3621759004] = { ["english"] = { [1] = "Good luck with Arugal. I must hurry back to Hadrec now." }, ["npcs"] = { [1] = "Deathstalker Adamant" }, ["priority"] = 1, ["text"] = "Нехай щастить з Аруґалом. Я маю негайно повертатися до Гадрека." },
    [3622008866] = { ["english"] = { [1] = "Your soul is mine, weakling." }, ["npcs"] = { [1] = "Artorius the Amiable" }, ["priority"] = 1, ["text"] = "Твоя душа буде моєю, нікчемо." },
    [3622396216] = { ["english"] = { [1] = "Please... please... Miss Proudmore. I didn't mean to..." }, ["npcs"] = { [1] = "Private Hendel" }, ["priority"] = 1, ["text"] = "Будь ласка... прошу вас... Пані Праудмур. Я не хотів..." },
    [362649005] = { ["english"] = { [1] = "Ready when you are, <class>." }, ["npcs"] = { [1] = "Big Will" }, ["priority"] = 1, ["text"] = "Ну, нападай, {клас:к}.#you are, <class>." },
    [3628531521] = { ["english"] = { [1] = "Such is the price of curiosity." }, ["npcs"] = { [1] = "Azuregos" }, ["priority"] = 1, ["text"] = "Така ціна допитливості." },
    [3628828817] = { ["english"] = { [1] = "Nice work! I'll set off the charges to prevent any more troggs from making it to the surface." }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Чудова робота! Я підірву заряди, щоб троги більше не лізли на поверхню." },
    [3629662650] = { ["english"] = { [1] = "All I need now is a golden lasso." }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Мені потрібно лиш моє золоте ласо." },
    [3631142510] = { ["english"] = { [1] = "*Sigh* You're probably right, Raven. I'm going back on patrol...." }, ["npcs"] = { [1] = "Defias Tower Patroller" }, ["priority"] = 1, ["text"] = "*Зітхає* Мабуть, ти маєш рацію, Вороно. Я повертаюсь на патрулювання...." },
    [3631412734] = { ["english"] = { [1] = "I'll cut you!" }, ["npcs"] = { [1] = "Leper Gnome" }, ["priority"] = 1, ["text"] = "Я тебе поріжу!" },
    [3631428161] = { ["english"] = { [1] = "The Wickerman Festival now begins!  Power to the Forsaken!" }, ["npcs"] = { [1] = "Darkcaller Yanka" }, ["priority"] = 1, ["text"] = "Фестиваль Плетеного чоловічка починається! Силу відреченим!" },
    [3631474090] = { ["english"] = { [1] = "%s begins to retaliate all attacks against him!" }, ["npcs"] = { [1] = "Captain Kromcrush" }, ["priority"] = 1, ["text"] = "%s починає контратакувати у відповідь на всі атаки!" },
    [3640800407] = { ["english"] = { [1] = "You'll rue the day you crossed me, <target>." }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Ти пошкодуєш про зустріч зі мною, {ціль}.#me, <target>." },
    [3642562166] = { ["english"] = { [1] = "Don't forget to buy refreshments and souvenirs!" }, ["npcs"] = { [1] = "Darkmoon Faire Carnie" }, ["priority"] = 1, ["text"] = "Не забудьте придбати напої та сувеніри!" },
    [3645278087] = { ["english"] = { [1] = "Maybe we should go to the bridge and fish." }, ["npcs"] = { [1] = "Adam" }, ["priority"] = 1, ["text"] = "Може підемо ловити рибу з мосту?" },
    [3646152366] = { ["english"] = { [1] = "Why ... won't you ... just dieeeee?" }, ["npcs"] = { [1] = "Qiraji Captain Ka'ark" }, ["priority"] = 1, ["text"] = "Чому... ви... не помираєте?" },
    [364811161] = { ["english"] = { [1] = "So this is what you have come for? To try and claim that which is the reason for the Dawn's existence and the Crusade's downfall? You open old wounds with your words, Commander!" }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "То за цим ви прийшли? Ця одержимість вже занапастила Багряний Похід! Досить ятрити старі рани, командире!" },
    [3656900637] = { ["english"] = { [1] = "Ragnaros has withdrawn to the elemental plane." }, ["npcs"] = { [1] = "Ragnaros" }, ["priority"] = 1, ["text"] = "Рагнарос відійшов у вимір стихій." },
    [3656995108] = { ["english"] = { [1] = "Not what Keever was hoping for. Keever may have added too much earthroot. Let's see if the second serum will do what I need." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "Не те, на що сподівався Ківер. Можливо, Ківер додав забагато землекореню. Подивимось, чи зробить інша сироватка те, що мені потрібно." },
    [3660307838] = { ["english"] = { [1] = "There's one of the Scourge, right over there!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Скара! Прямо тут!" },
    [3660334242] = { ["english"] = { [1] = "10 seconds to blast! Stand back!!!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "10 секунд до вибуху! Відійдіть!!!" },
    [366152338] = { ["english"] = { [1] = "Bad, <target>. <target>, bad!" }, ["npcs"] = { [1] = "A-Me 01" }, ["priority"] = 1, ["text"] = "Погано, {ціль}. {Ціль}, погано!#Bad, <target>." },
    [3661762526] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Brains..." }, ["npcs"] = { [1] = "Cursed Marine" }, ["priority"] = 1, ["text"] = "Мізки..." }, [2] = { ["english"] = { [1] = "Brains..." }, ["npcs"] = { [1] = "Cursed Sailor" }, ["priority"] = 1, ["text"] = "Мізки..." } }, ["english"] = { [1] = "Brains..." }, ["npcs"] = { [1] = "Captain Halyndor" }, ["priority"] = 1, ["text"] = "Мізки..." },
    [3661916867] = { ["english"] = { [1] = "It's all their fault, stupid Alliance army. Just had to build their towers right behind my farm." }, ["npcs"] = { [1] = "Topper McNabb" }, ["priority"] = 3, ["text"] = "Це все через них, через ту кляту армію Альянсу. Треба ж було їм збудувати свої вежі просто за моєю фермою." },
    [3662953976] = { ["english"] = { [1] = "Please do as I instruct you, <name>." }, ["npcs"] = { [1] = "Celebras the Redeemed" }, ["priority"] = 1, ["text"] = "Будь ласка, роби так, як я тобі скажу, {ім'я:к}.#you, <name>." },
    [366427846] = { ["english"] = { [1] = "You'll never leave this place alive." }, ["npcs"] = { [1] = "Amnennar the Coldbringer" }, ["priority"] = 1, ["text"] = "Вам не вийти звідси живими." },
    [3673265460] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Let's not even begin comparing battle scars, my friend." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Давай навіть не починати мірятись шрамами, друже." } }, ["english"] = { [1] = "Let's not even begin comparing battle scars, my friend." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Давай навіть не починати мірятись шрамами, друже." },
    [3674435145] = { ["english"] = { [1] = "%s goes into a rage after seeing his raptor fall in battle!" }, ["npcs"] = { [1] = "Bloodlord Mandokir" }, ["priority"] = 1, ["text"] = "%s впадає в лють, коли бачить, як його раптор гине в бою!" },
    [367722508] = { ["english"] = { [1] = "The troggs...they never stop coming.  Die trogg!  Die!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Троги... вони все лізуть й лізуть. Здохни, тварюко! Здохни!" },
    [3678497653] = { ["english"] = { [1] = "%s's will falters." }, ["npcs"] = { [1] = "Emberstrife" }, ["priority"] = 1, ["text"] = "Воля %sа слабшає." },
    [3688572337] = { ["english"] = { [1] = "I'll never fall for that, fool! If you want a battle, it will be on my terms and in my lair." }, ["npcs"] = { [1] = "Captain Galvangar" }, ["priority"] = 1, ["text"] = "Я на це не поведуся, дурні! Якщо хочете битви, то вона буде на моїх умовах і в моїй твердині!" },
    [3697712670] = { ["english"] = { [1] = "Mister body guard, are you going to earn your money or what?" }, ["npcs"] = { [1] = "Cork Gizelton" }, ["priority"] = 1, ["text"] = "То що, \"охоронцю\", ти збираєшся відпрацьовувати свої гроші чи як?" },
    [3698504886] = { ["english"] = { [1] = "Is someone there? Tirion my old friend, is that you? Have you come to save us?" }, ["npcs"] = { [1] = "Artist Renfray" }, ["priority"] = 1, ["text"] = "Тут хтось є? Тіріоне, мій старий друже, це ти? Ти прийшов врятувати нас?" },
    [3703752227] = { ["english"] = { [1] = "Is that the best you can do?  Do you really expect that you could defeat someone as awe inspiring as me?" }, ["npcs"] = { [1] = "Emperor Dagran Thaurissan" }, ["priority"] = 1, ["text"] = "Це все, що ви можете? Ви справді думаєте, що зможете здолати когось такого величного, як я?" },
    [3704651144] = { ["english"] = { [1] = "%s looks from side to side..." }, ["npcs"] = { [1] = "Crank Fizzlebub" }, ["priority"] = 1, ["text"] = "%s озирається навсібіч..." },
    [3704999839] = { ["english"] = { [1] = "You be dead soon!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ти скоро здохнеш!" },
    [370788064] = { ["english"] = { [1] = "That wasn't very helpful. Let me check the other one." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Це не дуже допомогло. Доведеться проглянути інший." },
    [371055456] = { ["english"] = { [1] = "Thank you! Thank you, <priest/priestess>. Now I can take on those gnolls with your power to back me!" }, ["npcs"] = { [1] = "Deathguard Kel" }, ["priority"] = 1, ["text"] = "Дякую! Щиро дякую, {стать:жерцю:жрице}. Завдяки тобі я знову зможу битись з гнолами!" },
    [3720166172] = { ["english"] = { [1] = "Alarm-a-bomb unit 2600 has failed. Self-destruct override [ACTIVE]. Cooldown [ACTIVE]." }, ["npcs"] = { [1] = "Alarm-a-bomb 2600" }, ["priority"] = 1, ["text"] = "Тривого-бомба 2600 зазнала збою. Скасування самознищення [АКТИВНО]. Охолодження [АКТИВНО]." },
    [3720565237] = { ["english"] = { [1] = "You cannot hide from us, little paladin!" }, ["npcs"] = { [1] = "Aligar the Tormentor" }, ["priority"] = 1, ["text"] = "Ти не сховаєшся від нас, нікчемний паладине!" },
    [3720672849] = { ["english"] = { [1] = "These orders must get to High General Abbendis!" }, ["npcs"] = { [1] = "Crimson Courier" }, ["priority"] = 1, ["text"] = "Ці накази мають дійти до верховного генерала Аббендіс!" },
    [3726974953] = { ["english"] = { [1] = "It seems you'll need another lesson, mortals!" }, ["npcs"] = { [1] = "Onyxia" }, ["priority"] = 1, ["text"] = "Схоже, вас доведеться провчити ще раз, смертні!" },
    [3729104260] = { ["english"] = { [1] = "That was a nice shot... but not perfect. Maybe a bit more to the left." }, ["npcs"] = { [1] = "Guard Lasiter" }, ["priority"] = 1, ["text"] = "Це був гарний постріл... але не ідеальний. Можливо, треба цілитись трохи лівіше." },
    [3732036582] = { ["english"] = { [1] = "Lysta, summon forth... the abomination!" }, ["npcs"] = { [1] = "Brother Malach" }, ["priority"] = 1, ["text"] = "Лайсто, виклич... потвору!" },
    [3733058985] = { ["english"] = { [1] = "Slay them in the master's name!" }, ["npcs"] = { [1] = "Grand Widow Faerlina" }, ["priority"] = 1, ["text"] = "Вбийте їх в ім'я повелителя!" },
    [3738709208] = { ["english"] = { [1] = "Blast those stupid centaurs! Sigh - well, it seems you kept your bargain. Up the road you shall find Smeed Scrabblescrew, he has your money." }, ["npcs"] = { [1] = "Cork Gizelton" }, ["priority"] = 1, ["text"] = "До біса цих тупих кентаврів! Фух... Що ж, здається, ти {стать:дотримався:дотрималася} своєї угоди. Далі по дорозі ти знайдеш Сміда Гвинтодряпа — у нього твої гроші." },
    [3743883684] = { ["english"] = { [1] = "\"Magic Maladies\", no. \"Magic Matricies\", no. Ahh here we go \"Magic Mysteries\"." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "\"Магічні хвороби\", ні. \"Магічні матриці\", ні. А, ось воно — \"Магічні таємниці\"." },
    [3754129807] = { ["english"] = { [1] = "You have fought hard to invade the realm of the harvester." }, ["npcs"] = { [1] = "Gothik the Harvester" }, ["priority"] = 1, ["text"] = "Ви завзято билися, щоб вдертися в царину женця." },
    [3754424600] = { ["english"] = { [1] = "Arrrgh!" }, ["npcs"] = { [1] = "Deathstalker Vincent" }, ["priority"] = 1, ["text"] = "Арррґх!" },
    [3757920492] = { ["english"] = { [1] = "That should do the trick." }, ["npcs"] = { [1] = "Razzle Sprysprocket" }, ["priority"] = 1, ["text"] = "Це має спрацювати." },
    [3761083879] = { ["english"] = { [1] = "Follow me, <name>. I'll take you to the Defias hideout. But you better protect me or I am as good as dead." }, ["npcs"] = { [1] = "The Defias Traitor" }, ["priority"] = 3, ["text"] = "Іди за мною, {ім'я:к}. Я відведу тебе до схованки Непокірних. Але краще захищай мене, бо інакше мені кінець." },
    [3766983620] = { ["english"] = { [1] = "Let it not trouble your heart, beloved. You have freed me from slavery, and for that I love you all the more." }, ["npcs"] = { [1] = "Anaya" }, ["priority"] = 1, ["text"] = "Нехай це не мучить тебе, любий. Ти звільнив мене від цих кайданів, і за це я кохаю тебе ще сильніше." },
    [3767616289] = { ["english"] = { [1] = "%s nods knowingly." }, ["npcs"] = { [1] = "Arygos" }, ["priority"] = 1, ["text"] = "%s киває." },
    [3767761532] = { ["english"] = { [1] = "You will pay for what you've done to Trey!" }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Ти заплатиш за те, що сталось з Треєм!" },
    [3768695599] = { ["english"] = { [1] = "Aku'mai demands more sacrifices, now you must die!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Аку'май вимагає нових жертв, ти маєш померти!" },
    [3770005022] = { ["english"] = { [1] = "That's about the gist of it. Once you've gained your boon from resting near the fire, speak with me again." }, ["npcs"] = { [1] = "Raan Wildwind" }, ["priority"] = 3, ["text"] = "Ось, власне, і вся суть. Коли отримаєш своє благословення від відпочинку біля вогню, поговори зі мною знову." },
    [377450141] = { ["english"] = { [1] = "Hah!  Eternal undeath to the cursed Agamands!" }, ["npcs"] = { [1] = "Coleman Farthing" }, ["priority"] = 1, ["text"] = "Ха! Нехай кляті Аґаманди ніколи не знайдуть спокою в смерті!" },
    [3776700707] = { ["english"] = { [1] = "I fear something dark is coming." }, ["npcs"] = { [1] = "Hogan Ference" }, ["priority"] = 3, ["text"] = "Боюся, насувається щось лихе." },
    [3779206450] = { ["english"] = { [1] = "Thank you, Mrs. Chambers." }, ["npcs"] = { [1] = "Father Inigo Montoy" }, ["priority"] = 1, ["text"] = "Дякую, пані Чамберс." },
    [3782463508] = { ["english"] = { [1] = "Perhaps a bit more grease will do the trick." }, ["npcs"] = { [1] = "Ozzie Togglevolt" }, ["priority"] = 1, ["text"] = "Може, ще трохи мастила — і все запрацює." },
    [3785003013] = { ["english"] = { [1] = "Get a rope!" }, ["npcs"] = { [1] = "Cenarion Hold Infantry" }, ["priority"] = 1, ["text"] = "Несіть мотузку!" },
    [3787110592] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "KILL!" }, ["npcs"] = { [1] = "Number Two" }, ["priority"] = 1, ["text"] = "ВБИТИ!" } }, ["english"] = { [1] = "Kill!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Вбивати!" },
    [3788760361] = { ["english"] = { [1] = "The heathens will be forced to react. Orcs, bull-men..." }, ["npcs"] = { [1] = "Scarlet Commander Marjhan" }, ["priority"] = 1, ["text"] = "Невірні не зможуть цього ігнорувати. Орки, биколюди..." },
    [3789840477] = { ["english"] = { [1] = "Attack!!" }, ["npcs"] = { [1] = "Avarus Kharag" }, ["priority"] = 1, ["text"] = "В атаку!!" },
    [3790904109] = { ["english"] = { [1] = "Thanks, Charys. C'mon Paige, sweetie." }, ["npcs"] = { [1] = "Karlee Chaddis" }, ["priority"] = 1, ["text"] = "Дякую, Черіс. Пейдж, люба, ходімо." },
    [3791180207] = { ["english"] = { [1] = "Ooo, so strong!  Happy Hallow's End, <name>!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ого, яка сила! Щасливого Повечір'я святих, {ім'я:к}!#Hallow's End, <name>!" },
    [3795077838] = { ["english"] = { [1] = "If the Captain finds out, it'll be the end of me." }, ["npcs"] = { [1] = "Warden Thelwater" }, ["priority"] = 3, ["text"] = "Якщо капітан дізнається, мені кінець." },
    [3797524004] = { ["english"] = { [1] = "What's that smell?" }, ["npcs"] = { [1] = "Cyriden Farseeker" }, ["priority"] = 1, ["text"] = "Що це за запах?" },
    [3798513322] = { ["english"] = { [1] = "Keever is unhappy with this. Perhaps if Keever were to try a larger dose, that may fix this dilemma." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "Ківер незадоволений цим. Можливо, якщо Ківер спробує більшу дозу, це все вирішить." },
    [3799324508] = { ["english"] = { [1] = "Sadly, even this must be cut short... The ties that bind me to this world weaken, and pull me away..." }, ["npcs"] = { [1] = "Anaya" }, ["priority"] = 1, ["text"] = "На жаль, навіть цій зустрічі не судилось тривати довго... Зв'язок, що тримає мене у цьому світі, слабне... Я йду назавжди..." },
    [3800660740] = { ["english"] = { [1] = "All right, stay close.  These fiends will jump right out of the shadows at you if you let your guard down." }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Гаразд, тримайтесь поруч. Ці почвари можуть вискочити прямо з тіней, якщо втратити пильність." },
    [3800785804] = { ["english"] = { [1] = "Be bathed in the power of the Warchief! Drink in his might! Battle for the glory of the Horde!" }, ["npcs"] = { [1] = "Herald of Thrall" }, ["priority"] = 1, ["text"] = "Купайтеся в силі вождя! Сповнюйтесь його могутністю! Бийтеся за славу Орди!" },
    [3806702915] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "%s barely grunts." }, ["npcs"] = { [1] = "Anvilrage Guardsman" }, ["priority"] = 1, ["text"] = "%s ледь чутно стогне." }, [2] = { ["english"] = { [1] = "%s barely grunts." }, ["npcs"] = { [1] = "Anvilrage Warden" }, ["priority"] = 1, ["text"] = "%s ледь чутно стогне." } }, ["english"] = { [1] = "%s barely grunts." }, ["npcs"] = { [1] = "Anvilrage Footman" }, ["priority"] = 1, ["text"] = "%s ледь чутно стогне." },
    [3810618032] = { ["english"] = { [1] = "%s start pushing each other back and forth." }, ["npcs"] = { [1] = "Blackhand Thug" }, ["priority"] = 1, ["text"] = "%s починає штовхатись." },
    [3811362668] = { ["english"] = { [1] = "Patchwerk want to play!" }, ["npcs"] = { [1] = "Patchwerk" }, ["priority"] = 1, ["text"] = "Клаптик хоче грати!" },
    [3811835150] = { ["english"] = { [1] = "Here we have the Cathedral of Light, the center of spiritual enlightenment here in Stormwind." }, ["npcs"] = { [1] = "Miss Danna" }, ["priority"] = 3, ["text"] = "Перед нами Собор Сяйва — осередок духовного просвітлення тут, у Штормовії." },
    [3823217388] = { ["english"] = { [1] = "And then the rabbit just bit his head off... I swear." }, ["npcs"] = { [1] = "Justin" }, ["priority"] = 1, ["text"] = "А потім кролик просто відкусив йому голову... Я клянусь." },
    [3824045649] = { ["english"] = { [1] = "Onward!" }, ["npcs"] = { [1] = "Arch Druid Renferal" }, ["priority"] = 1, ["text"] = "Вперед!" },
    [3828470716] = { ["english"] = { [1] = "Look! Over there at the tunnel wall!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Погляньте! Там, у стіні тунелю!" },
    [3828955266] = { ["english"] = { [1] = "The Scarlet Crusade shall smite the wicked and drive evil from these lands!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Багряний Похід покарає нечестивих і вижене зло з цих земель!" },
    [3835335579] = { ["english"] = { [1] = "DIE, DEMON DOGS!" }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "ЗДОХНІТЬ, КЛЯТІ ДЕМОНИ!" },
    [3836475472] = { ["english"] = { [1] = "End our suffering!" }, ["npcs"] = { [1] = "Darrowshire Poltergeist" }, ["priority"] = 1, ["text"] = "Поклади край нашим стражданням!" },
    [3836565635] = { ["english"] = { [1] = "This has gone too far.  How dare the Scourge attack Undercity!  Destroy it before more come!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Це зайшло надто далеко. Як сміє Скара нападати на Підмістя? Знищте їх, поки не прийшло ще більше!" },
    [3849640231] = { ["english"] = { [1] = "Zunguzung!  I'm finished!" }, ["npcs"] = { [1] = "Tormus Deepforge" }, ["priority"] = 3, ["text"] = "Зунґузунґе!  Я закінчив!" },
    [3852998080] = { ["english"] = { [1] = "You kept me in that cell for too long, monster!" }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Ви занадто довго тримали мене в тій клітці, чудовисько!" },
    [3853568339] = { ["english"] = { [1] = "Let's find out the whole story.  That's going to take some magic..." }, ["npcs"] = { [1] = "Chromie" }, ["priority"] = 1, ["text"] = "Давай дізнаємося всю історію. Нам потрібна лиш дрібка магії..." },
    [3856803688] = { ["english"] = { [1] = "%s whimpers." }, ["npcs"] = { [1] = "Awbee" }, ["priority"] = 1, ["text"] = "%s скиглить." },
    [3865472001] = { ["english"] = { [1] = "Argh! You're hopeless!" }, ["npcs"] = { [1] = "Pilot Bellowfiz" }, ["priority"] = 3, ["text"] = "Аргх! З тобою безнадійно!" },
    [3871036262] = { ["english"] = { [1] = "I was thinking the same thing." }, ["npcs"] = { [1] = "Razzle Sprysprocket" }, ["priority"] = 1, ["text"] = "Я подумав про те саме." },
    [3873576745] = { ["english"] = { [1] = "Every trade has something they can contribute to your camp, even fishermen!" }, ["npcs"] = { [1] = "Raan Wildwind" }, ["priority"] = 3, ["text"] = "Кожне ремесло може щось додати до твого табору — навіть рибалки!" },
    [3879367690] = { ["english"] = { [1] = "It's a mystery of the past indeed! But a key to our future!" }, ["npcs"] = { [1] = "Archaeologist Flagongut" }, ["priority"] = 1, ["text"] = "Це справжня загадка минулого! Але це також ключ до нашого майбутнього!" },
    [3882127901] = { ["english"] = { [1] = "%s belches out a disgusting Bile Slime!" }, ["npcs"] = { [1] = "Bile Spewer" }, ["priority"] = 1, ["text"] = "%s виригує огидний жовчний слиз!" },
    [3883006166] = { ["english"] = { [1] = "I. . .I. . .don't. . .feel. . .right. . ." }, ["npcs"] = { [1] = "Captured Scarlet Zealot" }, ["priority"] = 1, ["text"] = "Щ... Щось... мені... не... добре..." },
    [3886861748] = { ["english"] = { [1] = "Be careful, <name>.  Those wolves like to hide among the trees." }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "Обережно, {ім'я:к}. Вовки люблять ховатись серед дерев.#careful, <name>." },
    [3891630814] = { ["english"] = { [1] = "Follow me, Cataloren. I'll take you to the Defias hideout. But you better protect me or I am as good as dead." }, ["npcs"] = { [1] = "The Defias Traitor" }, ["priority"] = 3, ["text"] = "Іди за мною, Каталорене. Я відведу тебе до схованки Непокірних. Але краще захищай мене, бо інакше мені кінець." },
    [3894432653] = { ["english"] = { [1] = "Etam!  I'm finished!" }, ["npcs"] = { [1] = "Tormus Deepforge" }, ["priority"] = 3, ["text"] = "Етаме!  Я закінчив!" },
    [3898731091] = { ["english"] = { [1] = "Hey there, Belm!  Give me a mug of Thunder Ale, and one for my good friend <name>." }, ["npcs"] = { [1] = "Jarven Thunderbrew" }, ["priority"] = 3, ["text"] = "Гей, Белме!  Налий мені кухоль Громового елю, і ще один — для мого доброго друга {ім'я:р}." },
    [3898949188] = { ["english"] = { [1] = "That's right friend!  The Darkmoon Faire is going to be right here.  Just as soon as I unload those huge wagons, put up all the tents, erect the zoo and pour the drinks.  Make sure you come back!" }, ["npcs"] = { [1] = "Darkmoon Faire Carnie" }, ["priority"] = 1, ["text"] = "Це правда, друзі! Ярмарок Темного місяця відбудеться саме тут. Щойно я розвантажу ці величезні вози, розставлю всі намети, зведу загін і розіллю напої. Обов'язково приходьте!" },
    [3899532066] = { ["english"] = { [1] = "They must have had someone helping them." }, ["npcs"] = { [1] = "Warden Thelwater" }, ["priority"] = 3, ["text"] = "Їм напевно хтось допомагав." },
    [3900500865] = { ["english"] = { [1] = "I have a few notes from the job back at my place. I'll get them and then meet you back in the inn." }, ["npcs"] = { [1] = "Tapoke \"Slim\" Jahn" }, ["priority"] = 1, ["text"] = "У мене з тієї справи залишилось кілька записок. Я їх заберу і ми зустрінемось в таверні." },
    [39007914] = { ["english"] = { [1] = "I sense the taint of corruption upon this <target>. Help me destroy it!" }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Я відчуваю, як {ціль} страждає від скверни. Ми маємо припинити ці муки!#upon this <target>." },
    [3903649064] = { ["english"] = { [1] = "You have challenged the Seven, and now you will die!" }, ["npcs"] = { [1] = "Doom'rel" }, ["priority"] = 1, ["text"] = "Ви кинули виклик Сімом, і тепер ви помрете!" },
    [3905580468] = { ["english"] = { [1] = "Incoming <target> - look sharp, friends!" }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Сюди йде {ціль} — будьте напоготові, друзі!#Incoming <target> - look" },
    [390596033] = { ["english"] = { [1] = "Corbett, dear.  Harlan needs a load of knitted shirts and pants as soon as we can manage." }, ["npcs"] = { [1] = "Rema Schneider" }, ["priority"] = 1, ["text"] = "Корбет, любий. Гарлану потрібно багато в'язаних сорочок і штанів, і якомога швидше." },
    [3914840964] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Course I remember that night. Two inches to the left and you'd be drinking with that elf, Morris. That was my best shirt, too." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Звісно, я пам'ятаю ту ніч. Кілька перстів лівіше, і ти б зараз пиячив з тим ельфом, Моррісом. Ех, це була моя найкраща сорочка..." } }, ["english"] = { [1] = "Course I remember that night. Two inches to the left and you'd be drinking with that elf, Morris. That was my best shirt, too." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Звісно, я пам'ятаю ту ніч. Кілька перстів лівіше, і ти б зараз пиячив з тим ельфом, Моррісом. Ех, це була моя найкраща сорочка..." },
    [3919605005] = { ["english"] = { [1] = "Fools! Our cause is righteous!" }, ["npcs"] = { [1] = "Edwin VanCleef" }, ["priority"] = 1, ["text"] = "Дурні! Ми прагнемо справедливості!" },
    [3922600971] = { ["english"] = { [1] = "Argh!" }, ["npcs"] = { [1] = "Aurius" }, ["priority"] = 1, ["text"] = "Агх!" },
    [3924357779] = { ["english"] = { [1] = "Ok, enough!  I give up!" }, ["npcs"] = { [1] = "Bartleby" }, ["priority"] = 1, ["text"] = "Гаразд, досить! Я здаюся!" },
    [3938682826] = { ["english"] = { [1] = "Enemy ho! Fire!" }, ["npcs"] = { [1] = "Cannoneer Smythe" }, ["priority"] = 1, ["text"] = "Ворог попереду! Вогонь!" },
    [3939316833] = { ["english"] = { [1] = "Lay down your weapons, your feuds have no place here!" }, ["npcs"] = { [1] = "Argent Sentry" }, ["priority"] = 1, ["text"] = "Складіть зброю, вашим чварам тут не місце!" },
    [3939452909] = { ["english"] = { [1] = "가학 ran the Gauntlet!  Three cheers for 가학!" }, ["npcs"] = { [1] = "Yorus Barleybrew" }, ["priority"] = 3, ["text"] = "가학 пройшов Випробування!  Тричі слава 가학!" },
    [3940653207] = { ["english"] = { [1] = "The Warchief shall make quick work of you, mortals. Prepare yourselves!" }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Воєвождь швидко впорається з вами, смертні. Готуйтесь!" },
    [3941481951] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Stonesplinter Tribe shall see to your doom!" }, ["npcs"] = { [1] = "Grawmug" }, ["priority"] = 1, ["text"] = "Плем'я Каменедробів принесе вам загибель!" }, [2] = { ["english"] = { [1] = "The Stonesplinter Tribe shall see to your doom!" }, ["npcs"] = { [1] = "Magosh" }, ["priority"] = 1, ["text"] = "Плем'я Каменедробів знищить вас!" } }, ["english"] = { [1] = "The Stonesplinter Tribe shall see to your doom!" }, ["npcs"] = { [1] = "Boss Galgosh" }, ["priority"] = 1, ["text"] = "Плем'я Каменедробів знищить вас!" },
    [3943454163] = { ["english"] = { [1] = "I think... I think it's working!" }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "Здається... Здається, воно працює!" },
    [3946184581] = { ["english"] = { [1] = "Did you see that?  There's a Scourge over there!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ви це бачили? Там Скара!" },
    [3950515609] = { ["english"] = { [1] = "The Sandfury reign supreme!" }, ["npcs"] = { [1] = "Chief Ukorz Sandscalp" }, ["priority"] = 1, ["text"] = "Піщанолютих не спинити!" },
    [3953306249] = { ["english"] = { [1] = "No! My friend... what's happened? This is all my fault..." }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Ні! Друже мій... що сталося? Це все моя провина..." },
    [3955580999] = { ["english"] = { [1] = "The Blood God, the Soulflayer, has been defeated!  We are imperiled no longer!" }, ["npcs"] = { [1] = "Zandalarian Emissary" }, ["priority"] = 1, ["text"] = "Кривавого Бога, Здирача душ, знищено! Він нам більше не загрожуватиме!" },
    [3955704566] = { ["english"] = { [1] = "Don't make me angry! You wouldn't like me when I'm angry!" }, ["npcs"] = { [1] = "Bloodlord Mandokir" }, ["priority"] = 1, ["text"] = "Не зли мене! Тобі не сподобається мій гнів!" },
    [3957664507] = { ["english"] = { [1] = "We will never allow it... We have banished him from our world before and we will banish him again." }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "Ми цього не допустимо... Ми вже одного разу вигнали його з нашого світу, і ми зробимо це знову." },
    [3958545699] = { ["english"] = { [1] = "We made it!  Thanks, <name>.  I couldn't have gotten here without you." }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "Нам вдалося! Дякую, {ім'я:к}. Я б не дістався сюди без тебе.#Thanks, <name>." },
    [396675881] = { ["english"] = { [1] = "%s collapses but the broken body rises again!" }, ["npcs"] = { [1] = "Ravaged Cadaver" }, ["priority"] = 1, ["text"] = "%s падає, проте його понівечене тіло знову підіймається!" },
    [3969549797] = { ["english"] = { [1] = "Lunch has arrived, my beautiful children. Tear them to pieces!" }, ["npcs"] = { [1] = "Antu'sul" }, ["priority"] = 1, ["text"] = "Час їсти, мої любі діти. Порвіть їх на шматки!" },
    [3974062951] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Honor your heroes! On this day, they have dealt a great blow against one of our most hated enemies! The false Warchief, Rend Blackhand, has fallen!" }, ["npcs"] = { [1] = "Thrall" }, ["priority"] = 1, ["text"] = "Шануймо наших героїв! Цього дня вони завдали нищівного удару одному з наших найненависніших ворогів! Самозваний вождь, Ренд Чорнорук, нарешті мертвий!" } }, ["english"] = { [1] = "Honor your heroes! On this day, they have dealt a great blow against one of our most hated enemies! The false Warchief, Rend Blackhand, has fallen!" }, ["npcs"] = { [1] = "Herald of Thrall" }, ["priority"] = 1, ["text"] = "Шануймо наших героїв! Цього дня вони завдали нищівного удару одному з наших найненависніших ворогів! Самозваний вождь, Ренд Чорнорук, нарешті мертвий!" },
    [3978017356] = { ["english"] = { [1] = "Oh c'mon, that's not true." }, ["npcs"] = { [1] = "Brandon" }, ["priority"] = 1, ["text"] = "Ой, та ну. Це не правда." },
    [3979781423] = { ["english"] = { [1] = "You're making that up." }, ["npcs"] = { [1] = "Adam" }, ["priority"] = 1, ["text"] = "Ти все це вигадав." },
    [3983113829] = { ["english"] = { [1] = "Scourge spotted nearby!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Неподалік бачили Скару!" },
    [3983152201] = { ["english"] = { [1] = "I know how to speak kitty, and Effsee said thank you." }, ["npcs"] = { [1] = "Hilary" }, ["priority"] = 3, ["text"] = "Я вмію говорити по-котячому, і Еффсі сказала «дякую»." },
    [3983722682] = { ["english"] = { [1] = "%s lets out a shriek, calling for help!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s верещить, кличучи на допомогу!" },
    [3987299315] = { ["english"] = { [1] = "The arcane is an affront to the wind spirits!" }, ["npcs"] = { [1] = "Windshaper Novice Seer" }, ["priority"] = 3, ["text"] = "Аркана — образа для духів вітру!" },
    [3989345374] = { ["english"] = { [1] = "Stormwind's desertion shall not be forgiven by the people of Westfall." }, ["npcs"] = { [1] = "Captain Danuvin" }, ["priority"] = 1, ["text"] = "Мешканці Західного краю не пробачать зраду Штормовію." },
    [3990161448] = { ["english"] = { [1] = "Har! You scared I'll hurt your little dainty racer?" }, ["npcs"] = { [1] = "Pilot Stonegear" }, ["priority"] = 3, ["text"] = "Ха! Боїшся, що я пошкоджу твою маленьку тендітну гоночну цяцьку?" },
    [3990222854] = { ["english"] = { [1] = "Closer now. Tasty morsels. I've been too long without food, without blood to drink." }, ["npcs"] = { [1] = "Anub'Rekhan" }, ["priority"] = 1, ["text"] = "Ближче. Ближче! Я надто довго не їв... надто довго не пив кров." },
    [3994679415] = { ["english"] = { [1] = "Who dares awaken Aquementas?" }, ["npcs"] = { [1] = "Aquementas" }, ["priority"] = 1, ["text"] = "Хто сміє тривожити Акваментаса?" },
    [3997228685] = { ["english"] = { [1] = "Three minutes left -- I can feel the energy starting to build!  Keep up the solid defense!" }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Залишилося три хвилини — я відчуваю, як енергія починає накопичуватися! Продовжуйте тримати оборону!" },
    [3998090577] = { ["english"] = { [1] = "%s kneels down to pick up the fragments of the shattered scepter." }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "%s схиляється над уламками розбитого скіпетра, щоб зібрати їх." },
    [3999113537] = { ["english"] = { [1] = "It is done, dragon. Lead the way." }, ["npcs"] = { [1] = "Fandral Staghelm" }, ["priority"] = 1, ["text"] = "Я готовий, драконе. Веди нас." },
    [3999130851] = { ["english"] = { [1] = "I have failed once more..." }, ["npcs"] = { [1] = "Eris Havenfire" }, ["priority"] = 1, ["text"] = "Я знову всіх підвела..." },
    [4000157120] = { ["english"] = { [1] = "Hehehe! Things go boom!" }, ["npcs"] = { [1] = "Zamek" }, ["priority"] = 1, ["text"] = "Хехехе! Зараз буде БУМ!" },
    [4001677352] = { ["english"] = { [1] = "Very interesting!" }, ["npcs"] = { [1] = "Doc Mixilpixil" }, ["priority"] = 1, ["text"] = "Дуже цікаво!" },
    [4002245215] = { ["english"] = { [1] = "%s looks at you expectantly." }, ["npcs"] = { [1] = "Chicken" }, ["priority"] = 1, ["text"] = "%s очікує від вас чогось смачного." },
    [4004696500] = { ["english"] = { [1] = "Taste your world's corruption!" }, ["npcs"] = { [1] = "Emeriss" }, ["priority"] = 1, ["text"] = "Відчуйте псування вашого світу!" },
    [4004964776] = { ["english"] = { [1] = "I'm coming Cyriden!" }, ["npcs"] = { [1] = "Relathor Moonsong" }, ["priority"] = 1, ["text"] = "Я йду, Циріден!" },
    [4010683188] = { ["english"] = { [1] = "The Brotherhood shall prevail!" }, ["npcs"] = { [1] = "Edwin VanCleef" }, ["priority"] = 1, ["text"] = "Братство здобуде перемогу!" },
    [4023408270] = { ["english"] = { [1] = "Is it? Call out to them, Servitor." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Невже? Звернись до них, Слуго." },
    [402604530] = { ["english"] = { [1] = "Won't be long now until the Darkmoon Faire opens.  Come back later and check to see if we're done." }, ["npcs"] = { [1] = "Darkmoon Faire Carnie" }, ["priority"] = 1, ["text"] = "Ярмарок Темного місяця почнеться зовсім скоро. Повертайтесь пізніше і приєднуйтесь до свята!" },
    [4028180226] = { ["english"] = { [1] = "Ahh, there we go. Now, Keever must try this vial and see if it works." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "Ага, ось так. Тепер Ківер має спробувати цю формулу і перевірити, чи спрацює вона." },
    [402894991] = { ["english"] = { [1] = "%s cries." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s плаче." },
    [4033759137] = { ["english"] = { [1] = "Ah, a chance to use this freshly sharpened blade." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "О, а я саме лезо наточив." },
    [4035944105] = { ["english"] = { [1] = "So sorry to leave a customer but we have places to go and people to swindle. We will be back sometime later today. Good-bye!" }, ["npcs"] = { [1] = "Cork Gizelton" }, ["priority"] = 1, ["text"] = "Завжди шкода покидати клієнтів, але нам ще є куди йти, і є кого обдурювати. Ми ще повернемося. До зустрічі!" },
    [4041361574] = { ["english"] = { [1] = "You have not seen the last of me fools!  All shall be consumed in the end!" }, ["npcs"] = { [1] = "Baron Charr" }, ["priority"] = 1, ["text"] = "Це ще не кінець, жалюгідні дурні! Вас всіх врешті-решт пожере полум'я!" },
    [4049035161] = { ["english"] = { [1] = "Doesn't anybody KNOCK anymore???!" }, ["npcs"] = { [1] = "Crest Killer" }, ["priority"] = 1, ["text"] = "Невже ніхто більше НЕ СТУКАЄ У ДВЕРІ??!!" },
    [4052218981] = { ["english"] = { [1] = "Farewell to you, and may Elune be with you always." }, ["npcs"] = { [1] = "Sentinel Shaya" }, ["priority"] = 1, ["text"] = "Бувай, і нехай Елуна береже тебе." },
    [4053383199] = { ["english"] = { [1] = "Where are your manners, brother. Let us properly welcome our guests." }, ["npcs"] = { [1] = "Emperor Vek'nilash" }, ["priority"] = 1, ["text"] = "Де твої манери, брате? Привітаймо наших гостей як належить." },
    [4061880385] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Death to the Warden's men!" }, ["npcs"] = { [1] = "Bruegal Ironknuckle" }, ["priority"] = 1, ["text"] = "Смерть людям наглядача!" }, [2] = { ["english"] = { [1] = "Death to the Warden's men!" }, ["npcs"] = { [1] = "Defias Rioter" }, ["priority"] = 1, ["text"] = "Смерть людям наглядача!" } }, ["english"] = { [1] = "Death to the Warden's men!" }, ["npcs"] = { [1] = "Bazil Thredd" }, ["priority"] = 1, ["text"] = "Смерть людям наглядача!" },
    [4064421613] = { ["english"] = { [1] = "Never better, Relathor. Come, let us return inside." }, ["npcs"] = { [1] = "Cyriden Farseeker" }, ["priority"] = 1, ["text"] = "Я в порядку, Релаторе. Ходімо, повернімось всередину." },
    [4064691744] = { ["english"] = { [1] = "And that's how Lothar killed thirty six orcs with his bare hands!" }, ["npcs"] = { [1] = "Justin" }, ["priority"] = 1, ["text"] = "І отак Лотар убив тридцять шість орків голіруч!" },
    [4068250590] = { ["english"] = { [1] = "They say he can turn into a raven sometimes." }, ["npcs"] = { [1] = "Justin" }, ["priority"] = 1, ["text"] = "Кажуть, що він може перетворюватись на ворона." },
    [4070425144] = { ["english"] = { [1] = "Eburi ash, <name>.  Ala mush ri ash." }, ["npcs"] = { [1] = "Barithras Moonshade" }, ["priority"] = 1, ["text"] = "Eburi ash, {ім'я:к}.  Ala mush ri ash.#Eburi ash, <name>." },
    [4071976289] = { ["english"] = { [1] = "I go now to summon the lord whose house this is. Should you seek an audience with him, your paltry lives will surely be forfeit! Nevertheless, seek out his lair, if you dare!" }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "А тепер я покличу володаря цієї обителі. Аудієнція з ним, безсумнівно, буде останньою у вашому житті! Що ж, ходіть до його лігва, якщо наважитеся!" },
    [4080648759] = { ["english"] = { [1] = "Be ready, <name>. I hear the council returning. Prepare to ambush!" }, ["npcs"] = { [1] = "Deathstalker Faerleia" }, ["priority"] = 1, ["text"] = "Приготуйся, {ім'я:к}. Я чую, як радники повертаються. Готуй засідку!#ready, <name>." },
    [4081589696] = { ["english"] = { [1] = "Thank you, all. I shall return again in about a week." }, ["npcs"] = { [1] = "Antonio Perelli" }, ["priority"] = 1, ["text"] = "Дякую вам усім. Побачимось приблизно за тиждень." },
    [4083092542] = { ["english"] = { [1] = "Fresh bread, baked this very morning." }, ["npcs"] = { [1] = "Myra Tyrngaarde" }, ["priority"] = 1, ["text"] = "Свіжий хліб, спечений цього ранку." },
    [4083741030] = { ["english"] = { [1] = "I've found that when I throw something into this water, it has improved incredibly when I retrieve it." }, ["npcs"] = { [1] = "Donova Snowden" }, ["priority"] = 1, ["text"] = "Я виявила, що якщо занурити щось у цю воду, його характеристики значно поліпшуються." },
    [4085477136] = { ["english"] = { [1] = "You will not defile these mysteries!" }, ["npcs"] = { [1] = "Arcanist Doan" }, ["priority"] = 1, ["text"] = "Ви не спаплюжите ці таємниці!" },
    [4088504696] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Did you hear something?" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Ви щось чули?" } }, ["english"] = { [1] = "Did you hear something?" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Ви щось чули?" },
    [4098823109] = { ["english"] = { [1] = "I pledge my love to you forever. Death cannot erase that, even as I am sure that you still remember your love for me." }, ["npcs"] = { [1] = "Annalise Lerent" }, ["priority"] = 1, ["text"] = "Я вічно кохатиму тебе. Смерть не може стерти це, і я знаю, що ти все ще пам'ятаєш про своє кохання до мене." },
    [4099759046] = { ["english"] = { [1] = "Ragnaros sees all, mortal." }, ["npcs"] = { [1] = "Dark Iron Steelshifter" }, ["priority"] = 1, ["text"] = "Раґнарос бачить усе, {стать:смертний:смертна}." },
    [4101012411] = { ["english"] = { [1] = "Don't forget the orphans of Stormwind!" }, ["npcs"] = { [1] = "John Turner" }, ["priority"] = 3, ["text"] = "Не забувайте про сиріт Штормовію!" },
    [4101778386] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You've interfered with our plans for the last time, foolish <class>!" }, ["npcs"] = { [1] = "Stormscale Toxicologist" }, ["priority"] = 1, ["text"] = "Ти востаннє втручаєшся в наші плани, {клас:к}!#foolish <class>!" } }, ["english"] = { [1] = "You've interfered with our plans for the last time, foolish <class>!" }, ["npcs"] = { [1] = "Burning Blade Toxicologist" }, ["priority"] = 1, ["text"] = "Ти востаннє втручаєшся в наші плани, {клас:к}!#foolish <class>!" },
    [4104421457] = { ["english"] = { [1] = "Just two minutes to go!  We're half way there, but don't let your guard down!" }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Залишилося лише дві хвилини! Ми на півдорозі, але не втрачайте пильність!" },
    [4107240208] = { ["english"] = { [1] = "%s pokes the small fuzzy squirrel with obvious disappointment." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "%s з очевидним розчаруванням штрикає пальцем маленьку пухнасту білку." },
    [411491298] = { ["english"] = { [1] = "Why do we always go the same way?" }, ["npcs"] = { [1] = "Gil" }, ["priority"] = 1, ["text"] = "Чому ми постійно ходимо тим самим шляхом?" },
    [411741774] = { ["english"] = { [1] = "Use the freezing breath, imbecile!" }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Скористайся морозним диханням, йолопе!" },
    [4119293147] = { ["english"] = { [1] = "Oh!!! Get that thing away from me!" }, ["npcs"] = { [1] = "Quixxil" }, ["priority"] = 1, ["text"] = "А-а-а!!! Забери від мене цю штуку!" },
    [4121097725] = { ["english"] = { [1] = "Defenders of Darrowshire!  Rally!  We must prevail!" }, ["npcs"] = { [1] = "Captain Redpath" }, ["priority"] = 1, ["text"] = "Захисники Дарроуширу! Зберіться! Ми повинні перемогти!" },
    [4124489015] = { ["english"] = { [1] = "OW! That's not right!" }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "Ой! Так не годиться!" },
    [4126068573] = { ["english"] = { [1] = "Eeck! Demons appear hungry for the kodos!" }, ["npcs"] = { [1] = "Rigger Gizelton" }, ["priority"] = 1, ["text"] = "Йоой! Демони хочуть зжерти кодо!" },
    [4130964830] = { ["english"] = { [1] = "Ah yes. I've heard all about those new flarged things. Armor was removed from the casing to decrease weight. Bargh! Nonsense!" }, ["npcs"] = { [1] = "Pilot Stonegear" }, ["priority"] = 3, ["text"] = "Ага, чув я все про ті нові фларґові штукенції. З корпусу, бач, броню зняли, щоб вагу зменшити. Бах! Нісенітниця!" },
    [4133367602] = { ["english"] = { [1] = "You cannot hide from me!" }, ["npcs"] = { [1] = "Grand Widow Faerlina" }, ["priority"] = 1, ["text"] = "Вам не сховатись від мене!" },
    [413461208] = { ["english"] = { [1] = "Before you depart, <class>, check in with Jamie Nore in the town hall. She may have a task for you." }, ["npcs"] = { [1] = "Deathguard Burgess" }, ["priority"] = 1, ["text"] = "Перш ніж підеш, {клас:к}, зайди в ратушу й поговори з Джеймі Нор. У неї може знайтись завдання для тебе.#depart, <class>," },
    [4139458695] = { ["english"] = { [1] = "Bah! By the time you got in range of old Trollplow you would be in reduced to rubble!" }, ["npcs"] = { [1] = "Pilot Stonegear" }, ["priority"] = 3, ["text"] = "Пхе! Поки ти дістанешся на відстань пострілу до старого Тролеплуга, від тебе вже самі уламки лишаться!" },
    [4141052431] = { ["english"] = { [1] = "FOOL! Do you purport to have even one-tenth of the power you held during the Uprising? The nations were united and still were nearly consumed by a shadow of Hakkar. You stand no chance." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "ДУРЕНЬ! Думаєш, у вас є хоча б десятина від тієї сили, яку ви мали під час Повстання? Племена були об'єднані, і їх все одно ледь не поглинула тінь Гаккара. У вас немає жодного шансу." },
    [4143383170] = { ["english"] = { [1] = "<name>, my wounds are grave.  Forgive my slow pace but my injuries won't allow me to walk any faster." }, ["npcs"] = { [1] = "Corporal Keeshan" }, ["priority"] = 1, ["text"] = "{Ім'я:к}, я серйозно поранений. Пробач мені за повільну ходу, але мої травми не дозволяють мені йти швидше.#<name>, my" },
    [4146108681] = { ["english"] = { [1] = "There is but one duty that remains..." }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "Залишилася лиш одна справа..." },
    [4151136740] = { ["english"] = { [1] = "Let's move forward!" }, ["npcs"] = { [1] = "Sergeant Bly" }, ["priority"] = 1, ["text"] = "Рухаймося вперед!" },
    [4154089189] = { ["english"] = { [1] = "Your fate is sealed!" }, ["npcs"] = { [1] = "Emperor Vek'nilash" }, ["priority"] = 1, ["text"] = "Вашу долю вирішено!" },
    [415426053] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "%s flaps its wings furiously!" }, ["npcs"] = { [1] = "Flamegor" }, ["priority"] = 1, ["text"] = "%s несамовито розмахує крилами!" } }, ["english"] = { [1] = "%s flaps its wings furiously!" }, ["npcs"] = { [1] = "Ebonroc" }, ["priority"] = 1, ["text"] = "%s несамовито розмахує крилами!" },
    [4155587916] = { ["english"] = { [1] = "The abomination has come! Forward!" }, ["npcs"] = { [1] = "Town Crier" }, ["priority"] = 1, ["text"] = "Потвора вже тут! В атаку!" },
    [4156714007] = { ["english"] = { [1] = "The fish is exquisite, Jessica." }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Ця риба неперевершена, Джесіко." },
    [4157303389] = { ["english"] = { [1] = "I will hurry back to Vahlarriel. Finish off those that you can--I should be fine on my own from here." }, ["npcs"] = { [1] = "Dalinda Malem" }, ["priority"] = 1, ["text"] = "Я повернусь до Валарріеля. Добий тих, кого зможеш — далі я сама впораюся." },
    [4157499221] = { ["english"] = { [1] = "Right away, sir." }, ["npcs"] = { [1] = "Adjutant Tesoran" }, ["priority"] = 1, ["text"] = "Слухаюсь, сер." },
    [4157528091] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Fresh meat!" }, ["npcs"] = { [1] = "Bruegal Ironknuckle" }, ["priority"] = 1, ["text"] = "Свіже м'ясо!" } }, ["english"] = { [1] = "Fresh meat!" }, ["npcs"] = { [1] = "Bazil Thredd" }, ["priority"] = 1, ["text"] = "Свіже м'ясо!" },
    [4160462004] = { ["english"] = { [1] = "Feel the power of the Brotherhood!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Відчуй силу Братства!" },
    [4160542264] = { ["english"] = { [1] = "Go on and have a seat near the fire and we can get started." }, ["npcs"] = { [1] = "Raan Wildwind" }, ["priority"] = 3, ["text"] = "Ну ж бо, сідай біля вогню, і почнемо." },
    [416058140] = { ["english"] = { [1] = "NEFARIAN IS SLAIN! People of Orgrimmar, bow down before the might of <name> and <his/her> allies for they have laid a blow against the Black Dragonflight that is sure to stir the Aspects from their malaise! This defeat shall surely be felt by the father of the Black Flight: Deathwing reels in pain and anguish this day!" }, ["npcs"] = { [1] = "High Overlord Saurfang" }, ["priority"] = 1, ["text"] = "НЕФАРІАН МЕРТВИЙ! Жителі Орґріммару, падіть ниць перед могутністю {ім'я:р} та {стать:його:її} союзників. Вони завдали чорним драконам потужного удару, здатного пробудити Аспекти від їх байдужості! Без сумніву, навіть батько чорних драконів, Смертекрил, відчуває цю втрату й здригається від болю та страждань!#might of <name> and#and <his/her> allies" },
    [4163977046] = { ["english"] = { [1] = "I dunno, Jill. If Klaven comes down while we're slacking, we may end up as one of those things!" }, ["npcs"] = { [1] = "Defias Tower Patroller" }, ["priority"] = 1, ["text"] = "Не знаю, Джил. Якщо Клейвен побачить, що ми байдикуємо, ми можемо стати одними з тих створінь!" },
    [4164088178] = { ["english"] = { [1] = "Elune be with us! Let's make haste from this evil fortress." }, ["npcs"] = { [1] = "Dalinda Malem" }, ["priority"] = 1, ["text"] = "Нехай береже нас Елуна! Забираймося з цього мерзенного місця." },
    [4172072511] = { ["english"] = { [1] = "Not quite so sure of yourself without the Purifier, hm?" }, ["npcs"] = { [1] = "Balizar the Umbrage" }, ["priority"] = 1, ["text"] = "А ви вже не такі впевнені без Очистителя, га?" },
    [4175832698] = { ["english"] = { [1] = "This place is under my protection. The mysteries of the arcane shall remain inviolate." }, ["npcs"] = { [1] = "Azuregos" }, ["priority"] = 1, ["text"] = "Це місце знаходиться під моїм захистом. Таємниці аркани залишаться непорушними." },
    [4182785871] = { ["english"] = { [1] = "Feel the power of the Dark Iron Dwarves!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Відчуй силу дворфів Темного Заліза!" },
    [4183863513] = { ["english"] = { [1] = "It's quiet here...." }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Тут тихо...." },
    [4184505903] = { ["english"] = { [1] = "Ah yes, and promptly delivered.  As always, it's a pleasure doing business with you, Corbett." }, ["npcs"] = { [1] = "Harlan Bagley" }, ["priority"] = 1, ["text"] = "Так, чудово, і дуже вчасно. Як завжди, приємно мати з вами справу, Корбете." },
    [4192183601] = { ["english"] = { [1] = "Oooooo hot hot hot!  If that won't put spring in your step, I don't know what will!" }, ["npcs"] = { [1] = "Durnan Furcutter" }, ["priority"] = 1, ["text"] = "Ой-ой-ой, гаряче! Якщо це не додасть тобі бадьорості, то вже не знаю, що додасть!" },
    [4192468796] = { ["english"] = { [1] = "With your help, I can evaluate these tunnels." }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "З вашою допомогою я зможу дослідити ці тунелі." },
    [4195739368] = { ["english"] = { [1] = "The light appears to have forsaken us." }, ["npcs"] = { [1] = "Hogan Ference" }, ["priority"] = 3, ["text"] = "Схоже, Світло покинуло нас." },
    [4198826476] = { ["english"] = { [1] = "I apologize for taking so long to get here. I wanted Lady Proudmoore to be present also." }, ["npcs"] = { [1] = "Archmage Tervosh" }, ["priority"] = 1, ["text"] = "Прошу вибачення, що так довго добирався сюди. Я хотів, щоб Леді Праудмур теж була присутня." },
    [4199974909] = { ["english"] = { [1] = "Tiny mortals - me HERE! Doom you meet!" }, ["npcs"] = { [1] = "Avalanchion" }, ["priority"] = 1, ["text"] = "Малі смертні, Я ТУТ! Я ваш кінець!" },
    [420142467] = { ["english"] = { [1] = "Whoa! Look at that bullseye!" }, ["npcs"] = { [1] = "Guard Lasiter" }, ["priority"] = 1, ["text"] = "Ого! Прямо в ціль!" },
    [4201812884] = { ["english"] = { [1] = "Indeed it could have. Most importantly, you are unharmed, Cyriden?" }, ["npcs"] = { [1] = "Relathor Moonsong" }, ["priority"] = 1, ["text"] = "Так, могло. Ти не поранився, Цирідене?" },
    [4202242594] = { ["english"] = { [1] = "\"Magical Flows and How They Effect the World\", by Maginor Dumas. That's the one I was looking for." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "\"Магічні потоки та їхній вплив на світ\", автор Маґінор Дюма. Це те, що я шукала." },
    [4202713103] = { ["english"] = { [1] = "There! Over there!" }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Сюди! Нам сюди!" },
    [4203675925] = { ["english"] = { [1] = "Stand prepared! The naga won't wait long to press their advantage once they know we're alive." }, ["npcs"] = { [1] = "Captain Vanessa Beltis" }, ["priority"] = 1, ["text"] = "Приготуйтеся! Наги не зволікатимуть з атакою коли дізнаються, що ми живі." },
    [420553326] = { ["english"] = { [1] = "%s feeds the toad some of the strange liquid." }, ["npcs"] = { [1] = "Apothecary Keever" }, ["priority"] = 1, ["text"] = "%s дає жабі попити дивної рідини." },
    [4206509574] = { ["english"] = { [1] = "We'll dance on your bones!" }, ["npcs"] = { [1] = "Defias Rioter" }, ["priority"] = 1, ["text"] = "Ми танцюватимемо на ваших кістках!" },
    [4207632010] = { ["english"] = { [1] = "By the stars! A spirit has been summoned!" }, ["npcs"] = { [1] = "Archaeologist Flagongut" }, ["priority"] = 1, ["text"] = "Клянусь зірками! Ми викликали духа!" },
    [4209279697] = { ["english"] = { [1] = "Just /lay down anywhere, <name>. I promise, this won't hurt a bit!" }, ["npcs"] = { [1] = "Doc Mixilpixil" }, ["priority"] = 1, ["text"] = "Просто ляж десь тут, {ім'я:к}. Це не буде боляче, обіцяю!#anywhere, <name>." },
    [4210638001] = { ["english"] = { [1] = "Your efforts will prove fruitless. None shall stand in our way!" }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Ваші зусилля марні. Ніхто не зможе завадити нам!" },
    [4212932807] = { ["english"] = { [1] = "Send them on! I'm not afraid of some scrawny beasts!" }, ["npcs"] = { [1] = "Miran" }, ["priority"] = 1, ["text"] = "Нехай ідуть! Я не боюся якихось кволих звірюк!" },
    [4214257942] = { ["english"] = { [1] = "The cannons must be finished soon." }, ["npcs"] = { [1] = "Gilnid" }, ["priority"] = 3, ["text"] = "Гармати треба закінчити якнайшвидше." },
    [4214926514] = { ["english"] = { [1] = "You no take candle!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Не рухай свічу!" },
    [4215245369] = { ["english"] = { [1] = "Kel'thuzad make Patchwerk his avatar of war!" }, ["npcs"] = { [1] = "Patchwerk" }, ["priority"] = 1, ["text"] = "Кел'Тузад зробити Клаптик богом війни!" },
    [4216779478] = { ["english"] = { [1] = "Let's see if we can find out where these Troggs are coming from.... and put a stop to the invasion!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "Спробуймо з'ясувати, звідки з'являються ці троги... і покінчимо з цим!" },
    [4219946871] = { ["english"] = { [1] = "Farewell, citizens of Darkshire. Until next time..." }, ["npcs"] = { [1] = "Antonio Perelli" }, ["priority"] = 1, ["text"] = "Бувайте, жителі Темнодолу. До наступної зустрічі..." },
    [4223143274] = { ["english"] = { [1] = "Thank you for clearing out those foolish senators.  Now prepare to meet your doom at the hands of Ragnaros' most powerful servant." }, ["npcs"] = { [1] = "Emperor Dagran Thaurissan" }, ["priority"] = 1, ["text"] = "Дякую, що позбулися тих дурних сенаторів. Тепер приготуйтеся зустріти свою загибель від рук наймогутнішого слуги Рагнароса." },
    [4231085302] = { ["english"] = { [1] = "Filthy Frostwolf cowards! If you want a fight, you'll have to come to me!" }, ["npcs"] = { [1] = "Captain Balinda Stonehearth" }, ["priority"] = 1, ["text"] = "Брудні боягузи Морозних Вовків! Як хочете битись — приходьте до мене самі!" },
    [423630119] = { ["english"] = { [1] = "Thank you for this report, <name>.  It is now clear that we must tighten our patrols near Theramore." }, ["npcs"] = { [1] = "Captain Garran Vimes" }, ["priority"] = 1, ["text"] = "Дякую за звіт, {ім'я:к}. Вочевидь, ми маємо посилити патрулювання навколо Терамора.#report, <name>." },
    [4236310781] = { ["english"] = { [1] = "Shine yer armor for a copper." }, ["npcs"] = { [1] = "Topper McNabb" }, ["priority"] = 1, ["text"] = "Почищу обладунок за мідяк." },
    [4243563167] = { ["english"] = { [1] = "Which one shall I eat first? So difficult to choose. They all smell so delicious..." }, ["npcs"] = { [1] = "Anub'Rekhan" }, ["priority"] = 1, ["text"] = "Кого ж мені з'їсти першим? Так тяжко вибрати. Ви всі такі апетитні..." },
    [4243683744] = { ["english"] = { [1] = "WAAAHHH!!!" }, ["npcs"] = { [1] = "Donna" }, ["priority"] = 1, ["text"] = "И-И-А-А-А!!!" },
    [4244820855] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "It is my duty and honor to die for the Abyssal Council!" }, ["npcs"] = { [1] = "Crimson Templar" }, ["priority"] = 1, ["text"] = "Мій обов'язок і честь — померти за Раду Безодні!" }, [2] = { ["english"] = { [1] = "It is my duty and honor to die for the Abyssal Council!" }, ["npcs"] = { [1] = "Earthen Templar" }, ["priority"] = 1, ["text"] = "Мій обов'язок і честь — померти за Раду Безодні!" }, [3] = { ["english"] = { [1] = "It is my duty and honor to die for the Abyssal Council!" }, ["npcs"] = { [1] = "Hoary Templar" }, ["priority"] = 1, ["text"] = "Мій обов'язок і честь — померти за Раду Безодні!" } }, ["english"] = { [1] = "It is my duty and honor to die for the Abyssal Council!" }, ["npcs"] = { [1] = "Azure Templar" }, ["priority"] = 1, ["text"] = "Мій обов'язок і честь — померти за Раду Безодні!" },
    [424801872] = { ["english"] = { [1] = "Oh no!  Here they come!" }, ["npcs"] = { [1] = "Weegli Blastfuse" }, ["priority"] = 1, ["text"] = "О ні! Вони йдуть!" },
    [4250208926] = { ["english"] = { [1] = "Do you ever think about anything other than fighting? I could circle you down on the stretch course!" }, ["npcs"] = { [1] = "Pilot Bellowfiz" }, ["priority"] = 3, ["text"] = "Ти взагалі про щось інше, крім бійок, думаєш? Я б тебе на довгій трасі колами обійшов!" },
    [4253796088] = { ["english"] = { [1] = "The Al'Aketh cult continues to escalate their violence, and the Windshapers stubbornly refuse to recognize the inaction that brought us here." }, ["npcs"] = { [1] = "Rathiril Sunlance" }, ["priority"] = 3, ["text"] = "Культ Ал'Акету продовжує нарощувати насильство, а вітротворці вперто відмовляються визнавати бездіяльність, що привела нас сюди." },
    [4255016249] = { ["english"] = { [1] = "I have changed my mind loyal servants, you do not need to bring the prisoner all the way to my study, I will deal with him here and now." }, ["npcs"] = { [1] = "Arugal" }, ["priority"] = 1, ["text"] = "Я передумав, мої вірні слуги, немає потреби тягнути в'язня до мого кабінету, я розберуся з ним тут і зараз." },
    [4256865728] = { ["english"] = { [1] = "Oh my! Look at this... all these candles. I'm sure they're used for some terrible ritual or dark summoning. We best make haste!" }, ["npcs"] = { [1] = "Captured Arko'narin" }, ["priority"] = 1, ["text"] = "Ох! Поглянь на це... всі ці свічки. Я впевнена, що їх використовують для якогось жахливого ритуалу або темного закликання. Нам краще поквапитись!" },
    [4258093848] = { ["english"] = { [1] = "To the house! Stay close to me, no matter what! I have my gun and ammo there!" }, ["npcs"] = { [1] = "Daphne Stilwell" }, ["priority"] = 1, ["text"] = "До хати! Тримайся поруч зі мною! У мене там зброя і набої!" },
    [4259127820] = { ["english"] = { [1] = "Rolls, buns and bread. Baked fresh!" }, ["npcs"] = { [1] = "Thomas Miller" }, ["priority"] = 1, ["text"] = "Пироги та хліб. Свіжоспечені!" },
    [426077512] = { ["english"] = { [1] = "Try to take better care of yourself, Quinn.  You were lucky this time." }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "Бережи себе, Квінне. Цього разу тобі пощастило." },
    [4264868898] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "My lord will be outraged to learn of this ambush.  Let us hope your death will appease him." }, ["npcs"] = { [1] = "Crimson Templar" }, ["priority"] = 1, ["text"] = "Мій повелитель буде розлючений, коли дізнається про цю засідку. Сподіваюсь, його втішить твоя смерть." }, [2] = { ["english"] = { [1] = "My lord will be outraged to learn of this ambush.  Let us hope your death will appease him." }, ["npcs"] = { [1] = "Earthen Templar" }, ["priority"] = 1, ["text"] = "Мій повелитель буде розлючений, коли дізнається про цю засідку. Сподіваюсь, його втішить твоя смерть." }, [3] = { ["english"] = { [1] = "My lord will be outraged to learn of this ambush.  Let us hope your death will appease him." }, ["npcs"] = { [1] = "Hoary Templar" }, ["priority"] = 1, ["text"] = "Мій повелитель буде розлючений, коли дізнається про цю засідку. Сподіваюсь, його втішить твоя смерть." } }, ["english"] = { [1] = "My lord will be outraged to learn of this ambush.  Let us hope your death will appease him." }, ["npcs"] = { [1] = "Azure Templar" }, ["priority"] = 1, ["text"] = "Мій повелитель буде розлючений, коли дізнається про цю засідку. Сподіваюсь, його втішить твоя смерть." },
    [4265399495] = { ["english"] = { [1] = "I'm lucky to be alive!" }, ["npcs"] = { [1] = "Acolyte Dellis" }, ["priority"] = 1, ["text"] = "Мені пощастило, що я живий!" },
    [4266492743] = { ["english"] = { [1] = "Poor Dorius. If I ever get my hands on those Dark Irons, so help me..." }, ["npcs"] = { [1] = "Curator Thorius" }, ["priority"] = 1, ["text"] = "Бідний Дорій. Якщо я коли-небудь доберуся до цих дворфів Темного Заліза..." },
    [4267058799] = { ["english"] = { [1] = "Come to me, my children!" }, ["npcs"] = { [1] = "Witch Doctor Zum'rah" }, ["priority"] = 1, ["text"] = "Ходіть до мене, діти мої!" },
    [4268511530] = { ["english"] = { [1] = "Thank you, <name>.  May the Light bless you, <brother/sister>, and guide your path." }, ["npcs"] = { [1] = "Brother Kristoff" }, ["priority"] = 1, ["text"] = "Дякую тобі, {ім'я:к}. Нехай Світло благословить тебе, {стать:брате:сестро}, і вказує тобі шлях." },
    [4268512181] = { ["english"] = { [1] = "...Sampson, Yorick, Chamley..." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "...Семпсон, Йорік, Чамлі..." },
    [4271136130] = { ["english"] = { [1] = "It was a critical mistake that our people left their fates in the hands of fickle elemental spirits. It's up to us now to remedy that error." }, ["npcs"] = { [1] = "Rathiril Sunlance" }, ["priority"] = 3, ["text"] = "Було великою помилкою віддати долі нашого народу в руки мінливих стихійних духів. Тепер виправити цю помилку належить нам." },
    [4277185839] = { ["english"] = { [1] = "Let it be known that <name> - Horde <class> - has earned the undying respect of the Warchief.   <He/She> has engaged in great diplomacy with Timbermaw Hold and performed valiant actions for them on our behalf.   <He/She> has gone above and beyond the call of duty.  Three cheers for <name> - a true hero of the Horde!" }, ["npcs"] = { [1] = "Thrall" }, ["priority"] = 1, ["text"] = "Знайте ж, що {клас:н} Орди, {ім'я:н}, {стать:заслужив:заслужила} на безмежну повагу вождя. {стать:Він долучився:Вона долучилась} до великої дипломатичної місії з оплотом Деревопузих та {стать:здійснив:здійснила} відважні вчинки для них від нашого імені, перевершивши свій службовий обов'язок. Славімо {ім'я:з} — {стать:справжнього героя:справжню героїню} Орди!#that <name> - Horde#Horde <class> - has#<He/She> has engaged" },
    [4277440575] = { ["english"] = { [1] = "Fear not.  The Night Watch will rid the land of this foul taint soon enough." }, ["npcs"] = { [1] = "Commander Althea Ebonlocke" }, ["priority"] = 1, ["text"] = "Не бійтеся. Нічна варта незабаром очистить землю від цієї нечисті." },
    [4277617887] = { ["english"] = { [1] = "I see those fools at the Abbey sent some fresh meat for us." }, ["npcs"] = { [1] = "Defias Thug" }, ["priority"] = 1, ["text"] = "Бачу, ці дурні з абатства послали нам свіже м'ясо." },
    [4277758189] = { ["english"] = { [1] = "I'm not gonna make it... death comes..." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Я не виживу... смерть вже близько..." },
    [4278545298] = { ["english"] = { [1] = "%s hatches!" }, ["npcs"] = { [1] = "Deepmoss Hatchling" }, ["priority"] = 1, ["text"] = "%s вилуплюється!" },
    [4279558791] = { ["english"] = { [1] = "%s flinches as its skin shimmers." }, ["npcs"] = { [1] = "Chromaggus" }, ["priority"] = 1, ["text"] = "%s здригається, коли його шкіра починає мерехтіти." },
    [4283756175] = { ["english"] = { [1] = "There we go. All done!" }, ["npcs"] = { [1] = "Curator Thorius" }, ["priority"] = 1, ["text"] = "Ось так. Готово!" },
    [4291805158] = { ["english"] = { [1] = "You are too late!! I... must... obey!!" }, ["npcs"] = { [1] = "Thaddius" }, ["priority"] = 1, ["text"] = "Ви запізнилися!! Я... мушу... підкоритися!!" },
    [433684595] = { ["english"] = { [1] = "You're still here?  Your foolishness is amusing!  The Argent Dawn wench needn't suffer in vain.  Leave at once and she shall be spared!" }, ["npcs"] = { [1] = "Baron Rivendare" }, ["priority"] = 1, ["text"] = "Ви досі тут? Ваша дурість мене веселить! Це дівчисько зі Сріблястого Світанку не має страждати марно. Йдіть геть, і я її помилую!" },
    [448726927] = { ["english"] = { [1] = "<name>, my form has now changed! The true strength of my spirit is returning to me now... The cursed grasp of the forest is leaving me." }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "{ім'я:к}, я змінився! Я відчуваю, як справжня сила мого духу повертається... Прокляття лісу полишає мене." },
    [449509889] = { ["english"] = { [1] = "The Blackrock infestation is thick in these parts.  I will do my best to keep the pace, <name>.  Let's go!" }, ["npcs"] = { [1] = "Corporal Keeshan" }, ["priority"] = 1, ["text"] = "Орки Чорнокаменю міцно закріпились тут. Я постараюся не відставати, {ім'я:к}. Ходімо!#pace, <name>." },
    [451134110] = { ["english"] = { [1] = "Darrowshire, to arms!  The Scourge approach!" }, ["npcs"] = { [1] = "Darrowshire Defender" }, ["priority"] = 1, ["text"] = "Дарроушир, до зброї! Скара наближається!" },
    [453763440] = { ["english"] = { [1] = "I'm Augustus, and my prices are INSANE!" }, ["npcs"] = { [1] = "Augustus the Touched" }, ["priority"] = 1, ["text"] = "Я Август, і мої ціни ШАЛЕНІ!" },
    [454119922] = { ["english"] = { [1] = "One more down!" }, ["npcs"] = { [1] = "Daphne Stilwell" }, ["priority"] = 1, ["text"] = "Влучила!" },
    [455613596] = { ["english"] = { [1] = "My dear Staffron, have you forgotten what it is to love? The love that we once shared?" }, ["npcs"] = { [1] = "Annalise Lerent" }, ["priority"] = 1, ["text"] = "Мій любий Стаффроне, невже ти забув, що таке кохання? Те почуття, що ми колись поділяли?" },
    [465130956] = { ["english"] = { [1] = "We must move quickly. Auberdine isn't too far away, but many enemies lurk in the forest." }, ["npcs"] = { [1] = "Feero Ironhand" }, ["priority"] = 1, ["text"] = "Ми маємо рухатись швидко. Аубердін не надто далеко, але в лісі ховається багато ворогів." },
    [466353340] = { ["english"] = { [1] = "I'm out of here!" }, ["npcs"] = { [1] = "Weegli Blastfuse" }, ["priority"] = 1, ["text"] = "Я вшиваюсь звідси!" },
    [467030363] = { ["english"] = { [1] = "Release your rage!" }, ["npcs"] = { [1] = "Archmage Arugal" }, ["priority"] = 1, ["text"] = "Вивільни свою лють!" },
    [467851641] = { ["english"] = { [1] = "To my side, brothers! For the Makers!" }, ["npcs"] = { [1] = "Archaedas" }, ["priority"] = 1, ["text"] = "До мене, брати! За Творців!" },
    [469191131] = { ["english"] = { [1] = "No more play?" }, ["npcs"] = { [1] = "Patchwerk" }, ["priority"] = 1, ["text"] = "Більше не хотіти гратись?" },
    [470701719] = { ["english"] = { [1] = "Yes ma'am, business is brisk!" }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Так, пані, крамниця процвітає!" },
    [472029605] = { ["english"] = { [1] = "Are we there yet?" }, ["npcs"] = { [1] = "Gil" }, ["priority"] = 1, ["text"] = "Ми вже прийшли?" },
    [478231009] = { ["english"] = { [1] = "It isn't enough! Defenders, gather in the center of town. Together we will stand against the undead monster!" }, ["npcs"] = { [1] = "Town Crier" }, ["priority"] = 1, ["text"] = "Цього недостатньо! Захисники, зберіться на площі міста. Разом ми вистоїмо проти цієї невмерлої потвори!" },
    [47867955] = { ["english"] = { [1] = "%s calls for help!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s кличе на допомогу!" },
    [479065494] = { ["english"] = { [1] = "You've plundered our treasures too long.  Prepare to meet your watery grave!" }, ["npcs"] = { [1] = "Daggerspine Marauder" }, ["priority"] = 1, ["text"] = "Ви надто довго розкрадали наші скарби. Готуйтесь зустріти свою загибель!" },
    [48219426] = { ["english"] = { [1] = "Hideous bellows and growls are heard coming from that old hermit's shack!" }, ["npcs"] = { [1] = "Watcher Cutford" }, ["priority"] = 3, ["text"] = "З халупи старого відлюдника долинають жахливі ревіння й гарчання!" },
    [487652073] = { ["english"] = { [1] = "Guard, Bring forth the prisoner. Place him in the Circle of Binding." }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "Варта, приведіть в'язня. Помістіть його у коло зв'язування." },
    [487738159] = { ["english"] = { [1] = "Our cause falls on deaf ears beyond the thick, stone walls of Stormwind." }, ["npcs"] = { [1] = "Ambassador Berrybuck" }, ["priority"] = 1, ["text"] = "Наші прохання не почують за товстими, кам'яними мурами Штормовію." },
    [487742423] = { ["english"] = { [1] = "Please let me know if you need anything else!" }, ["npcs"] = { [1] = "Jessica Chambers" }, ["priority"] = 1, ["text"] = "Будь ласка, дайте мені знати, якщо вам ще щось знадобиться!" },
    [487962429] = { ["english"] = { [1] = "%s falls to one knee - exhausted." }, ["npcs"] = { [1] = "Fandral Staghelm" }, ["priority"] = 1, ["text"] = "%s падає на одне коліно від знесилля." },
    [489399138] = { ["english"] = { [1] = "I'll finish you off for good this time!" }, ["npcs"] = { [1] = "Feero Ironhand" }, ["priority"] = 1, ["text"] = "Цього разу я тебе остаточно знищу!" },
    [490730569] = { ["english"] = { [1] = "Give to the charities who seek to help the victims of these hard times! Please." }, ["npcs"] = { [1] = "John Turner" }, ["priority"] = 3, ["text"] = "Пожертвуйте благодійникам, які допомагають жертвам цих тяжких часів! Будь ласка." },
    [490962550] = { ["english"] = { [1] = "%s chants words of power..." }, ["npcs"] = { [1] = "Bethor Iceshard" }, ["priority"] = 1, ["text"] = "%s начитує слова сили..." },
    [500735517] = { ["english"] = { [1] = "Farewell to you, and may shadow always protect you!" }, ["npcs"] = { [1] = "Deathguard Kel" }, ["priority"] = 1, ["text"] = "Бувай, і нехай тіні завжди захищають тебе!" },
    [50107295] = { ["english"] = { [1] = "The Primal Gods? Impossible!" }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "Первісні боги? Неможливо!" },
    [502614670] = { ["english"] = { [1] = "Scourge in the Trade District!  Have at them!" }, ["npcs"] = { [1] = "Stormwind Elite Guard" }, ["priority"] = 1, ["text"] = "Скара в Торговому районі! Знищте їх!" },
    [50351489] = { ["english"] = { [1] = "An Ash'ari Crystal has been toppled! Restore the ziggurat before the Necropolis is vulnerable!" }, ["npcs"] = { [1] = "Thuzadin Acolyte" }, ["priority"] = 1, ["text"] = "Кристал Аш'арі розбито! Відновіть зіккурат, поки некрополь не втратив захист!" },
    [506692380] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Aye and thanks for letting me carry my own hand back to the priests that night." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Ага, і дякую що дозволив тоді мені самому нести свою руку до жерців." } }, ["english"] = { [1] = "Aye and thanks for letting me carry my own hand back to the priests that night." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Ага, і дякую що дозволив тоді мені самому нести свою руку до жерців." },
    [507983674] = { ["english"] = { [1] = "For the Horde!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "За Орду!" },
    [509234053] = { ["english"] = { [1] = "The boss wants all hands on high alert.  The rusty anchor sinks tonight." }, ["npcs"] = { [1] = "Defias Messenger" }, ["priority"] = 1, ["text"] = "Бос наказав всім бути напоготові. Іржавий якір опуститься цієї ночі." },
    [522092020] = { ["english"] = { [1] = "%s drops its weapon." }, ["npcs"] = { [1] = "Atiesh" }, ["priority"] = 1, ["text"] = "%s впустив з рук зброю." },
    [526009539] = { ["english"] = { [1] = "Freedom!" }, ["npcs"] = { [1] = "Defias Rioter" }, ["priority"] = 1, ["text"] = "Свобода!" },
    [528832848] = { ["english"] = { [1] = "Kill the filthy <race>!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Вбийте {стать:цього:цю} {клас:з}.#filthy <race>!" },
    [529247113] = { ["english"] = { [1] = "No!  You cannot be stronger than the Foulweald!  No!!" }, ["npcs"] = { [1] = "Chief Murgut" }, ["priority"] = 1, ["text"] = "Ні! Ти не можеш бути сильніше за Гидколісових! Ні!!" },
    [529291730] = { ["english"] = { [1] = "Alright, <name>, your transponder is ready!" }, ["npcs"] = { [1] = "Scooty" }, ["priority"] = 1, ["text"] = "Ну от і все, {ім'я:к}, твій транспондер готовий!" },
    [534946689] = { ["english"] = { [1] = "So I was right about the energies. Let's see what the other tome has to say on the subject." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "То я все-таки мала рацію щодо енергій. Погляньмо, що про це скаже інший фоліант." },
    [538414898] = { ["english"] = { [1] = "%s summons a Blackhand Veteran to his aid!" }, ["npcs"] = { [1] = "Blackhand Summoner" }, ["priority"] = 1, ["text"] = "%s викликає ветерана Чорнорука на допомогу!" },
    [539088995] = { ["english"] = { [1] = "Oh, great." }, ["npcs"] = { [1] = "Captured Leper Gnome" }, ["priority"] = 1, ["text"] = "Ох, чудово." },
    [550706322] = { ["english"] = { [1] = "Ask me how to get a free drink at the Blue Recluse!" }, ["npcs"] = { [1] = "Erich Lohan" }, ["priority"] = 1, ["text"] = "Запитай мене, як отримати безплатний напій у «Синьому Самітнику»!" },
    [552359531] = { ["english"] = { [1] = "Sufficiently skilled leatherworkers, for example, can place a tent like this one behind me." }, ["npcs"] = { [1] = "Raan Wildwind" }, ["priority"] = 3, ["text"] = "Наприклад, достатньо вправні шкіряники можуть встановити такий намет, як у мене позаду." },
    [554360574] = { ["english"] = { [1] = "We don't take kindly to miscreants, <race>." }, ["npcs"] = { [1] = "Cenarion Hold Infantry" }, ["priority"] = 1, ["text"] = "Ми не терпітимемо тут злочинців, {раса:к}.#miscreants, <race>." },
    [555752085] = { ["english"] = { [1] = "So... You thought you could fool me, did you? The greatest criminal mastermind Azeroth has ever known???" }, ["npcs"] = { [1] = "Doctor Weavil" }, ["priority"] = 1, ["text"] = "То... Ви думали, що зможете мене обдурити, так? Найгеніальнішого злодія в Азероті???" },
    [556253084] = { ["english"] = { [1] = "%s reignites from the heat of another Core Hound!" }, ["npcs"] = { [1] = "Core Hound" }, ["priority"] = 1, ["text"] = "%s знову загоряється від жару іншого гончака ядра!" },
    [556540772] = { ["english"] = { [1] = "You cannot save him!" }, ["npcs"] = { [1] = "Decrepit Guardian" }, ["priority"] = 1, ["text"] = "Їх вже не врятувати!" },
    [557369060] = { ["english"] = { [1] = "I'm back!" }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Я повернувся!" },
    [561652960] = { ["english"] = { [1] = "Come on boys, we've got to get this bridge rebuilt." }, ["npcs"] = { [1] = "Foreman Oslow" }, ["priority"] = 1, ["text"] = "До роботи, хлопці. Ми маємо відбудувати цей міст." },
    [561847920] = { ["english"] = { [1] = "Ashes to ashes!" }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Прах до праху." },
    [562534426] = { ["english"] = { [1] = "%s's eyes glow red as he lights his dynamite and begins to cackle madly!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "%s починає божевільно реготати, запалюючи динаміт!" },
    [563667789] = { ["english"] = { [1] = "All you need to start a camp of your own is a basic campfire. Cooks can generally teach you how to make one of those." }, ["npcs"] = { [1] = "Raan Wildwind" }, ["priority"] = 3, ["text"] = "Усе, що потрібно, щоб облаштувати власний табір, — звичайне багаття. Кухарі зазвичай можуть навчити тебе його розпалювати." },
    [564955336] = { ["english"] = { [1] = "Brain encaved... mortar... bas... hed... leaking... dyin... g..." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "В голову... прилетіло... мортира... я... вмираю..." },
    [569395220] = { ["english"] = { [1] = "The Dark Iron Dwarves shall reclaim their rightful lands!" }, ["npcs"] = { [1] = "Balgaras the Foul" }, ["priority"] = 1, ["text"] = "Дворфи Темного Заліза повернуть свої законні землі!" },
    [569971452] = { ["english"] = { [1] = "Most definitely." }, ["npcs"] = { [1] = "Razzle Sprysprocket" }, ["priority"] = 1, ["text"] = "Авжеж." },
    [572393108] = { ["english"] = { [1] = "The runes of warding have been destroyed! Hunt down the infidels, my brethren!" }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Захисні руни знищено! Вбийте невірних, брати мої!" },
    [574196249] = { ["english"] = { [1] = "Could ye spare some coin?" }, ["npcs"] = { [1] = "Topper McNabb" }, ["priority"] = 1, ["text"] = "Не знайдеться монетки?" },
    [574209632] = { ["english"] = { [1] = "Make Way!  Make Way!" }, ["npcs"] = { [1] = "Watcher Cutford" }, ["priority"] = 3, ["text"] = "Дорогу! Дорогу!" },
    [577209090] = { ["english"] = { [1] = "Hey Stone, did you hear about the new steam engine old Tonkrend has been runnin on?" }, ["npcs"] = { [1] = "Pilot Bellowfiz" }, ["priority"] = 3, ["text"] = "Гей, Стоуне, чув про новий паровий двигун, на якому старий Тонкренд тепер ганяє?" },
    [581654073] = { ["english"] = { [1] = "We need better representation from Stormwind.  Our homes are falling to the undead." }, ["npcs"] = { [1] = "Councilman Millstipe" }, ["priority"] = 1, ["text"] = "Нам потрібно більше підтримки від Штормовію. Невмерлі захоплюють наші домівки!" },
    [585013453] = { ["english"] = { [1] = "People of the Horde, citizens of Orgrimmar, come, gather round and celebrate a hero of the Horde. On this day, <name>, under the auspices of our glorious Warchief, laid a mortal blow against the Black Dragonflight. The brood mother, Onyxia, has been slain!" }, ["npcs"] = { [1] = "Overlord Runthak" }, ["priority"] = 1, ["text"] = "Ординці, жителі Орґріммару, виходьте, збирайтеся і вшановуйте героя Орди! Сьогодні руками {ім'я:р} було завдано смертельного удару чорним драконам під егідою нашого славного вождя. Матір виводка, Оніксію, знищено!#day, <name>, under" },
    [586495170] = { ["english"] = { [1] = "Huh? What dat?" }, ["npcs"] = { [1] = "Chok'sul" }, ["priority"] = 1, ["text"] = "Га? Це шо?" },
    [587092614] = { ["english"] = { [1] = "Time to join us, <class>." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Приєднуйся до нас, {клас:к}.#us, <class>." },
    [601387200] = { ["english"] = { [1] = "Help! I've only one hand to defend myself with." }, ["npcs"] = { [1] = "Miran" }, ["priority"] = 1, ["text"] = "Допоможіть! У мене лише одна вільна рука, щоб захищатися." },
    [601612190] = { ["english"] = { [1] = "Take a chest of containment coffers and a cantation of manifestation, <name>.  You will need them for your mission." }, ["npcs"] = { [1] = "Anastasia Hartwell" }, ["priority"] = 1, ["text"] = "Візьми ящик зі скринями стримування та закляття прояву, {ім'я:к}. Вони знадобляться тобі для цього завдання.#of manifestation, <name>." },
    [601895925] = { ["english"] = { [1] = "Destroy the Scourge invader now, before it's too late!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Знищте загарбників Скари, поки не пізно!" },
    [602586440] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Abyssal Council does not tolerate deceit!  Feel our wrath, little <race>!" }, ["npcs"] = { [1] = "Crimson Templar" }, ["priority"] = 1, ["text"] = "Рада Безодні не терпить обману! Відчуй наш гнів, {раса:к}!#little <race>!" }, [2] = { ["english"] = { [1] = "The Abyssal Council does not tolerate deceit!  Feel our wrath, little <race>!" }, ["npcs"] = { [1] = "Earthen Templar" }, ["priority"] = 1, ["text"] = "Рада Безодні не терпить обману! Відчуй наш гнів, {раса:к}!#little <race>!" }, [3] = { ["english"] = { [1] = "The Abyssal Council does not tolerate deceit!  Feel our wrath, little <race>!" }, ["npcs"] = { [1] = "Hoary Templar" }, ["priority"] = 1, ["text"] = "Рада Безодні не терпить обману! Відчуй наш гнів, {раса:к}!#little <race>!" } }, ["english"] = { [1] = "The Abyssal Council does not tolerate deceit!  Feel our wrath, little <race>!" }, ["npcs"] = { [1] = "Azure Templar" }, ["priority"] = 1, ["text"] = "Рада Безодні не терпить обману! Відчуй наш гнів, {раса:к}!#little <race>!" },
    [605287202] = { ["english"] = { [1] = "Hey, who Fengus callin' a gnoll lover?!  Take da prisoners to da king; you smart to bring them with their weapons and show da king that they a threat.  I'll go see if Fengus talk smack when I give him da beatdown!  HAR!" }, ["npcs"] = { [1] = "Captain Kromcrush" }, ["priority"] = 1, ["text"] = "Гей, кого там Фенґ гнололюбом назвав?! Веди цих полонених до короля. Мудро було лишить їм зброю, зразу видно — угроза. А я піду гляну, шо скаже Фенґ, коли я його поб'ю! ГРРР!" },
    [606843393] = { ["english"] = { [1] = "Ah!  My wounds are too severe.  Defenders, fight on without me!" }, ["npcs"] = { [1] = "Davil Lightfire" }, ["priority"] = 1, ["text"] = "Ах! Мої рани занадто тяжкі. Захисники, бийтеся без мене!" },
    [607994370] = { ["english"] = { [1] = "Are you sure you weren't followed here? I have a very bad feeling all of a sudden..." }, ["npcs"] = { [1] = "Donova Snowden" }, ["priority"] = 1, ["text"] = "Ти {стать:впевнений:впевнена}, що за тобою не стежили? У мене погане передчуття..." },
    [608549811] = { ["english"] = { [1] = "There will be pain..." }, ["npcs"] = { [1] = "Emperor Vek'lor" }, ["priority"] = 1, ["text"] = "Буде боляче..." },
    [609189386] = { ["english"] = { [1] = "All Hail <name>, slayer of Hakkar, and hero of Azeroth!" }, ["npcs"] = { [1] = "Zandalarian Emissary" }, ["priority"] = 1, ["text"] = "Хвала {ім'я:д}, вбивці Гаккара, і герою Азероту!#All Hail <name>," },
    [613692392] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "This will not be the end of the Scarlet Crusade!  You will not break our line!" }, ["npcs"] = { [1] = "Crimson Sorcerer" }, ["priority"] = 1, ["text"] = "Це ще не кінець Багряного Походу! Вам не вдасться прорвати наші ряди!" } }, ["english"] = { [1] = "This will not be the end of the Scarlet Crusade!  You will not break our line!" }, ["npcs"] = { [1] = "Crimson Monk" }, ["priority"] = 1, ["text"] = "Це ще не кінець Багряного Походу! Вам не вдасться прорвати наші ряди!" },
    [614315550] = { ["english"] = { [1] = "Thank you, <name>." }, ["npcs"] = { [1] = "Crank Fizzlebub" }, ["priority"] = 1, ["text"] = "Дякую, {ім'я:к}.#you, <name>." },
    [616874991] = { ["english"] = { [1] = "Chugga-chugga, woo-woo!  Happy Hallow's End, <name>!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Чух-чух-чух, ту-ту! Щасливого Повечір'я святих, {ім'я:к}!#Hallow's End, <name>!" },
    [619369637] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "More of the Warden's errand boys!" }, ["npcs"] = { [1] = "Bruegal Ironknuckle" }, ["priority"] = 1, ["text"] = "Нарешті, нові лакеї наглядача!" } }, ["english"] = { [1] = "More of the Warden's errand boys!" }, ["npcs"] = { [1] = "Bazil Thredd" }, ["priority"] = 1, ["text"] = "Нарешті, нові лакеї наглядача!" },
    [627744934] = { ["english"] = { [1] = "What? You mean you can't kill this one by yourself?" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Що? Хочеш сказати, що не зможеш вбити його самостійно?" },
    [630701700] = { ["english"] = { [1] = "Shhh... it will all be over soon." }, ["npcs"] = { [1] = "Anub'Rekhan" }, ["priority"] = 1, ["text"] = "Шшш... це все скоро закінчиться." },
    [632265318] = { ["english"] = { [1] = "Follow, <name>.  I will soon begin the summoning..." }, ["npcs"] = { [1] = "Bath'rah the Windwatcher" }, ["priority"] = 1, ["text"] = "Ходімо, {ім'я:к}. Скоро я почну виклик...#Follow, <name>." },
    [637549858] = { ["english"] = { [1] = "%s gets to one knee." }, ["npcs"] = { [1] = "Archmage Tarsis Kir-Moldir" }, ["priority"] = 1, ["text"] = "%s стає на одне коліно." },
    [641372979] = { ["english"] = { [1] = "How, my love? How will I find the strength to face the ages of the world without you by my side..." }, ["npcs"] = { [1] = "Cerellean Whiteclaw" }, ["priority"] = 1, ["text"] = "Як, кохана моя? Як мені жити у світі, в якому немає тебе..." },
    [64232006] = { ["english"] = { [1] = "Follow me and I'll open the courtyard door for you." }, ["npcs"] = { [1] = "Sorcerer Ashcrombe" }, ["priority"] = 1, ["text"] = "Йдіть за мною, і я відчиню вам двері у двір." },
    [645519445] = { ["english"] = { [1] = "Hey Stone, let's hit the circuit some time. We could run a few laps and see who wins?" }, ["npcs"] = { [1] = "Pilot Bellowfiz" }, ["priority"] = 3, ["text"] = "Гей, Стоуне, якось гайда на трасу. Зробимо кілька кіл і побачимо, хто переможе?" },
    [650927014] = { ["english"] = { [1] = "When time permits, we must speak at length.  For we have much to discuss." }, ["npcs"] = { [1] = "Gunther's Visage" }, ["priority"] = 1, ["text"] = "Коли прийде час, нас чекає довга розмова. Бо нам є що обговорити." },
    [651741368] = { ["english"] = { [1] = "The boar is superb!" }, ["npcs"] = { [1] = "Archmage Angela Dosantos" }, ["priority"] = 1, ["text"] = "Порося неперевершене!" },
    [653642717] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Your actions shame us all, <class>. It pains me to beat you senseless!" }, ["npcs"] = { [1] = "Cenarion Hold Reservist" }, ["priority"] = 1, ["text"] = "Ти ганьбиш нас всіх, {клас:к}. Мені шкода, але я мушу тебе провчити." } }, ["english"] = { [1] = "Your actions shame us all, <class>. It pains me to beat you senseless!" }, ["npcs"] = { [1] = "Cenarion Hold Infantry" }, ["priority"] = 1, ["text"] = "Ти ганьбиш нас всіх, {клас:к}. Мені шкода, але я мушу тебе провчити." },
    [655164008] = { ["english"] = { [1] = "The Affray has begun.  <name>, get ready to fight!" }, ["npcs"] = { [1] = "Twiggy Flathead" }, ["priority"] = 1, ["text"] = "Побоїще починається. {ім'я:к}, приготуйся до бою!# <name>, get" },
    [656651995] = { ["english"] = { [1] = "%s shifts uncomfortably." }, ["npcs"] = { [1] = "Baristolth of the Shifting Sands" }, ["priority"] = 1, ["text"] = "%s стривожено сіпається." },
    [657430326] = { ["english"] = { [1] = "Who is this weak <class> who challenges my might?  Die fool!" }, ["npcs"] = { [1] = "Balgaras the Foul" }, ["priority"] = 1, ["text"] = "Що за {стать:нікчемний:нікчемна} {раса:н} кидає виклик моїй могутності? Помри, {стать:дурню:дурепо}!#weak <class> who" },
    [657471394] = { ["english"] = { [1] = "Pathetic wretch!" }, ["npcs"] = { [1] = "Grand Widow Faerlina" }, ["priority"] = 1, ["text"] = "Нікчемні виродки!" },
    [663376984] = { ["english"] = { [1] = "My father says that's just a story." }, ["npcs"] = { [1] = "Brandon" }, ["priority"] = 1, ["text"] = "Мій тато каже, що це все вигадки." },
    [663388843] = { ["english"] = { [1] = "%s is enraged!" }, ["npcs"] = { [1] = "Discordant Surge" }, ["priority"] = 1, ["text"] = "%s лютує!" },
    [664383686] = { ["english"] = { [1] = "%s drops his shoulders and exposes his neck." }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "%s опускає плечі та оголює шию." },
    [664424121] = { ["english"] = { [1] = "Challenger is down!" }, ["npcs"] = { [1] = "Twiggy Flathead" }, ["priority"] = 1, ["text"] = "Претендента переможено!" },
    [665175363] = { ["english"] = { [1] = "Althea, there are reports of strange happenings at the graveyard.  Ello believes it portends an attack on Darkshire." }, ["npcs"] = { [1] = "Watcher Cutford" }, ["priority"] = 3, ["text"] = "Алтеє, надходять повідомлення про дивні події на кладовищі. Елло вважає, що це віщує напад на Темнокрай." },
    [66833651] = { ["english"] = { [1] = "None of your kind should be here!  You've doomed only yourselves!" }, ["npcs"] = { [1] = "Broodlord Lashlayer" }, ["priority"] = 1, ["text"] = "Ніхто з вас не має бути тут! Ви прирекли себе на загибель!" },
    [668457277] = { ["english"] = { [1] = "And then the Tauren said, '13 INCHES!'" }, ["npcs"] = { [1] = "Caretaker Alen" }, ["priority"] = 1, ["text"] = "А таурен каже: '30 САНТИМЕТРІВ!'" },
    [675016845] = { ["english"] = { [1] = "Feel the fury of the sands!" }, ["npcs"] = { [1] = "Chief Ukorz Sandscalp" }, ["priority"] = 1, ["text"] = "Відчуй лють пісків!" },
    [675943235] = { ["english"] = { [1] = "Get this, <target> off of me!" }, ["npcs"] = { [1] = "Blastmaster Emi Shortfuse" }, ["priority"] = 1, ["text"] = "{Ціль}! Заберіть його від мене!#this, <target> off" },
    [680847002] = { ["english"] = { [1] = "%s senses your presence and opens a nether portal!" }, ["npcs"] = { [1] = "Wandering Eye of Kilrogg" }, ["priority"] = 1, ["text"] = "%s відчуває вашу присутність і відкриває портал до Підсвіття!" },
    [680898637] = { ["english"] = { [1] = "Who dares step into my domain!  Come!  Come, and be consumed!" }, ["npcs"] = { [1] = "Chief Ukorz Sandscalp" }, ["priority"] = 1, ["text"] = "Хто сміє заходити в мої володіння? Вас поглинуть піски!" },
    [681405596] = { ["english"] = { [1] = "I... I think I see Blue..." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Здається... я бачу небеса..." },
    [682289332] = { ["english"] = { [1] = "Vek'lor, I feel your pain!" }, ["npcs"] = { [1] = "Emperor Vek'nilash" }, ["priority"] = 1, ["text"] = "Век'лор, я відчуваю твій біль!" },
    [68325480] = { ["english"] = { [1] = "I'll take whatever ya got cookin'! And throw in a bottle to wash it down!" }, ["npcs"] = { [1] = "Miner Grumnal" }, ["priority"] = 1, ["text"] = "Візьму все, що наготуєш! І пляшку чогось, щоб запити!" },
    [69454766] = { ["english"] = { [1] = "My daddy can catch more fish than your daddy!" }, ["npcs"] = { [1] = "Billy" }, ["priority"] = 1, ["text"] = "Мій тато може зловити більше риби, ніж твій тато!" },
    [701236367] = { ["english"] = { [1] = "Your victory shall be short lived. The days of both the Alliance and Horde are coming to an end! The next time we meet shall be the last." }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "Недовго ви насолоджуватиметесь своєю перемогою. Дні Альянсу та Орди добігають кінця! Наша наступна зустріч буде останньою." },
    [716981480] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Loch belongs to the Stonesplinter Tribe now, <name>!  Now die!" }, ["npcs"] = { [1] = "Grawmug" }, ["priority"] = 1, ["text"] = "Це озеро тепер належить племені Каменедробів, {ім'я:н}! Помри!#now, <name>!" }, [2] = { ["english"] = { [1] = "The Loch belongs to the Stonesplinter Tribe now, <name>!  Now die!" }, ["npcs"] = { [1] = "Magosh" }, ["priority"] = 1, ["text"] = "Це озеро тепер належить племені Каменедробів, {ім'я:н}! Помри!#now, <name>!" } }, ["english"] = { [1] = "The Loch belongs to the Stonesplinter Tribe now, <name>!  Now die!" }, ["npcs"] = { [1] = "Boss Galgosh" }, ["priority"] = 1, ["text"] = "Це озеро тепер належить племені Каменедробів, {ім'я:н}! Помри!#now, <name>!" },
    [720744741] = { ["english"] = { [1] = "Widdle!  I'm finished!" }, ["npcs"] = { [1] = "Tormus Deepforge" }, ["priority"] = 3, ["text"] = "Віддле!  Я закінчив!" },
    [72308161] = { ["english"] = { [1] = "How fortuitous. Usually, I must leave my lair in order to feed." }, ["npcs"] = { [1] = "Onyxia" }, ["priority"] = 1, ["text"] = "Як зручно. Зазвичай мені доводиться покидати своє лігво, щоб поїсти." },
    [732401472] = { ["english"] = { [1] = "%s arrives!" }, ["npcs"] = { [1] = "Deepmoss Matriarch" }, ["priority"] = 1, ["text"] = "%s наближається!" },
    [73387052] = { ["english"] = { [1] = "My entrails are leaking out! HELP!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "В мене кишки випадають! ДОПОМОЖІТЬ!" },
    [734527559] = { ["english"] = { [1] = "Holy, the translation is finished!" }, ["npcs"] = { [1] = "Sirra Von'Indi" }, ["priority"] = 3, ["text"] = "Святе небо, переклад завершено!" },
    [737656795] = { ["english"] = { [1] = "<name>, you have disturbed me from my rest!" }, ["npcs"] = { [1] = "Aquementas" }, ["priority"] = 1, ["text"] = "{Ім'я:н}, як ти смієш порушувати мій спокій?!" },
    [741033274] = { ["english"] = { [1] = "Clemens, Bartholemew, Enderman, Wyles..." }, ["npcs"] = { [1] = "Captain Nials" }, ["priority"] = 1, ["text"] = "Клеменс, Варфоломій, Ендермен, Вайлс..." },
    [743348165] = { ["english"] = { [1] = "Give me a moment while I calibrate the transponder to your height and weight specifications, <name>." }, ["npcs"] = { [1] = "Scooty" }, ["priority"] = 1, ["text"] = "Зачекай хвильку, {ім'я:к}, я відкалібрую транспондер відповідно до твоїх параметрів зросту та ваги.#specifications, <name>." },
    [748675530] = { ["english"] = { [1] = "Watch out for the <target>!" }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Обережно, {ціль}!#the <target>!" },
    [748856844] = { ["english"] = { [1] = "These mortal infidels, my lord! They have invaded your sanctum and seek to steal your secrets!" }, ["npcs"] = { [1] = "Majordomo Executus" }, ["priority"] = 1, ["text"] = "Ці невірні смертні, мій повелителю! Вони вдерлися в твою обитель і прагнуть викрасти твої таємниці!" },
    [749181509] = { ["english"] = { [1] = "Take a Candle of Beckoning from this crate, <name>." }, ["npcs"] = { [1] = "Gunther Arcanus" }, ["priority"] = 1, ["text"] = "Візьми свічку поклику з цього ящика, {ім'я:к}.#crate, <name>." },
    [749423941] = { ["english"] = { [1] = "Lord Staghelm, where are you going? You would shatter our bond for the sake of pride?" }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "Оленеріг, куди ти йдеш? Невже ти готовий обірвати наш зв'язок через свою гордість?" },
    [750886712] = { ["english"] = { [1] = "So close to blessed Lakeshire.  By the Light, let my legs carry me a bit further!" }, ["npcs"] = { [1] = "Corporal Keeshan" }, ["priority"] = 1, ["text"] = "Так близько до мого любого Приозер'я. О, Світло, допоможи мені пройти ще трохи!" },
    [753303043] = { ["english"] = { [1] = "Meet me down by the orchard--I just need to put my gun away." }, ["npcs"] = { [1] = "Daphne Stilwell" }, ["priority"] = 1, ["text"] = "Почекай мене в саду — я поки сховаю зброю." },
    [756499617] = { ["english"] = { [1] = "You're hurting her!" }, ["npcs"] = { [1] = "Donna" }, ["priority"] = 1, ["text"] = "Їй боляче!" },
    [757441668] = { ["english"] = { [1] = "Nothing must befoul the gardens! You must be destroyed!" }, ["npcs"] = { [1] = "Celebrian Dryad" }, ["priority"] = 1, ["text"] = "Ніщо не має оскверняти сади! Вас необхідно знищити!" },
    [75747258] = { ["english"] = { [1] = "We must act quickly or all shall be lost!" }, ["npcs"] = { [1] = "Anachronos the Ancient" }, ["priority"] = 1, ["text"] = "Ми повинні діяти негайно, інакше все буде втрачено!" },
    [758880484] = { ["english"] = { [1] = "<name>, that's it! I have finally figured it out!" }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "{ім'я:н}, це воно! Нарешті я все зрозуміла!#<name>, that's" },
    [764884215] = { ["english"] = { [1] = "My daddy says that in the ocean, there are fish so big they could swallow a whole ship." }, ["npcs"] = { [1] = "Billy" }, ["priority"] = 1, ["text"] = "Мій тато каже, що в океані є такі великі риби, що можуть проковтнути цілий корабель." },
    [769440050] = { ["english"] = { [1] = "Your efforts are utterly pointless, fools!  You will never be able to defeat me!" }, ["npcs"] = { [1] = "Emperor Dagran Thaurissan" }, ["priority"] = 1, ["text"] = "Ваші зусилля абсолютно марні, дурні! Ви ніколи не зможете перемогти мене!" },
    [771197595] = { ["english"] = { [1] = "Your skull gonna decorate our ritual altars!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Твій череп прикрасить наші ритуальні вівтарі!" },
    [775022159] = { ["english"] = { [1] = "Where are the so-called heroes of this world?  Too frightened to come out and play?" }, ["npcs"] = { [1] = "Baron Charr" }, ["priority"] = 1, ["text"] = "Де ж так звані герої цього світу? Занадто налякані, щоб вийти і битись?" },
    [775067910] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "A <class> called <name>? You'll make a fine breakfast!" }, ["npcs"] = { [1] = "Grawmug" }, ["priority"] = 1, ["text"] = "{Клас:к} на ім'я {ім'я:н}? Звучить, як чудовий сніданок!#A <class> called#called <name>?" }, [2] = { ["english"] = { [1] = "A <class> called <name>? You'll make a fine breakfast!" }, ["npcs"] = { [1] = "Magosh" }, ["priority"] = 1, ["text"] = "{Клас:к} на ім'я {ім'я:н}? Звучить, як чудовий сніданок!#A <class> called#called <name>?" } }, ["english"] = { [1] = "A <class> called <name>? You'll make a fine breakfast!" }, ["npcs"] = { [1] = "Boss Galgosh" }, ["priority"] = 1, ["text"] = "{Клас:к} на ім'я {ім'я:н}? Звучить, як чудовий сніданок!#A <class> called#called <name>?" },
    [777102463] = { ["english"] = { [1] = "Together, the two parts shall become one, once again." }, ["npcs"] = { [1] = "Celebras the Redeemed" }, ["priority"] = 1, ["text"] = "Разом ці частини знову стануть єдиним цілим." },
    [781081930] = { ["english"] = { [1] = "%s forces one of his Firesworn minions to erupt!" }, ["npcs"] = { [1] = "Garr" }, ["priority"] = 1, ["text"] = "%s змушує одного зі своїх вогнеклятів вибухнути!" },
    [782262517] = { ["english"] = { [1] = "And I am determined to find out more... So if you need my help again, you know where I'll be." }, ["npcs"] = { [1] = "Donova Snowden" }, ["priority"] = 1, ["text"] = "І я маю намір дізнатися більше... Тож якщо тобі знову знадобиться моя допомога — ти знаєш, де мене знайти." },
    [787301136] = { ["english"] = { [1] = "The goblins win! The goblins win!" }, ["npcs"] = { [1] = "Race Master Kronkrider" }, ["priority"] = 1, ["text"] = "Гобліни перемогли! Гобліни перемогли!" },
    [794847848] = { ["english"] = { [1] = "Die in the name of Ragnaros!" }, ["npcs"] = { [1] = "Dark Iron Sapper" }, ["priority"] = 1, ["text"] = "Помри в імʼя Раґнароса!" },
    [797569848] = { ["english"] = { [1] = "I feel... something strange..." }, ["npcs"] = { [1] = "Arei" }, ["priority"] = 1, ["text"] = "Я відчуваю... щось дивне..." },
    [800756733] = { ["english"] = { [1] = "Student is worthless, master! Student apologizes for his deficiency!" }, ["npcs"] = { [1] = "Deathknight Understudy" }, ["priority"] = 1, ["text"] = "Учень нікчемний, вчителю! Учень просить вибачення за свою недолугість!" },
    [80510248] = { ["english"] = { [1] = "%s sighs." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s зітхає." },
    [805314190] = { ["english"] = { [1] = "Humbug!  Die!" }, ["npcs"] = { [1] = "Dark Iron Kidnapper" }, ["priority"] = 1, ["text"] = "Падло! Здохни!" },
    [809762041] = { ["english"] = { [1] = "I wanna see the Mage Tower." }, ["npcs"] = { [1] = "Gil" }, ["priority"] = 1, ["text"] = "Я хочу побачити вежу магів." },
    [813230513] = { ["english"] = { [1] = "This meaningless exertion bores me. I'll incinerate you all from above!" }, ["npcs"] = { [1] = "Onyxia" }, ["priority"] = 1, ["text"] = "Ваші нікчемні зусилля починають мені набридати. Я спопелю вас усіх!" },
    [813337877] = { ["english"] = { [1] = "This sickness clouds my vision, but I know you must be a trogg.  Die foul invader!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Ця хвороба затьмарює мій зір, але я знаю, що ти трог. Здохни, брудний загарбник!" },
    [816704883] = { ["english"] = { [1] = "Even demons are capable of fear..." }, ["npcs"] = { [1] = "Commander Eligor Dawnbringer" }, ["priority"] = 1, ["text"] = "Навіть демони здатні відчувати страх..." },
    [817871051] = { ["english"] = { [1] = "I wonder if your dolly can swim!" }, ["npcs"] = { [1] = "William" }, ["priority"] = 1, ["text"] = "Цікаво, чи вміє твоя лялька плавати?!" },
    [822311711] = { ["english"] = { [1] = "For the Dark Strand!" }, ["npcs"] = { [1] = "Dark Strand Assassin" }, ["priority"] = 1, ["text"] = "За Темне Пасмо!" },
    [822776726] = { ["english"] = { [1] = "%s begins to work..." }, ["npcs"] = { [1] = "Tormus Deepforge" }, ["priority"] = 1, ["text"] = "%s береться до роботи..." },
    [825166330] = { ["english"] = { [1] = "The forest is crawling with Worgen and Ghouls.  Something must be done!" }, ["npcs"] = { [1] = "Councilman Millstipe" }, ["priority"] = 1, ["text"] = "Ліс кишить воргенами та гулями. Треба з цим щось робити!" },
    [831752674] = { ["english"] = { [1] = "I said KNEEL!" }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "Я сказав НА КОЛІНА!" },
    [831769863] = { ["english"] = { [1] = "Magical studies stressing your brain? Relax at the Blue Recluse!" }, ["npcs"] = { [1] = "Erich Lohan" }, ["priority"] = 1, ["text"] = "Магічні дослідження виснажують мозок? Відпочиньте у \"Синьому Відлюднику\"!" },
    [833423798] = { ["english"] = { [1] = "You are indeed courageous for wanting to brave the horrors that lie beyond this door." }, ["npcs"] = { [1] = "Deathstalker Adamant" }, ["priority"] = 1, ["text"] = "А ви дійсно сміливі, якщо хочете зустрітись з жахами, що чекають на вас за цими дверима." },
    [83370372] = { ["english"] = { [1] = "Time for the Gizleton Caravan to head on out! We'll be back soon but if you cannot wait, head north to Kormek's Hut. We open shop in about an hour." }, ["npcs"] = { [1] = "Rigger Gizelton" }, ["priority"] = 1, ["text"] = "Час каравану Ґізельтона вирушати! Ми скоро повернемося, але якщо не хочете чекати, вирушайте на північ до халупи Кормека. Ми відкриємо лавку десь за годину." },
    [833958517] = { ["english"] = { [1] = "%s emerges from the darkness, drawn out by the divination scryer!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s з'являється з темряви, прикликаний кристалом провидіння!" },
    [835308547] = { ["english"] = { [1] = "But I do know this - love makes the heart and body weak. It can be exploited. Without your love, I have only my work, Annalise." }, ["npcs"] = { [1] = "Apothecary Staffron Lerent" }, ["priority"] = 1, ["text"] = "Але я знаю, що любов робить серце і тіло слабкими. Її можна використати. Без твоєї любові у мене є лише моя робота, Анналіз." },
    [836168549] = { ["english"] = { [1] = "Look! Look! I caught something! Aww....it's just a stinky ol' boot." }, ["npcs"] = { [1] = "Billy" }, ["priority"] = 1, ["text"] = "Дивись! Дивись! Я щось зловив! Ех... це просто старий смердючий чобіт." },
    [843109697] = { ["english"] = { [1] = "Guards!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Варта!" },
    [843923798] = { ["english"] = { [1] = "%s snarls ferociously." }, ["npcs"] = { [1] = "Corrupted Cat" }, ["priority"] = 1, ["text"] = "%s лютo гарчить." },
    [843996743] = { ["english"] = { [1] = "Rouse and to arms, citizens of Darkshire! An abomination of the undead approaches along the road!" }, ["npcs"] = { [1] = "Town Crier" }, ["priority"] = 1, ["text"] = "До зброї, жителі Темнодолу! Невмерла потвора наближається до міста!" },
    [849172367] = { ["english"] = { [1] = "I sense danger up ahead." }, ["npcs"] = { [1] = "Crimson Courier" }, ["priority"] = 1, ["text"] = "Я відчуваю небезпеку попереду." },
    [851439666] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Less than a hundred of us, and over a thousand orcs. Only a handful of us managed to walk away from that one." }, ["npcs"] = { [1] = "Christoph Faral" }, ["priority"] = 1, ["text"] = "Нас було менше сотні, а орків з тисячу. Не багатьом тоді вдалося вижити..." } }, ["english"] = { [1] = "Less than a hundred of us, and over a thousand orcs. Only a handful of us managed to walk away from that one." }, ["npcs"] = { [1] = "Aedis Brom" }, ["priority"] = 1, ["text"] = "Нас було менше сотні, а орків з тисячу. Не багатьом тоді вдалося вижити..." },
    [857169305] = { ["english"] = { [1] = "More... More souls!" }, ["npcs"] = { [1] = "Bloodmage Thalnos" }, ["priority"] = 1, ["text"] = "Більше... Більше душ!" },
    [860163496] = { ["english"] = { [1] = "NOW FOR YOU, INSECTS! BOLDLY, YOU SOUGHT THE POWER OF RAGNAROS. NOW YOU SHALL SEE IT FIRSTHAND!" }, ["npcs"] = { [1] = "Ragnaros" }, ["priority"] = 1, ["text"] = "А ВИ, КОМАХИ! ВИ ПРАГНУЛИ СИЛИ РАГНАРОСА. ТЕПЕР ВИ ВІДЧУЄТЕ ЇЇ НА ВЛАСНІЙ ШКУРІ!" },
    [869058643] = { ["english"] = { [1] = "That's what I wanted to know. Now I just need to find where the flux variance is discussed." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Це те, що я хотіла знати. Тепер мені просто потрібно знайти щось про варіантність потоку." },
    [876533537] = { ["english"] = { [1] = "My back is killing me." }, ["npcs"] = { [1] = "Crimson Courier" }, ["priority"] = 1, ["text"] = "Моя спина мене доконає." },
    [879047473] = { ["english"] = { [1] = "Reporting for duty!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Заступаю на службу!" },
    [880046353] = { ["english"] = { [1] = "The bottles are dusty but the liquor goes down clean!" }, ["npcs"] = { [1] = "Barkeep Daniels" }, ["priority"] = 1, ["text"] = "Пляшки трохи вкрились пилом, але випивка в них просто чудова!" },
    [881297792] = { ["english"] = { [1] = "%s begins to make a copy of itself!" }, ["npcs"] = { [1] = "Devouring Ectoplasm" }, ["priority"] = 1, ["text"] = "%s створює робити копію самої себе!" },
    [881609253] = { ["english"] = { [1] = "Okay, here we go.  It's going to take about five minutes to shut this thing down through the ritual.  Once I start, keep the vermin off of me or it will be the end of us all!" }, ["npcs"] = { [1] = "Belnistrasz" }, ["priority"] = 1, ["text"] = "Гаразд, починаємо. Мені знадобиться близько п'яти хвилин на проведення ритуалу, який відключить цю річ. Коли я почну, тримайте цих почвар подалі від мене, інакше все це буде дарма!" },
    [881907244] = { ["english"] = { [1] = "So Hakkar has returned?" }, ["npcs"] = { [1] = "Exzhal" }, ["priority"] = 1, ["text"] = "То Гаккар повернувся?" },
    [882913432] = { ["english"] = { [1] = "Yes, I was able to reseal the relic, <name>." }, ["npcs"] = { [1] = "Aurora Skycaller" }, ["priority"] = 1, ["text"] = "Так, я змогла відновити реліквію, {ім'я:к}.#the relic, <name>." },
    [883031038] = { ["english"] = { [1] = "Killing you and your cohorts, <class>, will amuse me.  I shall make it quick." }, ["npcs"] = { [1] = "Lord Skwol" }, ["priority"] = 1, ["text"] = "Вбивство тебе і твоїх друзів, {клас:к}, розважить мене. Це буде швидко.#cohorts, <class>, will" },
    [890948796] = { ["english"] = { [1] = "Sentinels, come to my defense!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Вартові, захистіть мене!" },
    [892465876] = { ["english"] = { [1] = "Betsy! Give me Betsy back!" }, ["npcs"] = { [1] = "Donna" }, ["priority"] = 1, ["text"] = "Ні, Бетсі! Поверни мою Бетсі!" },
    [898116041] = { ["english"] = { [1] = "Where I come from, you get shanked for opening another inmate's cell door!" }, ["npcs"] = { [1] = "Crest Killer" }, ["priority"] = 1, ["text"] = "У мене на батьківщині вас би вже порізали за те, що ви зайшли без дозволу до чужої камери!" },
    [899937673] = { ["english"] = { [1] = "Ha ha! I have Betsy!" }, ["npcs"] = { [1] = "William" }, ["priority"] = 1, ["text"] = "Ха-ха! А Бетсі у мене!" },
    [902577064] = { ["english"] = { [1] = "Do you really need to ask? Can you not feel him? Has the almighty King Rastakhan sent his Servitor and Hand here on a mission of diplomacy?" }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Тобі справді потрібна моя відповідь? Хіба ти не відчуваєш його? Невже всемогутній король Растахан послав сюди своїх Слугу та Руку з дипломатичною місією?" },
    [90272537] = { ["english"] = { [1] = "Will these unrelenting Scourge attacks never end?" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Невже ці напади Скари ніколи не скінчаться?" },
    [906076514] = { ["english"] = { [1] = "Hi Corbett!  Here, you go!  I trust business is faring well at your clothier shop...?" }, ["npcs"] = { [1] = "Elaine Trias" }, ["priority"] = 1, ["text"] = "Привіт, Корбете! Ось, будь ласка! Сподіваюся, справи в крамниці йдуть добре?" },
    [909397099] = { ["english"] = { [1] = "You dare defile this holy ground?" }, ["npcs"] = { [1] = "Fallen Hero" }, ["priority"] = 1, ["text"] = "Як ти смієш оскверняти це священне місце?" },
    [91010602] = { ["english"] = { [1] = "The pylons that keep our island home anchored to the elemental plane of Skywall are failing. Zephras Isle--our home--is in grave danger." }, ["npcs"] = { [1] = "Rathiril Sunlance" }, ["priority"] = 3, ["text"] = "Пілони, що утримують наш острівний дім на стихійному плані Небесної Стіни, руйнуються. Острів Зефрас — наш дім — у смертельній небезпеці." },
    [912466555] = { ["english"] = { [1] = "Spirits of the wind... forgive me..." }, ["npcs"] = { [1] = "Windshaper Novice Seer" }, ["priority"] = 3, ["text"] = "Духи вітру... пробачте мені..." },
    [915344449] = { ["english"] = { [1] = "Your blood shall be the catalyst for the Old Gods' return!" }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "Твоя кров прискорить повернення Старих Богів!" },
    [916565176] = { ["english"] = { [1] = "%s places the spores within his alchemical instruments..." }, ["npcs"] = { [1] = "Apothecary Helbrim" }, ["priority"] = 1, ["text"] = "%s поміщає спори у свої алхімічні прилади..." },
    [917869544] = { ["english"] = { [1] = "This place is safe for the Defias to take over! Get the others." }, ["npcs"] = { [1] = "Defias Raider" }, ["priority"] = 1, ["text"] = "Це місце належатиме Непокірним! Поклич інших." },
    [919033059] = { ["english"] = { [1] = "Kill..." }, ["npcs"] = { [1] = "Thaddius" }, ["priority"] = 1, ["text"] = "Вбивати..." },
    [920112023] = { ["english"] = { [1] = "Bear witness to the undeniable power of your Warchief! Be lifted by the rallying cry of your dragon slayers!" }, ["npcs"] = { [1] = "Overlord Runthak" }, ["priority"] = 1, ["text"] = "Будьте свідками незаперечної сили вашого вождя! Сповнюйтесь рвучким кличем ваших драконоборців!" },
    [923000668] = { ["english"] = { [1] = "If I should fall, take my pouch. Make certain that it gets to the High General." }, ["npcs"] = { [1] = "Crimson Courier" }, ["priority"] = 1, ["text"] = "Якщо я поляжу — заберіть мою сумку. Переконайтеся, що вона потрапить до верховного генерала." },
    [925506138] = { ["english"] = { [1] = "Be on your guard!" }, ["npcs"] = { [1] = "Donova Snowden" }, ["priority"] = 1, ["text"] = "Будь насторожі!" },
    [928656847] = { ["english"] = { [1] = "What's that noise?" }, ["npcs"] = { [1] = "Defias Dockmaster" }, ["priority"] = 1, ["text"] = "Що це за шум?" },
    [929480681] = { ["english"] = { [1] = "TIMMY!" }, ["npcs"] = { [1] = "Timmy the Cruel" }, ["priority"] = 1, ["text"] = "ТІММІ!" },
    [931945215] = { ["english"] = { [1] = "%s paces back and forth in anticipation of the battle." }, ["npcs"] = { [1] = "Lord Victor Nefarius" }, ["priority"] = 1, ["text"] = "%s ходить взад-вперед в очікуванні битви." },
    [934092520] = { ["english"] = { [1] = "The young races? The infants? Humans? Orcs? Dwarves? You expect to defeat the Hakkari? To destroy a GOD?" }, ["npcs"] = { [1] = "Captured Hakkari Zealot" }, ["priority"] = 1, ["text"] = "Молоді раси? Ті немовлята? Люди? Орки? Дворфи? І ви збираєтесь перемогти Гаккарі? Знищити БОГА?" },
    [938002426] = { ["english"] = { [1] = "It's a rescue attempt!  Slay them all!" }, ["npcs"] = { [1] = "Dark Iron Kidnapper" }, ["priority"] = 1, ["text"] = "Вони намагаються врятувати оленя! Вбийте їх усіх!" },
    [938488838] = { ["english"] = { [1] = "What am I going to do?" }, ["npcs"] = { [1] = "Warden Thelwater" }, ["priority"] = 3, ["text"] = "Що ж мені тепер робити?" },
    [938667376] = { ["english"] = { [1] = "Ward yourself friend... dark magic is no game." }, ["npcs"] = { [1] = "Doan Karhan" }, ["priority"] = 1, ["text"] = "Бережи себе, {стать:друже:подруго}... темна магія — не забавка." },
    [943202087] = { ["english"] = { [1] = "Always so negative. The chances of that happening are between zero and none." }, ["npcs"] = { [1] = "Janey Anship" }, ["priority"] = 3, ["text"] = "Завжди ти про погане. Шанси на це — між нулем і ніякими." },
    [944656130] = { ["english"] = { [1] = "The fortune is mine, Alexi! Your end comes soon!" }, ["npcs"] = { [1] = "Weldon Barov" }, ["priority"] = 1, ["text"] = "Статок мій, Алексій! Тобі кінець!" },
    [945719626] = { ["english"] = { [1] = "That the fates should be so cruel as to permit us only this after a thousand years apart..." }, ["npcs"] = { [1] = "Cerellean Whiteclaw" }, ["priority"] = 1, ["text"] = "Невже доля настільки жорстока, що після тисячі років розлуки це все, що лишається нам..." },
    [947410581] = { ["english"] = { [1] = "We've done it! We won!" }, ["npcs"] = { [1] = "Daphne Stilwell" }, ["priority"] = 1, ["text"] = "Нам вдалося! Ми перемогли!" },
    [950254540] = { ["english"] = { [1] = "Only if I were about five feet taller, then I would show these blasphemous demons a thing or two! Help!" }, ["npcs"] = { [1] = "Rigger Gizelton" }, ["priority"] = 1, ["text"] = "Якби я був на кілька метрів вищий, то показав би цим клятим демонам! Рятуйте!" },
    [950549708] = { ["english"] = { [1] = "Turn back! Do not wake the dreamer!" }, ["npcs"] = { [1] = "Dreamscythe" }, ["priority"] = 1, ["text"] = "Забирайтесь геть! Не будіть Сновиду!" },
    [954147155] = { ["english"] = { [1] = "Oh, Darrowshire!  I would give a thousand lives for you!" }, ["npcs"] = { [1] = "Darrowshire Poltergeist" }, ["priority"] = 1, ["text"] = "О, Дарроушир! Я б віддав за тебе тисячу життів!" },
    [955498519] = { ["english"] = { [1] = "Masses of wolves are to the east, and whoever lived at Malden's Orchard is gone." }, ["npcs"] = { [1] = "Deathstalker Erland" }, ["priority"] = 1, ["text"] = "На сході звідси купа вовків, а в саду Мальдена вже нікого немає." },
    [956011982] = { ["english"] = { [1] = "Ahh, \"Mystical Conjurings of the Archmages of Dalaran.\" Perfect." }, ["npcs"] = { [1] = "Samantha Shackleton" }, ["priority"] = 1, ["text"] = "Ага, \"Містичні вичарування архімагів Даларану\". Ідеально." },
    [96004164] = { ["english"] = { [1] = "You do not belong in these gardens.  Your body shall nourish our lovely creations!" }, ["npcs"] = { [1] = "Celebrian Dryad" }, ["priority"] = 1, ["text"] = "Вам не місце в цих садах. Ваші тіла стануть поживою для цих прекрасних створінь!" },
    [961347096] = { ["english"] = { [1] = "KILL!!!" }, ["npcs"] = { [1] = "Bogling" }, ["priority"] = 1, ["text"] = "ВБИВАТИ!!!" },
    [962475951] = { ["english"] = { [1] = "I can't even visit my father's grave in peace anymore." }, ["npcs"] = { [1] = "Hogan Ference" }, ["priority"] = 3, ["text"] = "Я вже навіть не можу спокійно відвідати могилу свого батька." },
    [965763484] = { ["english"] = { [1] = "We've done it! We've done it! We've driven them off!" }, ["npcs"] = { [1] = "Daphne Stilwell" }, ["priority"] = 1, ["text"] = "Ми впорались! Вони вже не повернуться!" },
    [966186076] = { ["english"] = { [1] = "Now you feel pain..." }, ["npcs"] = { [1] = "Thaddius" }, ["priority"] = 1, ["text"] = "Тепер ви відчуваєте біль..." },
    [97473025] = { ["english"] = { [1] = "%s dies." }, ["npcs"] = {  }, ["priority"] = 1, ["text"] = "%s вмирає." },
    [978497094] = { ["english"] = { [1] = "Well, I'm off then.  Take care, Harlan." }, ["npcs"] = { [1] = "Corbett Schneider" }, ["priority"] = 1, ["text"] = "Ну, я пішов. Бережи себе, Гарлане." },
    [984586274] = { ["english"] = { [1] = "A-Me home! A-Me, good! Good A-Me. Home. Home. Home." }, ["npcs"] = { [1] = "A-Me 01" }, ["priority"] = 1, ["text"] = "Е-Мі вдома! Е-Мі хороша! Е-Мі хороша. Дім. Дім. Дім." },
    [987719060] = { ["english"] = { [1] = "Now, let's see... If I am correct, then... Hmmm..." }, ["npcs"] = { [1] = "J.D. Collie" }, ["priority"] = 1, ["text"] = "Такс, погляньмо... Якщо я не помиляюсь... Хммм..." },
    [989305921] = { ["english"] = { [1] = "Fall!" }, ["npcs"] = { [1] = "Witch Doctor Zum'rah" }, ["priority"] = 1, ["text"] = "Помри!" },
    [99773683] = { ["english"] = { [1] = "Alms for the poor?" }, ["npcs"] = { [1] = "Topper McNabb" }, ["priority"] = 1, ["text"] = "Милостиню бідному?" },
}
